window.TOOLBOX_CONTENT = {"introHtml":"\n<div class=\"meta-row\">\n    <span class=\"meta-badge\">Werkblad</span>\n    <span class=\"meta-badge\">Niveau 1 — het bestaande bedrijf</span>\n    <span class=\"meta-badge\">VIC · juni 2026</span>\n  </div>\n\n<h1>Veenweide<span>boeren</span> — toolbox</h1>\n\n<p style=\"font-size:15px;color:var(--text2);max-width:640px\">De bouwstenen waarmee de veenweideboer zijn bestaande bedrijf optimaliseert — per bouwsteen: wat het is, wat het doet, wat we weten en wanneer het toepasbaar is, met bronnen achterin.</p>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:0 0 2rem;font-size:12.5px;line-height:1.6\">\n    <strong style=\"display:block;margin-bottom:8px;font-size:13px\">Inhoud — 35 bouwstenen</strong>\n<p style=\"margin:.35rem 0\"><strong>Waterbeheer op het bedrijf</strong> — <a href=\"#greppelinfiltratie\" style=\"color:var(--accent);text-decoration:none\">Greppelinfiltratie</a> · <a href=\"#dynamisch-peilbeheer\" style=\"color:var(--accent);text-decoration:none\">Dynamisch peilbeheer</a> · <a href=\"#pwis-en-awis\" style=\"color:var(--accent);text-decoration:none\">PWIS en AWIS</a> · <a href=\"#druppelinfiltratie-dis\" style=\"color:var(--accent);text-decoration:none\">Druppelinfiltratie (DIS)</a> · <a href=\"#bevloeiing\" style=\"color:var(--accent);text-decoration:none\">Bevloeiing</a></p>\n<p style=\"margin:.35rem 0\"><strong>Sloot- en oeverbeheer</strong> — <a href=\"#slootmaaibeheer\" style=\"color:var(--accent);text-decoration:none\">Slootmaaibeheer</a> · <a href=\"#baggerbeheer\" style=\"color:var(--accent);text-decoration:none\">Baggerbeheer</a> · <a href=\"#oeverbeheer\" style=\"color:var(--accent);text-decoration:none\">Oeverbeheer</a> · <a href=\"#natuurvriendelijke-oevers\" style=\"color:var(--accent);text-decoration:none\">Natuurvriendelijke oevers</a> · <a href=\"#helofytenfilter\" style=\"color:var(--accent);text-decoration:none\">Helofytenfilter</a> · <a href=\"#rivierkreeftenbestrijding\" style=\"color:var(--accent);text-decoration:none\">Rivierkreeftenbestrijding</a></p>\n<p style=\"margin:.35rem 0\"><strong>Bodem en veen</strong> — <a href=\"#bodembeheer-en-bewaking\" style=\"color:var(--accent);text-decoration:none\">Bodembeheer en bewaking</a> · <a href=\"#draagkrachtbeheer\" style=\"color:var(--accent);text-decoration:none\">Draagkrachtbeheer</a> · <a href=\"#bekalken\" style=\"color:var(--accent);text-decoration:none\">Bekalken</a></p>\n<p style=\"margin:.35rem 0\"><strong>Grasland</strong> — <a href=\"#beweidingssystemen\" style=\"color:var(--accent);text-decoration:none\">Beweidingssystemen</a> · <a href=\"#grasrassen-en-doorzaaien\" style=\"color:var(--accent);text-decoration:none\">Grasrassen en doorzaaien</a> · <a href=\"#kruidenrijk-grasland\" style=\"color:var(--accent);text-decoration:none\">Kruidenrijk grasland</a> · <a href=\"#maaibeheer\" style=\"color:var(--accent);text-decoration:none\">Maaibeheer</a> · <a href=\"#rijpaden-en-licht-materieel\" style=\"color:var(--accent);text-decoration:none\">Rijpaden en licht materieel</a></p>\n<p style=\"margin:.35rem 0\"><strong>Bemesting</strong> — <a href=\"#stikstofbemesting\" style=\"color:var(--accent);text-decoration:none\">Stikstofbemesting</a> · <a href=\"#andere-mestsoorten-en-organische-stof\" style=\"color:var(--accent);text-decoration:none\">(Andere) mestsoorten en\norganische stof</a> · <a href=\"#fosfaatbeheer\" style=\"color:var(--accent);text-decoration:none\">Fosfaatbeheer</a></p>\n<p style=\"margin:.35rem 0\"><strong>Gewas en voer</strong> — <a href=\"#voederwinning-en-conservering\" style=\"color:var(--accent);text-decoration:none\">Voederwinning en\nconservering</a> · <a href=\"#eiwit-van-eigen-land\" style=\"color:var(--accent);text-decoration:none\">Eiwit van eigen land</a> · <a href=\"#rantsoen-op-maat\" style=\"color:var(--accent);text-decoration:none\">Rantsoen op maat</a></p>\n<p style=\"margin:.35rem 0\"><strong>Vee en dierenwelzijn</strong> — <a href=\"#koe-kalf-kudde\" style=\"color:var(--accent);text-decoration:none\">Koe-kalf-kudde</a> · <a href=\"#dynamisch-draadloos-weiden\" style=\"color:var(--accent);text-decoration:none\">Dynamisch draadloos weiden</a> · <a href=\"#passende-koe\" style=\"color:var(--accent);text-decoration:none\">Passende koe</a></p>\n<p style=\"margin:.35rem 0\"><strong>Stal en emissies</strong> — <a href=\"#ammoniakemissie\" style=\"color:var(--accent);text-decoration:none\">Ammoniakemissie</a></p>\n<p style=\"margin:.35rem 0\"><strong>Biodiversiteit en landschap</strong> — <a href=\"#weidevogelbeheer\" style=\"color:var(--accent);text-decoration:none\">Weidevogelbeheer</a> · <a href=\"#insectenbeheer\" style=\"color:var(--accent);text-decoration:none\">Insectenbeheer</a> · <a href=\"#mozaïekbeheer\" style=\"color:var(--accent);text-decoration:none\">Mozaïekbeheer</a> · <a href=\"#landschapselementen-onderhouden\" style=\"color:var(--accent);text-decoration:none\">Landschapselementen\nonderhouden</a></p>\n<p style=\"margin:.35rem 0\"><strong>Mechanisatie en energie</strong> — <a href=\"#elektrificatie\" style=\"color:var(--accent);text-decoration:none\">Elektrificatie</a> · <a href=\"#eigen-energieopwekking\" style=\"color:var(--accent);text-decoration:none\">Eigen energieopwekking</a></p>\n  </div>\n\n","categories":[{"id":"toolbox-01-water","naam":"Waterbeheer op het bedrijf","introHtml":"<p>Waterbeheer op het melkveebedrijf in het veenweidegebied omvat alles\nwat de grondwaterstand beïnvloedt: van greppelinfiltratiesystemen tot\npeilbeheer en druppelinfiltratie. De opgave is het veen vochtig houden\nzonder de bedrijfsvoering onmogelijk te maken.</p>","maatregelen":[{"titel":"Greppelinfiltratie","html":"<div class=\"ts\">WAT HET IS</div><p>Greppelinfiltratie is het permanent watervoerend houden van greppels\nin de zomerperiode (mei–oktober), zodat water vanuit de sloot of via een\npomp het perceel instroomt en de grondwaterstand stijgt. De techniek is\noud — boeren pasten hem in de jaren 50–70 al toe tegen verdroging — maar\nraakte in de vergetelheid door intensivering. Nu keert hij terug als\ngoedkope vernattingsmaatregel.</p><div class=\"ts\">WAT HET DOET</div><p>De grondwaterstand stijgt rondom de greppel. Bij een greppelafstand\nvan 6–9 meter is een zomergrondwaterstand van circa −40 cm onder\nmaaiveld haalbaar — de beleidsdrempel voor veenweidegebieden. Minder\nzuurstof bereikt de bodem, veenafbraak vertraagt, CO₂-emissie daalt.</p><div class=\"ts\">WAT WE WETEN</div><p>De vergelijking met waterinfiltratiesystemen is inmiddels goed\ngedocumenteerd (Hoving et al., 2022; Hoekstra et al., 2024):</p><ul>\n<li><p>Greppelinfiltratie verhoogt de grondwaterstand, maar\nongelijkmatig: vlak bij de greppel (0,5 m) tot −10 cm, midden op het\nperceel veel verder weg.</p></li>\n<li><p>WIS geeft een gelijkmatiger verhoging. Greppelinfiltratie is\ngoedkoper in aanleg maar minder effectief.</p></li>\n<li><p>Draagkracht direct naast de greppel blijft een groot deel van het\nseizoen onder de grenswaarde voor beweiding (0,7 MPa), met vertrapping\ntot gevolg.</p></li>\n<li><p>Dagelijks beheer is intensiever dan bij WIS. Twee keer per jaar\ngreppelen bleek nodig.</p></li>\n<li><p>Effect op CO₂-reductie is nog in onderzoek bij het NOBV\n(meetperiode 2024–2027; VIPNL, 2024).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Greppelinfiltratie past het beste bij extensieve percelen:\nvaarpolders, NNN-gebieden in agrarisch beheer, hooiland en\nknikpuntgebieden. Bij intensieve bedrijfsvoering is de kleine\ngreppelafstand te klein voor machines.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Plasdras —</strong> Een extreem vernatte greppel is een\nplasdras. Dat is geen neveneffect maar een bewuste keuze als\nweidevogelhabitat. De intensieve variant van greppelinfiltratie, met\neigen ANLb-vergoedingslogica.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Dynamisch draadloos weiden —</strong> GPS-onnauwkeurigheid\n(~5 m) botst met de gewenste greppelafstand (6–10 m). Open technisch\nvraagstuk.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Weidevogelbeheer —</strong> Nattere omstandigheden en\nextensiever graslandbeheer zijn gunstig voor weidevogels, zonder extra\ningreep.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: LEVERBOT</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Bij watervoerende greppels neemt het risico op leverbot (Fasciola\nhepatica) toe. Leverbotslakjes leven in natte, ondiepe plekken — precies\nde omstandigheden die greppelinfiltratie creëert. Geen reden om de\nmaatregel te vermijden, maar serieus beheervraagstuk: preventief\nbehandelen, monitoring veestapel, bewuste keuzes over beweiding nabij\nnatte greppels.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Hoving, I.E., Van Riel, J.W., Massop, H.T.L., Van\nHouwelingen, K. en Bijman, M. (2022).</strong> <em>Waterinfiltratie met\ndrukdrains en greppels voor veenbehoud en emissiereductie. Deelonderzoek\n'natte veeteelt' in het Innovatie Programma Veen (2018–2021).</em>\nWageningen Livestock Research, Rapport 1345.\nhttps://doi.org/10.18174/557763</p><p><strong>Hoekstra, N., Bestman, M., Pijlman, J., Honkoop, W., Van der\nWeijde, H. en Van Houwelingen, K. (2024).</strong>\n<em>Greppelinfiltratie als low-cost vernattingsmethode.</em> V-focus,\nnovember 2024, pp. 20–23. Louis Bolk Instituut / KTC Zegveld.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/greppelinfiltratie-als-low-cost-vernattingsmethode.pdf</p><p><strong>VIPNL (2024).</strong> <em>Themasheet Greppelinfiltratie —\nvoortgangsrapportage 2024.</em> Veenweiden Innovatie Programma\nNederland.\nhttps://vip-nl.nl/portfolio-item/themasheet-greppelinfiltratie/</p>"},{"titel":"Dynamisch peilbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Dynamisch peilbeheer is het actief sturen van het slootpeil binnen\neen vooraf vastgestelde boven- en ondergrens, afgestemd op\ngrondwaterstand, bodemvocht en weersverwachting. In tegenstelling tot\nhet klassieke systeem — een vast zomerpeil en een vast winterpeil —\nvarieert het slootpeil bewust mee met de seizoensomstandigheden. Het is\neen anticiperend systeem: er wordt niet gereageerd op wat er al is, maar\ngestuurd op wat er verwacht wordt. In de praktijk staat de maatregel in\ndelen van het land ook bekend als HAKLAM — Hoog Als het Kan, Laag Als\nhet Moet — een naam die het sturingsprincipe goed samenvat.</p><div class=\"ts\">WAT HET DOET</div><p>Door het slootpeil in de zomer hoger te zetten, wordt meer water het\nperceel ingestuwd via de sloot en — als ook WIS aanwezig is — via de\ndrains. Dat remt veenoxidatie en bodemdaling. In het voor- en najaar kan\nhet peil worden verlaagd om de draagkracht te verbeteren. Als losse\nmaatregel is het effect bescheiden; als aanvulling op WIS op\npolderniveau wordt het significant groter.</p><div class=\"ts\">WAT WE WETEN</div><p>De meest relevante onderzoeken dateren uit 2009–2022, wat op zichzelf\nveelzeggend is: na een reeks proeven is dynamisch peilbeheer als\nzelfstandige maatregel grotendeels verlaten. De kern (Nederlof, 2011;\nVan Doorn et al., 2012; HDSR, 2022):</p><ul>\n<li><p>De interactie tussen slootpeil en grondwaterstand in het midden\nvan een perceel is traag en beperkt. Na een peilwijziging duurt het\nweken voor het effect het midden van een 50-meter-breed perceel bereikt,\nen dan is het effect nog slechts 20–30%.</p></li>\n<li><p>Als losse maatregel reduceert dynamisch peilbeheer de bodemdaling\nmet slechts circa 2 mm per jaar (van 11 naar 9 mm). Te weinig om als\nzelfstandige maatregel te tellen.</p></li>\n<li><p>In combinatie met WIS op polderniveau werkt het wél (HDSR, 2022):\nin de droge zomer van 2020 konden grondeigenaren de grondwaterstand\nflink verhogen. Vereist intensieve samenwerking via een\nbegeleidingsgroep.</p></li>\n<li><p>Geen meetbaar effect op gewasopbrengst. Op draagkracht alleen\nbeperkt effect: perceel enkele dagen eerder betreedbaar door tijdelijke\npeilverlaging van 10–15 cm.</p></li>\n<li><p>Het systeem functioneert buiten de omslagperiodes weinig\ndynamisch: zomer staat het peil langdurig op het hoogste niveau, winter\nop het laagste.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Dynamisch peilbeheer is zinvol als aanvulling op WIS en op\npolderniveau georganiseerd, niet als individuele bedrijfsmaatregel.\nVereist coördinatie tussen alle grondeigenaren in een peilvak en een\nwaterschap dat bereid is mee te sturen.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>PWIS en AWIS —</strong> Dynamisch peilbeheer is pas echt\neffectief gecombineerd met WIS. Het slootpeil is het stuurmechanisme; de\ndrains zijn de verdelers. Zonder drains bereikt een peilwijziging het\nmidden van een perceel nauwelijks.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Coördinatie via collectieven —</strong> Eén boer kan het\npeil van een peilvak niet alleen bepalen. Dit is het schoolvoorbeeld van\neen maatregel die boer-boer-coördinatie op polderniveau vereist.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Bodem- en watermonitoring —</strong> Dynamisch peilbeheer\nzonder meetnet is sturen in het donker. Grondwaterstandsensoren per\nperceel of peilvak zijn de basis voor iedere peilbeslissing.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: OEVERAFKALVING</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Wisselende waterpeilen belasten slootkanten. Bij een hoger peil\nworden oevers nat en drassig; bij een lager peil drogen ze uit. Die\nwisseling versnelt oeverafkalving — een effect dat al na korte tijd\nzichtbaar was in de HDSR-proef (Van Doorn et al., 2012). Hoe steiler en\nzachter de oever, hoe groter het risico. De combinatie met natuurlijke\noevers (flauw talud, begroeiing) is een directe mitigerende\nmaatregel.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>STATUS EN CONTEXT</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Dat de relevante rapporten dateren uit 2009–2022 is geen toeval. Als\nzelfstandige maatregel leverde dynamisch peilbeheer te weinig op voor de\nforse beheerinspanning. Het onderzoek heeft zijn werk gedaan: niet door\nte bewijzen dat het werkt, maar door scherp te maken waar de grens ligt.\nDe opvolger — WIS en AWIS — heeft die beperkingen grotendeels opgelost.\nDynamisch peilbeheer op polderniveau, als aanvulling op WIS in\ncollectief verband, heeft wel degelijk toekomst.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Nederlof, L. (2011).</strong> <em>Eindrapport proef dynamisch\npeilbeheer.</em> Hoogheemraadschap De Stichtse Rijnlanden (HDSR), DM\n337361.\nhttps://www.veenweiden.nl/wp-content/uploads/2012/09/Proef-dynamisch-peilbeheer.pdf</p><p><strong>Van Doorn, A., Van Hardeveld, H. en Nederlof, L.\n(2012).</strong> <em>Toepassing dynamisch peilbeheer vereist\ninnovaties.</em> H2O — Tijdschrift voor waterbeleid en waterbeheer, nr.\n18, pp. 29–31. https://edepot.wur.nl/338979</p><p><strong>HDSR (2022).</strong> <em>Toekomstbestendige polder Lange\nWeide — polderbreed waterinfiltratiesysteem en dynamisch waterpeil:\nbevindingen en inzichten 2020/2021.</em> Hoogheemraadschap De Stichtse\nRijnlanden.\nhttps://www.hdsr.nl/buurt/bodemdaling/infiltratiebuizen-toekomstbestendige/nieuws/waterinfiltratie-dynamisch-peilbeheer/</p>"},{"titel":"PWIS en AWIS","html":"<p>Waterinfiltratiesystemen zijn de meest toegepaste en best\ngedocumenteerde vernattingsmaatregel in het Nederlandse veenweidegebied.\nZe bestaan in twee hoofdvarianten die op hetzelfde principe berusten\nmaar sterk verschillen in stuurbaarheid, kosten en\nonderhoudsintensiteit. PWIS en AWIS worden hier samen behandeld omdat ze\ndezelfde bouwsteen zijn in verschillende generaties.</p><div class=\"ts\">WAT HET IS</div><p><strong>PWIS — Passief Waterinfiltratiesysteem (vroeger:\nonderwaterdrainage)</strong></p><p>Drainbuizen aangelegd onder het slootpeil, zo’n 70 a 80 cm onder\nmaaiveld, met een drainafstand van 4–8 meter. De werking is passief: het\nhoogteverschil tussen slootpeil en grondwater drijft water de bodem in.\nIn de zomer infiltreert het systeem, in de winter draineert hetzelfde\nsysteem. Tegenwoordig vrijwel altijd aangelegd als samengestelde\ndrainage: drains lopen samen naar een centrale verzamelput die via één\naansluiting in de sloot uitkomt. Dit vermindert het aantal kwetsbare\neindbuizen en vergemakkelijkt onderhoud (Terwan et al., 2026).</p><p><strong>AWIS — Actief Waterinfiltratiesysteem (vroeger: drukdrainage\nof peilgestuurde onderwaterdrainage)</strong></p><p>Hetzelfde basisprincipe als PWIS, maar aangevuld met een\npompinstallatie op de verzamelput. De pomp verhoogt het waterpeil in de\nput ten opzichte van het slootpeil, waardoor water actiever en dieper\nhet perceel in wordt gestuwd. AWIS is onafhankelijk van het slootpeil te\nsturen — tot op perceelsniveau, geautomatiseerd op basis van\ngrondwaterstandmetingen of weersverwachting (KBF, 2020).</p><div class=\"ts\">WAT HET DOET</div><p>Beide systemen remmen de zomerse uitzakking van de grondwaterstand.\nDoor de grondwaterstand hoger te houden, blijft de veenlaag vochtig:\nminder zuurstof bereikt de veenbodem, veenoxidatie vertraagt,\nCO₂-emissie daalt en bodemdaling neemt af. Tegelijk wordt in natte\nperioden gedraineerd, wat de draagkracht herstelt. Dit\ntwee-richtingseffect — infiltreren in de zomer, draineren in de winter —\nis het kernvoordeel ten opzichte van eenvoudige peilverhoging (Hoving et\nal., 2008).</p><div class=\"ts\">WAT WE WETEN</div><p>Ruim twintig jaar onderzoek, van de eerste proeven op KTC Zegveld\n(2003) tot het lopende NOBV-programma, heeft een consistent beeld\nopgeleverd:</p><ul>\n<li><p><strong>Grondwaterstandsverhoging.</strong> PWIS verhoogt de\nzomergrondwaterstand gemiddeld 7–18 cm (tot 24 cm in het droge derde\nkwartaal). AWIS haalt 15–21 cm gemiddeld, oplopend tot 30 cm in Q3. AWIS\nis duidelijk effectiever in droge perioden (NOBV, 2024).</p></li>\n<li><p><strong>Bodemdaling en CO₂-reductie.</strong> Bij een slootpeil\nvan 35–40 cm kan met PWIS de maaivelddaling teruggebracht worden tot\ncirca 5 mm per jaar — een halvering. Het NOBV bevestigt dat de\ncombinatie van peilverhoging met onderwaterdrainage het beste resultaat\ngeeft (Hoving et al., 2008; NOBV, 2024).</p></li>\n<li><p><strong>Landbouwkundige effecten.</strong> WIS heeft geen\nnegatief effect op grasopbrengst (wel afhankelijk van de gws waar op\ngestuurd word). Draagkracht is gunstiger dan bij louter\nslootpeilverhoging doordat het systeem ook draineert (Hoving et al.,\n2008).</p></li>\n<li><p><strong>Heterogeniteit.</strong> \"Niets zo heterogeen als veen.\"\nEffectiviteit verschilt sterk per locatie: veentype, doorlatendheid,\nslootpeil en drainafstand bepalen samen hoeveel verhoging haalbaar is\n(KBF, 2020).</p></li>\n</ul><div class=\"ts\">PWIS VS AWIS — KEUZEOVERWEGINGEN</div><table>\n<colgroup>\n<col style=\"width: 27%\">\n<col style=\"width: 34%\">\n<col style=\"width: 37%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th></th>\n<th><strong>PWIS (passief)</strong></th>\n<th><strong>AWIS (actief)</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Verhoging zomer</strong></td>\n<td>7–18 cm gemiddeld</td>\n<td>15–21 cm gemiddeld</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Sturing</strong></td>\n<td>Afhankelijk van slootpeil</td>\n<td>Onafhankelijk, per perceel</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Aanlegkosten</strong></td>\n<td>Lager</td>\n<td>Hoger (pomp + installatie)</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Onderhoud</strong></td>\n<td>Lager</td>\n<td>Hoger (pomp, sensoren)</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Upgrade</strong></td>\n<td>Ja — later naar AWIS</td>\n<td>Eindsysteem</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: ONDERHOUD IS HET KNELPUNT</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>WIS is technisch bewezen, maar de praktijk laat zien dat onderhoud\nstructureel tekortschiet. Er zijn geen onderhoudsprotocollen, geen\nfinanciering en de KIWA-beoordelingsrichtlijn noemt slechts twee\nonderhoudswerkzaamheden. Verstoppingen van buizen en omhulsel,\nbeschadigde eindbuizen bij slootonderhoud en slecht functionerende\npompen zijn de meest voorkomende oorzaken van verminderde werking\n(Terwan et al., 2026).</td>\n</tr>\n<tr class=\"even\">\n<td>De samengestelde drainage is juist ontwikkeld om onderhoud te\nvereenvoudigen: minder eindbuizen, betere inspectie, en de put als\nbezinkput. Een goed werkend PWIS-systeem is bovendien eenvoudig op te\nwaarderen naar AWIS door een pomp toe te voegen — PWIS als gefaseerde\ninvestering.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Dynamisch peilbeheer —</strong> WIS en dynamisch peilbeheer\nzijn complementair. Het slootpeil is de voeding van PWIS; AWIS is\nonafhankelijk maar profiteert alsnog van een hoger polderpeil. De\ncombinatie geeft het meeste effect op polderniveau (NOBV, 2024).</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Bodem- en watermonitoring —</strong> Een\ngrondwaterstandmeetnet is noodzakelijk voor goed beheer van beide\nsystemen, zeker voor AWIS dat automatisch kan sturen.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Greppelinfiltratie —</strong> Voor extensieve of\nonbereikbare percelen waar WIS te kostbaar is, is greppelinfiltratie het\nalternatief. WIS voor intensievere percelen, greppelinfiltratie voor de\nranden.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Hoving, I.E., André, G., Van den Akker, J.J.H. en Pleijter,\nM. (2008).</strong> <em>Hydrologische en landbouwkundige effecten van\ngebruik 'onderwaterdrains' op veengrond.</em> Animal Sciences Group /\nWageningen UR, Rapport 102. https://edepot.wur.nl/165</p><p><strong>Deru, J., Lenssinck, F., Hoving, I., Van den Akker, J.,\nBloem, J. en Van Eekeren, N. (2014).</strong> <em>Effect\nonderwaterdrainage op bodemkwaliteit veenweiden.</em> V-focus. Louis\nBolk Instituut / Wageningen UR.\nhttps://www.louisbolk.nl/publicaties/effect-onderwaterdrainage-op-bodemkwaliteit-veenweiden</p><p><strong>KBF (2020).</strong> <em>Factsheet onderwater- en\ndrukdrainage — veelgestelde vragen over waterinfiltratiesystemen (versie\nmaart 2020).</em> Kenniscentrum Bodemdaling en Funderingen.\nhttps://www.kbf.nl/assets/uploads/2022/09/Onderwaterdrukdrainage-1.pdf</p><p><strong>NOBV (2024).</strong> <em>Jaarrapportage NOBV 2024 —\nmeetresultaten waterinfiltratiesystemen.</em> Nationaal\nOnderzoeksprogramma Broeikasgassen Veenweiden. www.nobveenweiden.nl</p><p><strong>Terwan, P., Honkoop, W. en Schaafsma, R. (2026).</strong>\n<em>Onderhoud van waterinfiltratiesystemen (WIS): activiteiten, kosten\nen organisatie.</em> VIPNL / VIC, Utrecht, maart 2026.\nhttps://vip-nl.nl/wp-content/uploads/V6700-VIPNL-Revisit-WIS-Onderhoud-WIS-2026-DEF.pdf</p><p><strong>VIPNL (2025).</strong> <em>Themasheet Revisit WIS.</em>\nVeenweiden Innovatie Programma Nederland.\nhttps://vip-nl.nl/portfolio-item/themasheet-revisit-wis/</p>"},{"titel":"Druppelinfiltratie (DIS)","html":"<p><strong>Fase:</strong> Vroeg experimenteel — pilots in Zegveld en\nLopikerwaard (2023–heden), haalbaarheidsstudie afgerond 2025,\nveldproeven lopend t/m 2027.</p><div class=\"ts\">WAT HET IS</div><p>Een Druppel Infiltratie Systeem (DIS) bestaat uit druppelslangen die\nondiep in de bovenste grondlaag worden aangebracht — typisch op 10 tot\n30 cm diepte — waarmee water actief en gecontroleerd in de veenbodem\nwordt geïnfiltreerd. De techniek (subsurface drip irrigation) is in de\nakker- en tuinbouw op zandgrond al een bewezen methode, maar de\ntoepassing op veengrond is nieuw. Het doel op veen is omgekeerd aan het\nlandbouwkundige gebruik op zand: niet de wortelzone optimaal vochtig\nhouden voor gewasgroei, maar het veen onder de wortelzone vernatten om\nzuurstofindringing en veenafbraak te beperken (Van Hateren &amp;\nHoogland, 2025).</p><div class=\"ts\">WAT HET DOET</div><p>DIS verhoogt het bodemvocht en de grondwaterstand rondom de\ndruppelslangen. Doordat water direct in de onverzadigde zone wordt\ningebracht — niet via de sloot — kan het systeem percelen vernatten die\nslecht bereikbaar zijn voor WIS of waar het slootpeil niet verhoogd kan\nworden. Bij lage druppelfluxen geeft het model een duidelijk vernattend\neffect met een gunstige invloed op CO₂-uitstoot. Bijkomend voordeel is\ndat het systeem grasgroei kan ondersteunen in droge perioden en dat\nbemesting via de slangen mogelijk is (Van Hateren &amp; Hoogland,\n2025).</p><div class=\"ts\">WAT WE WETEN</div><p>De kennis is nog beperkt maar groeit snel. De haalbaarheidsstudie\n(Acacia Water, 2025) heeft op basis van modelberekeningen met Hydrus2D\nde volgende hoofdbevindingen opgeleverd:</p><ul>\n<li><p><strong>Vernattend effect aangetoond.</strong> DIS kan bij lage\nfluxen een duidelijke verhoging van grondwaterstand en bodemvocht geven,\nook tussen de druppelslangen. CO₂-uitstoot daalt bij correcte\ndimensionering.</p></li>\n<li><p><strong>Balans is kritisch.</strong> Er is snel een risico op te\nnatte omstandigheden: bij ondiepe slangen (&lt;20 cm) en hoge fluxen kan\nmethaanvorming toenemen — en methaan heeft als broeikasgas een veel\ngroter opwarmend effect dan CO₂. Het netto klimaateffect kan dan\nnegatief worden.</p></li>\n<li><p><strong>Optimum voor gras ≠ optimum voor veen.</strong> Het\ndruppelregime dat gunstig is voor grasgroei hoeft niet samen te vallen\nmet het regime dat veenafbraak het best remt. Een strak beheer en goede\ndimensionering zijn essentieel.</p></li>\n<li><p><strong>Locatiespecifiek.</strong> Veentype, doorlatendheid en\ndrooglegging bepalen sterk hoe het systeem werkt. De haalbaarheidsstudie\nis verkennend en niet gekalibreerd op meetreeksen; veldproeven zijn\nnoodzakelijk voor uitspraken per locatie.</p></li>\n<li><p><strong>Eerste praktijkervaring positief.</strong> Een proefveld\nvan 0,3 ha in Zegveld (2023–2024) liet vernattende effecten zien.\nProeven worden uitgebreid naar het VIC-Innovatieveld en een bestaand\nDIS-veld in Polsbroek (Lopikerwaard) in 2026–2027.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>DIS is potentieel interessant voor percelen waar WIS moeilijk\naanlegbaar is (onregelmatige percelen, ongunstige verkaveling), percelen\nwaar het slootpeil niet verhoogd kan worden, en situaties waar een boer\nook grasgroei in droge perioden wil steunen. De maatregel is nog niet\ngrootschalig inzetbaar — eerst moeten de veldproeven de modeluitkomsten\nbevestigen en de dimensioneringsrichtlijnen worden vastgesteld.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: METHAANRISICO BIJ VERKEERDE\nTOEPASSING</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Het grootste risico bij DIS is onjuiste dimensionering. Bij te\nondiepe slangen en te hoge fluxen kan de grondwaterstand boven −20 cm\nstijgen, wat methaanvorming sterk bevordert. Methaan heeft als\nbroeikasgas een 28× hoger opwarmend vermogen dan CO₂ (over 100 jaar).\nEen systeem dat bedoeld is om klimaatschade te beperken kan daarmee het\nomgekeerde bewerkstelligen. Dit is precies waarom het onderzoek\nstapsgewijs werkt: haalbaarheidsmodel eerst, dan beperkte veldproeven,\ndan opschaling (Van Hateren &amp; Hoogland, 2025).</td>\n</tr>\n<tr class=\"even\">\n<td>Bemesting via de druppelslangen biedt kansen voor precisiebemesting\nmaar verhoogt in natte bodems ook het risico op lachgasvorming (N₂O, een\nkrachtig broeikasgas). Dit vraagt aanvullend onderzoek.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>PWIS en AWIS —</strong> DIS en WIS zijn complementair, niet\nconcurrerend. WIS werkt via de sloot en drains; DIS werkt direct in de\nonverzadigde zone en is onafhankelijk van het slootpeil. Voor percelen\nwaar WIS niet kan, is DIS een potentieel alternatief. De\ndimensioneringslogica verschilt fundamenteel.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Precisiebemesting —</strong> Bemesting via de druppelslangen\n(fertigation) biedt een directe koppeling naar de bouwsteen\nprecisiebemesting. Technisch al mogelijk; effecten op veenoxidatie en\nwaterkwaliteit nog te onderzoeken</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Bodem- en watermonitoring —</strong> Meer dan bij andere\nwatermaatregelen is een fijnmazig meetnet bij DIS essentieel: het\nsysteem reageert snel en de marge tussen optimaal en contraproductief is\nklein.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>STATUS: VROEG EXPERIMENTEEL</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>DIS staat op de innovatiefunnel van VIPNL in de fase 'verkenning en\nhaalbaarheid'. Er zijn eerste positieve signalen uit de praktijkproef in\nZegveld, een afgeronde haalbaarheidsstudie (2025) en een goedgekeurd\nonderzoeksplan voor 2026–2027. De maatregel is nog niet opgenomen in\nSOMERS. Grootschalige inzet is voorbarig zonder verdere veldvalidatie.\nDit onderscheidt DIS fundamenteel van greppelinfiltratie (vroege pilot)\nen WIS (bewezen maatregel).</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Van Hateren, T. en Hoogland, F. (2025).</strong>\n<em>Haalbaarheidsstudie DIS — potentiële effecten van druppelinfiltratie\nop veenafbraak.</em> Acacia Water, rapport 251603, 28 juli 2025. In\nopdracht van VIC/VIPNL (project V6800).\nhttps://vip-nl.nl/wp-content/uploads/Haalbaarheidsstudie-DIS.pdf</p><p><strong>VIC (2025).</strong> <em>Druppelinfiltratie — projectpagina\nen voortgangsrapportage 2025.</em> Veenweiden Innovatiecentrum / VIPNL.\nhttps://www.veenweiden.nl/activiteiten/druppelinfiltratie/</p><p><strong>VIPNL (2025).</strong> <em>Themasheet Druppel Infiltratie\nSysteem (DIS).</em> Veenweiden Innovatie Programma Nederland.\nhttps://vip-nl.nl/portfolio-item/themasheet-druppel-infiltratie-systeem-dis/</p>"},{"titel":"Bevloeiing","html":"<p><strong>Fase: M</strong>aatregel bij droogte — geen structurele\nbedrijfsmaatregel. Alleen inzetbaar waar voldoende watercapaciteit\nbeschikbaar is.</p><div class=\"ts\">WAT HET IS</div><p>Bevloeiing is het tijdelijk onder water zetten van een perceel door\nslootwater via pompen op het maaiveld te brengen. Het onderscheidt zich\nvan beregening door de hoeveelheid water en de duur: bij beregening\nwordt water gesproeid in kleine hoeveelheden, bij bevloeiing staat het\nperceel werkelijk blank. De techniek is in de Friese\nklei-op-veengebieden op grote schaal ingezet na muizenplagen (2014,\n2018/2019) en daarna door boeren overgenomen als droogtemaatregel.\nMinimaal 75 Friese boeren investeerden in een installatie; ruim 5.000\nhectare werd in 2020 bevloeid (Hoekstra &amp; Van Eekeren, 2023).</p><div class=\"ts\">WAT HET DOET</div><p>Bevloeiing verhoogt het grondwaterpeil scherp — meer dan 60 cm\nstijging is gemeten — en herstelt het bodemvochtgehalte op 10 en 20 cm\ndiepte. Na circa een maand zijn grondwaterstand en bodemvocht weer op\nhet niveau van vóór de bevloeiing. Het primaire effect is het opheffen\nvan hydrofobie: veengrond die te ver uitdroogt wordt waterafstotend en\nneemt geen water meer op. Bevloeiing kan die hydrofobie doorbreken\ndoordat de bodem gedurende langere tijd onder water staat, waarna\nregenval weer opgenomen wordt. Beregening alleen is daarvoor\nonvoldoende.</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Grasopbrengst.</strong> Bevloeiing na de eerste snede\nverdubbelde de drogestofopbrengst van de tweede snede (van 1.690 naar\n3.550 kg DS/ha bij 250 kg N). Op jaarbasis was het effect beperkt — geen\nsignificant meerjarig voordeel (Hoekstra &amp; Van Eekeren,\n2023).</p></li>\n<li><p><strong>Timing is bepalend.</strong> Bevloeien loont alleen vroeg\nin het seizoen. Boeren geven aan dat bevloeien na juni niet meer loont:\nde effecten werken door tot in de herfst en leiden tot natte,\nonbegaanbare percelen laat in het jaar (Hoekstra &amp; Van Eekeren,\n2023).</p></li>\n<li><p><strong>Voederwaarde.</strong> De hogere opbrengst na bevloeiing\nging deels ten koste van de voederwaarde: lagere VEM- en RE-gehalten.\nDit is een relevante afweging voor het rantsoen.</p></li>\n<li><p><strong>Hydrofobie en scheurvorming.</strong> Op\nklei-op-veenpercelen kunnen scheuren ontstaan bij extreme droogte.\nBevloeiing trekt scheuren dicht en herstelt de wateropname van de bodem\n— een effect dat met beregening niet te bereiken is (Hoekstra et al.,\n2020).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Bevloeiing is alleen zinvol bij: (1) extreme droogte met risico op\nhydrofobie of scheurvorming; (2) voldoende pompcapaciteit (minimaal 800\nm³/uur); (3) voldoende slootwater van voldoende kwaliteit; (4) inzet\nvóór of direct na de eerste snede. Op zuiver veenpercelen zonder\nkleicomponent is het risico op hydrofobie kleiner; op klei-op-veen is\nhet risico groter en het effect van bevloeiing daarmee groter.</p><blockquote>\n\n</blockquote>","lit":"<p><strong>Hoekstra, N. en Van Eekeren, N. (2023).</strong>\n<em>Bevloeiing van veenweidegrasland.</em> V-focus, januari 2023, pp.\n32–35. Louis Bolk Instituut.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/bevloeiing-van-veenweidegrasland.pdf</p>"}]},{"id":"toolbox-02-sloot","naam":"Sloot- en oeverbeheer","introHtml":"<p>De veenweidesloot is geen randverschijnsel van het bedrijf — hij is\nonderdeel van het systeem. Samen beslaan sloten en oevers in het\nveenweidegebied een groot deel van het totale oppervlak. De toestand is\nslechter dan verwacht: uit onderzoek op bijna 200 sloten (VeeST, 2025)\nblijkt dat watervegetatie schaars is, slib dik en nutriëntenrijk, oevers\nonderholt en draagkracht beperkt. Tegelijk is dit het deel van het\nbedrijf waar met relatief eenvoudige beheerkeuzes structurele winst te\nboeken valt op waterkwaliteit, biodiversiteit en oeverstabiliteit.</p><blockquote>\n<p><strong>Belangrijk kader:</strong> VeeST (Veenweidesloot van de\nToekomst) is het lopende onderzoeksprogramma (2023–2026) dat al deze\nbouwstenen integraal bestudeert. De resultaten zijn nog niet af — de\ntussenrapportage van januari 2026 geeft een eerste beeld maar de\nbeheerexperimenten lopen nog een jaar door. De bouwstenen hieronder zijn\ngebaseerd op de stand van kennis medio 2025, aangevuld met ouder\nonderzoek. Eindbevindingen van VeeST kunnen onderdelen herzien of\naanscherpen.</p>\n</blockquote>","maatregelen":[{"titel":"Slootmaaibeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Het maaien van watervegetatie in de sloot en het beheer van de\ndirecte slootkant (insteek). In de gangbare praktijk wordt jaarlijks\ngemaaid, vaak volledig en in één keer. Het wenselijke alternatief is\ngefaseerd, terughoudend beheer op basis van het principe 'niets doen,\ntenzij noodzakelijk' — noodzakelijk betekent: water aan- en afvoer\nwaarborgen of nutriënten uit het systeem verwijderen (Van Rotterdam et\nal., 2026).</p><div class=\"ts\">WAT HET DOET</div><p>Watervegetatie is de motor van een gezonde sloot: planten zuiveren\nwater, leveren zuurstof, bieden habitat voor insecten, amfibieën en\nvissen, en stabiliseren de waterbodem. Jaarlijks volledig maaien\nvernietigt die structuur steeds opnieuw. Gefaseerd maaien — nooit meer\ndan de helft van de sloot tegelijk, en niet elk jaar — laat de vegetatie\nzich herstellen en geeft biodiversiteit een kans. Maaisel afvoeren is\nbij voedselrijke sloten essentieel: nutriënten die in de plant zitten\nworden anders teruggebracht in het systeem.</p><div class=\"ts\">WAT WE WETEN</div><p>De VeeST-tussenrapportage (2026) geeft het scherpste beeld ooit van\nde huidige toestand:</p><ul>\n<li><p>In 27% van de onderzochte sloten ontbreekt watervegetatie\nvolledig of is slechts één soort aanwezig. Kroos domineert. De\ndiversiteit van waterplanten is in de meeste gebieden beperkt (Van\nRotterdam et al., 2026).</p></li>\n<li><p>De slechte toestand wordt deels verklaard door een negatieve\nvicieuze cirkel: algengroei door hoge nutriëntenbelasting → beperkt\ndoorzicht → geen waterplanten → fosfornalevering uit slib → meer\nalgengroei. Beheer doorbreekt deze cirkel niet snel, maar kan hem\nstabiliseren.</p></li>\n<li><p>Sloten worden matig tot vrij intensief beheerd. Zowel oever als\nslootvegetatie wordt jaarlijks gemaaid. Baggeren vindt 1 keer per 2–5\njaar plaats (Van Rotterdam et al., 2026).</p></li>\n<li><p>Beheerders die voor de experimenten zijn geïnterviewd bevestigen\ndat terughoudend beheer (niets doen, tenzij) mogelijk is maar vraagt om\naanpassing in de legger en schouwpraktijk van het waterschap.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Op alle sloten in het veenweidebedrijf, maar de aanpak verschilt per\nsloottypologie. VeeST onderscheidt zes sloottypes op basis van veentype,\ndrooglegging, kweldruk en ruimtelijke context. Gefaseerd maaibeheer\nwerkt het best als de watervegetatie al enige kwaliteit heeft; bij sterk\ngedegradeerde sloten zijn eerst herstelmaatregelen nodig.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Baggerbeheer —</strong> Slootmaaibeheer en baggerbeheer zijn\nonlosmakelijk verbonden: te intensief maaien versnelt baggeraanwas;\nbaggeren te vroeg na maaien haalt net herstelde vegetatie weg.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Rivierkreeftenbestrijding —</strong> Rivierkreeften\nvernietigen watervegetatie actief. Terughoudend slootmaaibeheer heeft\nweinig effect zolang kreeften waterplanten opeten en kapotknijpen.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Deru, J. en Van Eekeren, N. (2016).</strong> <em>Dikke\nfractie gescheiden drijfmest is alternatief voor ruige mest — mest voor\nweidevogelgebieden in veenweiden.</em> V-focus, april 2016, pp. 28–29.\nLouis Bolk Instituut / VIC.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/3117.pdf</p>"},{"titel":"Baggerbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Het verwijderen van slib (bagger) uit de sloot. In de gangbare\npraktijk wordt om de 2–5 jaar gebaggerd, vaak met zwaar materieel en\nzonder rekening te houden met het slibprofiel of de\nnutriëntensamenstelling. Goed baggerbeheer kiest het juiste moment, de\njuiste diepte en de juiste methode — en verwerkt het slib zodanig dat\nnutriënten niet direct terugkomen in het systeem.</p><div class=\"ts\">WAT HET DOET</div><p>Slib is het archief van de veenweidesloot: het bevat alle nutriënten\ndie in decennia zijn neergeslagen uit bemesting, afkalving en\nplantenresten. Een dikke sliblaag vermindert de waterdiepte, belemmert\nlichtdoorval en draagt bij aan de vicieuze cirkel van algendominantie.\nBaggeren is noodzakelijk om sloten op diepte te houden en nutriënten\nstructureel uit het systeem te verwijderen — maar verkeerd baggeren\nversnelt oeverafkalving en beschadigt de watervegetatie.</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p>In de helft van de onderzochte sloten is de slibdikte meer dan\n1,2 meter. De samenstelling is ongunstig: hoge fosfaatbeschikbaarheid en\nstikstofconcentraties die voor de meeste planten toxisch zijn (Van\nRotterdam et al., 2026).</p></li>\n<li><p>Het 'tompouce-effect' is een belangrijke maar onderschatte bron\nvan slib: de wortelzone van de oever (bovenste 5–10 cm) heeft enige\ndraagkracht, maar daaronder is de veenlaag vrijwel draagkrachteloos.\nOnder normale omstandigheden schuift dit zachte veenmateriaal de sloot\nin. Dit verklaart voor een deel de dikke sliblaag (Van Rotterdam et al.,\n2026).</p></li>\n<li><p>Meer dan 95% van de onderzochte sloten heeft enige onderholling.\nIn de helft kan een stok meer dan 25 cm horizontaal onder de\nterrestrische oever worden geduwd. Baggeren met zwaar materieel langs\ndergelijke oevers verergert dit.</p></li>\n<li><p>Baggeren verwijdert slib maar ook habitat. Te frequent baggeren\n(&lt; 2 jaar) geeft watervegetatie geen kans om zich te herstellen. Het\noptimum ligt locatiespecifiek.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Baggeren is vaak noodzakelijk maar de frequentie, diepte en methode\nhangen af van de toestand van de sloot. VeeST werkt aan een\nafwegingskader dat 'niets doen, tenzij' ook voor baggerbeheer\noperationaliseert. Bij sloten met ernstige onderholling moet baggeren\nworden gecombineerd met oeverherstel — anders is het effect\ntijdelijk.</p>","lit":null},{"titel":"Oeverbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Het beheer van de oever — de overgangszone tussen perceel en sloot —\nomvat maaibeheer van het talud, bescherming van de oever tegen\nvertrapping door vee, en inrichtingskeuzes (talud steilheid,\nbegroeiingstype). Veebescherming is het voorkomen dat koeien direct op\nde oever drinken of weiden, door uitrastering of drinkbakken.</p><div class=\"ts\">WAT HET DOET</div><p>Oevervegetatie bepaalt voor een groot deel de stabiliteit van de\nslootkant. Stevige, diep wortelende oeverplanten verankeren de veenlaag\nen bieden weerstand tegen erosie. Tegelijk absorberen ze nutriënten die\nafspoelen van het perceel. Vee dat direct op de oever loopt vertrapt de\nvegetatie, veroorzaakt instabiliteit en draagt bij aan het\ntompouce-effect. Uitrasteren met een drinkbak op afstand is een\neenvoudige maar effectieve maatregel (VeeST werksessies, 2026).</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p>In 2/3 van de onderzochte sloten drinken koeien direct vanaf de\noever uit de sloot. In slechts 1/3 is een drinkbak of drinkplaats\nbeschikbaar (Van Rotterdam et al., 2026).</p></li>\n<li><p>De amfibische oeverzone is soortenarm. De dominante soorten\npassen bij voedselrijke sloten. In de vochtige oeverzone boven de\nwaterlijn zijn relatief veel landplanten aanwezig die niet\ninundatietolerant zijn: bij peilverhoging zouden deze afsterven en de\noeverstabiliteit verminderen (Van Rotterdam et al., 2026).</p></li>\n<li><p>Er bestaat een doelconflict: weidevogels zijn gebaat bij lage\ngras/kruidenvegetatie, maar voor oeverstabiliteit en inundatietolerantie\nbij hogere peilen is juist hogere, structuurrijke, stevig wortelende\noevervegetatie nodig (Van Rotterdam et al., 2026).</p></li>\n<li><p>Uitrasteren van oevers gecombineerd met minimaal oeverbeheer\ngeeft vegetatie de kans zich te ontwikkelen naar hogere oeverplanten die\nde oever beter verankeren. Dit is een van de behandelingen in de\nVeeST-beheerexperimenten.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Op alle percelen waar vee toegang heeft tot de oever. Uitrasteren is\nde meest direct effectieve maatregel en relatief goedkoop. Het vraagt\neen aanpassing in beweidingsbeheer en plaatsing van drinkpunten. Bij\nANLb-pakketten voor weidevogels of slootkantbeheer is uitrastering soms\nal vereist of vergoed.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Natuurvriendelijke oevers —</strong> Waar de oever\nstructureel instabiel is (ernstige onderholling, steil talud) is\nuitrasteren en beheer alleen niet voldoende. Dan zijn\ninrichtingsmaatregelen nodig — met de kanttekening dat dit op veen\nwezenlijk complexer is dan op klei (zie bouwsteen Natuurvriendelijke\noevers).</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Dynamisch draadloos weiden —</strong> GPS-gestuurd weiden\nmaakt het mogelijk om koeien van oevers en greppels weg te houden zonder\nfysieke afrastering. Daarmee is het een directe technologische variant\nop uitrasteren: flexibeler, maar afhankelijk van de nauwkeurigheid van\nhet GPS-systeem (momenteel ~5 m). Op percelen met sloten op korte\nonderlinge afstand is de combinatie met smalle greppelafstanden lastig\nte sturen.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Dynamisch peilbeheer —</strong> Hogere en flexibelere peilen\nbelasten oevers extra. Oeverbeheer dat inzet op inundatietolerant\nplantmateriaal is een directe voorbereiding op de vernatte\nsituatie.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th>Verplicht per 1 maart 2023 (GLB + mestwetgeving). Breedte: 5 m langs\necologisch kwetsbare waterlopen en KRW-waterlichamen &gt; 10 m breed;\n1–3 m langs overige waterlopen. Als de bufferstrook meer dan 4% van het\nperceel beslaat, mag de breedte worden teruggebracht naar 1 meter.\nVergoeding via ANLb-pakket 'Bufferstrook met kruiden langs grasland'.\nMaaisel afvoeren is bij ANLb-pakketten verplicht — dit verwijdert actief\nnutriënten uit het systeem (RVO, 2023).</th>\n</tr>\n</thead>\n<tbody>\n</tbody>\n</table>","lit":"<p><strong>Van Rotterdam, D., Verhofstad, M., Moria, L., Koppenaal, E.,\nVerweij, J., Egas, Y., Jansen, E. en Thijssen, M. (2024).</strong>\n<em>Veenweidesloot van de Toekomst — resultaten inventarisatie\n(verkenningsfase).</em> VIPNL / VIC, januari 2024.\nhttps://vip-nl.nl/wp-content/uploads/Concept-tussenrapportage-Veenweidensloot-1.pdf</p><p><strong>Van Rotterdam, D., Verhofstad, M., Moria, L., Koppenaal, E.,\nVerweij, J., Sikking, F., Egas, Y., Jansen, E. en Thijssen, M.\n(2026).</strong> <em>Tussenrapportage Veenweidesloot van de\nToekomst.</em> VIPNL / VIC, rapport pp. 91, januari 2026.\nhttps://vip-nl.nl/wp-content/uploads/Tussenrapportage-VeeST-2025-260512.pdf</p><p><strong>VIPNL (2025).</strong> <em>Themasheet Veenweidesloot van de\nToekomst (VeeST).</em> Veenweiden Innovatie Programma Nederland.\nhttps://vip-nl.nl/portfolio-item/themasheet-veenweidesloot-van-de-toekomst/</p>"},{"titel":"Natuurvriendelijke oevers","html":"<p><strong>Belangrijk voorbehoud:</strong> Wat op klei of zand goed\nwerkt, werkt op veen fundamenteel anders. De toepasbaarheid van\n'klassieke' natuurvriendelijke oevers in het veenweidegebied is beperkt\nen vraagt een eigen aanpak.</p><div class=\"ts\">WAT HET IS</div><p>Een natuurvriendelijke oever is in de standaarddefinitie een oever\nmet een flauwe hellingshoek (flauw talud), begroeid met\ninundatietolerant plantenmateriaal. Het concept is ontwikkeld voor\noevers op klei, zand of leem — bodems die een flauw talud structureel\nkunnen vasthouden. Op veen is dat een wezenlijk ander verhaal.</p><div class=\"ts\">WAAROM VEEN ANDERS IS</div><p>De veenbodem heeft een wortelzone van slechts 5–10 cm met enige\ndraagkracht. Daaronder is het veen vrijwel draagkrachteloos. Dit heeft\ntwee directe consequenties voor oeverinrichting:</p><ul>\n<li><p>Een flauw talud aanleggen op veen vereist dat je veenmateriaal\nafgraaft of verplaatst. Dat materiaal heeft geen cohesie en schuift\nterug of weg zodra je ermee werkt. De aanleg is arbeidsintensief,\nkostbaar en het resultaat is fragiel.</p></li>\n<li><p>Het tompouce-effect: de oeverwortelzone houdt enigszins stand,\nmaar de zachte veenlaag eronder schuift langzaam de sloot in — óók na\ninrichting. Een 'herstelde' oever kan na enkele jaren opnieuw instabiel\nzijn als het onderliggende veen blijft wegschuiven.</p></li>\n<li><p>Op klei kun je een eenmaal aangelegd flauw talud jarenlang met\nalleen beheer in stand houden. Op veen vergt dat structureel meer\naandacht en is de levensduur van een ingreep korter.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p>Meer dan 95% van de onderzochte veenweidesloten heeft enige\nonderholling. In de helft kan een stok meer dan 25 cm horizontaal onder\nde terrestrische oever worden geduwd. Dit probleem is inherent aan veen\nen niet snel op te lossen (Van Rotterdam et al., 2026).</p></li>\n<li><p>Het VeeST-afwegingskader hanteert als uitgangspunt: beheer eerst,\ninrichting alleen als het echt niet anders kan. Dit geldt des te meer op\nveen, waar de kosten van inrichting hoog zijn en de effectiviteit op\nlangere termijn onzeker.</p></li>\n<li><p>Flauwe taluds verminderen wel degelijk de aantrekkelijkheid voor\nrivierkreeften — die bij steile wanden makkelijker gangen graven. Dit\neffect is op kleioevers goed gedocumenteerd; of en hoe het werkt op\nzachte veenoevers is minder duidelijk (STOWA, 2025).</p></li>\n<li><p>Alternatieve inrichtingsvormen die beter aansluiten op veen zijn:\ndrijvende oevermatten, inzaaien van stevige oeverplanten (grote\nlisdodde, riet, zegge) op de bestaande oever zonder grote\ngrondverzetting, en uitrasteren zodat vegetatie zich van nature kan\nontwikkelen. Dit zijn minder radicale ingrepen die het veen minder\ndestabiliseren.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>De vraag op veen is niet 'hoe leg ik een natuurvriendelijke oever\naan?' maar 'wat is de minst invasieve ingreep die de oever voldoende\nstabiliseert?' Dat begint met uitrasteren en terughoudend oeverbeheer\n(zie bouwsteen Oeverbeheer). Alleen bij acute instabiliteit of ernstige\nonderholling waarbij beheer aantoonbaar niet voldoet, zijn actieve\ninrichtingsmaatregelen aan de orde — altijd in overleg met het\nwaterschap en bij voorkeur met subsidiering.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Oeverbeheer en veebescherming —</strong> Op veen is dit de\neerste stap, vóór inrichting. Uitrasteren en terughoudend maaibeheer\ngeven oevervegetatie de kans om de oever te versterken zonder\ngrondverzetting.</td>\n</tr>\n<tr class=\"even\">\n<td></td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Dynamisch peilbeheer —</strong> Hogere en flexibelere peilen\nbelasten veenoevers extra. Inundatietolerant plantmateriaal is ook op\nveen wenselijk — maar de lat voor actieve inrichting moet hoger liggen\ndan op klei of zand.</td>\n</tr>\n</tbody>\n</table>","lit":null},{"titel":"Helofytenfilter","html":"<div class=\"ts\">WAT HET IS</div><p>Een helofytenfilter is een ondiepe oeverstrook of apart filterbekken\nbeplant met rietachtige oeverplanten (helofyten: riet, kleine lisdodde,\ngrote lisdodde) waar water heen wordt geleid voordat het de sloot\nbereikt. De planten nemen nutriënten op, het slib bezinkt, en de\nmicrobische activiteit in de wortelzone breekt organische stoffen\naf.</p><div class=\"ts\">WAT HET DOET</div><p>Helofytenfilters retineren fosfaat, stikstof en zwevende deeltjes uit\nhet afstromende perceel- en drainagewater. De effectiviteit hangt sterk\naf van de hydraulische belasting (hoeveel water per oppervlakte filter),\nde verblijftijd en het seizoen. Bij lage belasting en voldoende\nverblijftijd zijn retentiepercentages voor totaal-fosfor van 40–70%\nhaalbaar; voor totaal-stikstof 30–60%. Bijkomend voordeel: het filter\nbiedt habitat voor insecten, amfibieën en weidevogels (gecombineerde\nwerking met weidevogelbeheer).</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p>Helofytenfilters zijn in de agrarische praktijk bewezen als\nonderdeel van erf- en erfafwateringsaanpak, maar grootschalige\ntoepassingen langs veenweidepercelen zijn minder\ngedocumenteerd.</p></li>\n</ul><blockquote>\n<p>Onderhoud is het aandachtspunt: filters slibben dicht en moeten\nperiodiek worden gemaaid en het maaisel afgevoerd. Onvoldoende onderhoud\nvermindert de effectiviteit en keert nutriënten terug in het\nsysteem.</p>\n</blockquote><ul>\n<li><p>De helofytenfilter staat in het visiedocument als inkomstenstroom\n(niveau 2) wanneer hij functioneert als productie-installatie voor\nschoon slootwater — dan is het een dienst die vergoed kan worden via een\nprestatiecontract met het waterschap (KRW-doelen).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Bij percelen met drainuitlopen direct op de sloot, bij hoge\nnutriëntenbelasting van perceel naar sloot, en bij sloten die al dicht\nbij een KRW-doelstelling liggen waarbij de resterende opgave met een\nfilter te overbruggen is. Niet als vervanging van bufferstroken maar als\naanvulling — zeker bij veenweidepercelen waar oppervlakkige afspoeling\nbeperkt is maar drainage-uitstroom hoog.</p>","lit":null},{"titel":"Rivierkreeftenbestrijding","html":"<p><strong>Fase:</strong> Urgent en landelijk erkend probleem —\nbestrijdingsopties zijn beperkt en de verantwoordelijkheidsverdeling\ntussen Rijk en waterschappen is niet opgelost (stand van zaken mei\n2026).</p><div class=\"ts\">WAT HET IS</div><p>De Amerikaanse rivierkreeft (Procambarus clarkii) en de rode\nrivierkreeft zijn invasieve exoten die in de jaren 80 in Nederland\nbelandden. Ze zijn in de loop van de 21e eeuw explosief gegroeid, met\nname in het veenweidegebied van West-Nederland. Ze graven gangen in\noevers en dijken, eten waterplanten op en knippen ze kapot, woelen de\nwaterbodem los en maken het water troebel. Ze zijn de meest genoemde\nveroorzaker van het verstoorde veenweideslootsysteem in de\nVeeST-werksessies (2026) — door boeren, loonwerkers én\nwaterschappers.</p><div class=\"ts\">WAT HET DOET — DE SCHADE</div><p>Rivierkreeften ondermijnen vrijwel elke andere bouwsteen in deze\ncategorie:</p><ul>\n<li><p>Watervegetatie die via terughoudend slootmaaibeheer herstelt,\nwordt actief verwijderd door kreeften.</p></li>\n<li><p>Oevers die via oeverbeheer worden gestabiliseerd, worden van\nbinnenuit ondermijnd door graafgangen.</p></li>\n<li><p>De oplosbaarheid van fosfaat neemt toe door het woelen, wat de\nvicieuze cirkel van algendominantie versterkt.</p></li>\n<li><p>Bij dijken vormen graafgangen een waterveiligheidsrisico;\nmeerdere waterschappen voeren al actieve vangstprogramma's uit\n(Delfland, STOWA, 2025).</p></li>\n</ul><div class=\"ts\">WAT WE WETEN OVER BESTRIJDING</div><ul>\n<li><p>Alleen beroepsvissers mogen de kreeften met fuiken of\nkreeftenkorven vangen en verhandelen (stand 2023–2026). Sportvissers\nmogen alleen met hengel vissen. Massaal wegvangen is logistiek en\nfinancieel intensief.</p></li>\n<li><p>Hoogheemraadschap Delfland is in 2026 eigenmachtig begonnen met\ngrootschalige vangst (€7 mln) en wil de kosten verhalen op het Rijk. Het\nRijk is niet van plan te betalen. De verantwoordelijkheidsverdeling is\neen open conflict (NOS Nieuwsuur, 2026).</p></li>\n<li><p>Preventie via habitatvermindering is kansrijker dan bestrijding\nna vestiging: meer in water meer rijke vegetatie en flauwe taluds bieden\nminder geschikte habitat voor graafgedrag (STOWA Deltafact\nRivierkreeften, 2025).</p></li>\n<li><p>De invasieve soorten staan op de EU-Unielijst (ongewenste exoten)\n— er is een nationale verplichting tot bestrijding, maar de uitvoering\nis niet geregeld en het budget ontbreekt (STOWA, 2025).</p></li>\n</ul><div class=\"ts\">WAT DE BOER KAN DOEN</div><p>Directe bestrijding door de boer is beperkt door de wetgeving. Wat\nwél kan: (1) Uitrasteren van oevers zodat vee ze niet verder vertrapt —\ndit bevordert vegetatieherstel dat de oever geleidelijk sterker maakt en\nminder aantrekkelijk voor kreeften. (2) Melden bij waterschap en\nbijhouden van waar kreeften worden waargenomen. (3) Samenwerken met\ngebiedscollectief voor gecoördineerde vangstacties als wetgeving dat\ntoestaat. Let op: aanleg van natuurvriendelijke oevers als preventieve\nmaatregel wordt wel aangehaald in de literatuur, maar op veengrond is de\nhaalbaarheid beperkt — zie bouwsteen Natuurvriendelijke oevers.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>STATUS: URGENT MAAR ONOPGELOST</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Rivierkreeften zijn in 2026 het grootste aandachtspunt voor\nveenweidesloten dat buiten de directe invloedssfeer van de individuele\nboer valt. Waterschappen, provincies en ministerie wijzen naar elkaar.\nZonder nationale regie en budget blijft bestrijding fragmentarisch. Voor\nde boer geldt: focus op wat je kunt beïnvloeden (habitat verminderen,\nverspreiding voorkomen, melden) en reken er niet op dat het probleem op\nkorte termijn is opgelost.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>STOWA (2025).</strong> <em>Deltafact Rivierkreeften — update\n2025.</em> Stichting Toegepast Onderzoek Waterbeheer.\nhttps://www.stowa.nl/deltafacts/waterveiligheid/beoordelen-waterkeringen/rivierkreeften-update-2025</p><p><strong>Unie van Waterschappen (2023).</strong> <em>Amerikaanse\nrivierkreeft — landelijk probleem, nationale aanpak gevraagd.</em>\nhttps://unievanwaterschappen.nl/category/waterveiligheid/amerikaanse-rivierkreeft/</p><p><strong>NOS Nieuwsuur (2026).</strong> <em>Waterschap gaat strijd aan\nmet rivierkreeft en legt rekening bij Rijk.</em> NOS, april 2026.\nhttps://nos.nl/nieuwsuur/artikel/2610631-waterschap-gaat-strijd-aan-met-rivierkreeft-en-legt-rekening-bij-rijk</p>"}]},{"id":"toolbox-03-bodem","naam":"Bodem en veen","introHtml":"<p>De bodem is het fundament van het veenweidebedrijf — letterlijk.\nVeengrond is geen inerte ondergrond maar een levend, dynamisch systeem\ndat tegelijk productiemiddel, klimaatarchief en waterreservoir is.\nVeenoxidatie, bodemdaling, stikstofleverantie, draagkracht en\nbiodiversiteit zijn allemaal uitingen van hetzelfde bodemproces.\nBodembeheer op veen is daarmee geen technische bijzaak maar een van de\ncentrale managementthema's.</p>","maatregelen":[{"titel":"Bodembeheer en bewaking","html":"<div class=\"ts\">WAT HET IS</div><p>Bodemkwaliteit op veengrond omvat zes samenhangende dimensies:\norganische stof, bodemchemie, bodemleven, bodemstructuur,\nwaterhuishouding en beworteling. Geen van deze dimensies is los te zien\nvan de andere. Een goede bodemkwaliteit vertaalt zich direct in een\nbetere bodembenutting van stikstof — en elke 20% stijging in\nbodembenutting levert 10% stijging in bedrijfsbenutting op. De variatie\nin bodembenutting tussen veenweidebedrijven is enorm: van 30 tot 90%\n(Van Eekeren &amp; Philipsen, 2014).</p><div class=\"ts\">DE ZES DIMENSIES</div><ul>\n<li><p><strong>Organische stof.</strong> Veen bestaat voor een groot\ndeel uit organische stof — dat is tegelijk de kracht (hoog\nstikstofleverend vermogen) en de kwetsbaarheid (veenoxidatie bij lage\ngrondwaterstand). Het organische stofgehalte bepaalt sterk het\nstikstofleverend vermogen (NLV).</p></li>\n<li><p><strong>Bodemchemie.</strong> pH, fosfaat-, kalium-, zwavel- en\nmagnesiumtoestand bepalen de beschikbaarheid van nutriënten voor\ngrasgroei. Op veen is de pH vaak laag (verzuring), met negatieve\neffecten op bodemleven en grasproductie. Zwavel (S-PAE) en\nregenwormaantallen correleren positief met het NLV.</p></li>\n<li><p><strong>Bodemleven.</strong> Regenwormen, bacteriën en schimmels\nzijn de motor van mineralisatie. Strooiselbewonende regenwormen (0–10\ncm) zijn direct bereikbaar voor weidevogels en worden bevorderd door\norganische mestsoorten met hoge C/N-ratio (dikke fractie, ruige mest)\n(Deru &amp; Van Eekeren, 2016).</p></li>\n<li><p><strong>Bodemstructuur en draagkracht.</strong>\nIndringingsweerstand en draagkracht bepalen wanneer beweid en gereden\nkan worden. In rijspoor is de indringingsweerstand doorgaans veel hoger\ndan erbuiten — een directe maat voor verdichting en schade (Van Eekeren\net al., 2013).</p></li>\n<li><p><strong>Waterhuishouding.</strong> Grondwaterstand,\nbodemvochtgehalte en drainagesnelheid bepalen samen de beschikbaarheid\nvan vocht en nutriënten. Te droog: hydrofobie en scheurvorming. Te nat:\nte lage draagkracht en beperkte mineraliseringsactiviteit.</p></li>\n<li><p><strong>Beworteling.</strong> De diepte en dichtheid van\nbeworteling bepalen hoeveel van het profiel benut wordt. Op veen is de\nwortelzone van grassen doorgaans ondiep (0–15 cm); kruiden als cichorei\nen smalle weegbree wortelen dieper en ontsluiten daarmee mineralen uit\ndiepere lagen.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN</div><p>Uit het project Goed Bodembeheer op Veen Boert Beter (2012–2014) en\nde checklist (Van Eekeren &amp; Philipsen, 2014) komen de volgende\nkernlessen:</p><ul>\n<li><p>Graslandproductie varieert enorm: 9–18 ton DS/ha op vergelijkbare\nveenpercelen. Die variatie wordt niet verklaard door één factor maar\ndoor de combinatie van waterstand, botanische samenstelling, bodemchemie\nen bodembiologie (Hoekstra et al., 2023).</p></li>\n<li><p>Witte klaver en Engels raaigras geven hogere opbrengst en\nkwaliteit. Kweek heeft een significant negatief effect. Aanwezigheid van\nwitte klaver correleert ook positief met fosfor in het gras —\nwaarschijnlijk via mycorrhiza.</p></li>\n<li><p>Bodemzwavel (S-PAE) en regenwormaantallen zijn positief\ngerelateerd aan het NLV — twee parameters die snel en goedkoop te meten\nzijn als indicator voor de bodemdynamiek.</p></li>\n<li><p>De KringloopWijzer is het startpunt: op basis van bodem- en\nkuilanalyses gecombineerd met de bodemconditiescore\n(mijnbodemconditie.nl) is gericht bodembeheer mogelijk.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Bodemkwaliteitsbewaking is op elk bedrijf toepasbaar als jaarlijkse\nbedrijfsroutine. De aanbevolen aanpak: (1) KringloopWijzer voor\nbedrijfsbenutting; (2) graskuilanalyse eerste snede als signaal voor\nbodemvruchtbaarheid; (3) bodemanalyse voor chemische parameters per\nperceel; (4) bodemconditiescore in het veld voor structuur, bodemleven\nen beworteling. Het is geen eenmalige meting maar een meerjarig\nmonitoringsproces.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Bekalken en Ca/Mg-beheer —</strong> pH is de meest directe\nstuurknop voor bodemleven en nutriëntenbeschikbaarheid op veen.\nBodembewaking brengt de pH-problematiek in beeld. Let op dat een hogere\npH de veenafbraak wel kan verhogen!</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Mestsoort en organische stof —</strong> De keuze voor mest\nmet hoge C/N-ratio (dikke fractie, ruige mest) beïnvloedt direct het\nbodemleven, de pH en het NLV.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Bodem- en watermonitoring —</strong> Grondwaterstandsensoren\nper perceel zijn de aanvulling op bodemanalyses: samen geven ze een\nvolledig beeld van wat er in de bodem gebeurt.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Van Eekeren, N. en Philipsen, B. (2014).</strong> <em>Goed\nbodembeheer op veen boert beter — maatregelen voor duurzaam bodembeheer\nvoor melkveehouders op veen.</em> Louis Bolk Instituut, publicatienummer\n2014-005 LbD.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/2904.pdf</p><p><strong>Van Eekeren, N. en Philipsen, B. (2014).</strong>\n<em>Checklist bodemkwaliteit en graslandproductie voor het\nveenweidegebied.</em> V-focus, december 2014, pp. 20–22. Louis Bolk\nInstituut.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/2943.pdf</p><p><strong>Hoekstra, N., Van Eekeren, N. en Bosma, N. (2023).</strong>\n<em>Variatie in grasproductie — factsheet Integrale Bodemverbetering\nFeangreiden.</em> Louis Bolk Instituut / Veenweide Fryslân.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/factsheet-variatie-grasproductie.pdf</p>"},{"titel":"Draagkrachtbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Draagkracht is het vermogen van de bodem om belasting — van koeien of\nmachines — te dragen zonder blijvende schade aan bodemstructuur en zode.\nOp veengrond is draagkracht de meest directe beperking voor beweiding en\nmechanisatie: ze bepaalt wanneer het seizoen begint en eindigt, hoe\nintensief beweid kan worden en welke machines inzetbaar zijn.\nDraagkracht en bodemstructuur zijn nauw verwant maar niet hetzelfde: een\nslappe veenbodem kan een dichte zode hebben met goede draagkracht in de\ntoplaag, terwijl de onderliggende veenlaag draagkrachteloos is.</p><div class=\"ts\">WAT HET DOET — DE SPANNING</div><p>Er is een fundamentele spanning op veengrond: een goede\nbodemstructuur (lage indringingsweerstand, goede doorworteling) gaat\ngepaard met hogere grasproductie maar ook met grotere kwetsbaarheid voor\nverdichting. Bedrijven met een lage indringingsweerstand buiten het\nrijspoor moeten extra zorgvuldig zijn met machinekeuze en -timing.\nBedrijven die over vaste rijsporen rijden hebben vaak minder\nbodemstructuurschade buiten het spoor maar zware rijsporen (Van Eekeren\net al., 2013).</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Zodedichtheid bepaalt draagkracht.</strong> Een dichte\nzode, zoals kurzrasen opbouwt, correleert sterk met hogere draagkracht.\nDiploïde grassenrassen vormen meer spruiten per m² dan tetraploïde\nrassen en geven daardoor een dichtere zode en hogere draagkracht\n(Proeftuin Krimpenerwaard, 2022).</p></li>\n<li><p><strong>Rijspoorschade is meetbaar en vermijdbaar.</strong>\nIndringingsweerstand in het rijspoor is significant hoger dan erbuiten.\nGebruik van de sleepslang voor drijfmestuitrijden vermijdt\nrijspoorschade bij de eerste en tweede snede — een maatregel die op veen\naanzienlijk meer effect heeft dan op droge grond (Van Eekeren et al.,\n2013).</p></li>\n<li><p><strong>Tijdstip is de belangrijkste variabele.</strong>\nBodemverdichting hangt het sterkst samen met het vochtgehalte van de\nbodem op het moment van berijden. Niet de machine maar het moment\nbepaalt of er schade optreedt. Op veen geldt: bij twijfel wachten, niet\nrijden.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Draagkrachtmanagement is relevant voor elk veenweidebedrijf, maar het\nhandelingsperspectief verschilt per situatie. Drie niveaus: (1)\nZodemanagement — rassenlijstkeuze, kurzrasen, geen herinzaai; (2)\nWaterhuishouding — WIS, onderwaterdrainage, tijdig draineren voor\nmechanisatie; (3) Rijgedrag — sleepslang, lage bandenspanning,\nspoorrijden, tijdstip kiezen.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: VERNATTING EN DRAAGKRACHT</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Hogere grondwaterstanden remmen veenafbraak maar verlagen de\ndraagkracht. Dit is de centrale spanning in het veenweidegebied: de\nklimaatdoelen vragen om vernatting, de bedrijfsvoering vraagt om\ndraagkracht. Er is geen oplossing die beide volledig oplost, maar de\ncombinatie van een dichte zode (via kurzrasen of diploïde rassen) met\nWIS geeft het best haalbare resultaat: hogere grondwaterstand én\nvoldoende draagkracht voor beweiding (Hoekstra et al., 2022; Proeftuin\nKrimpenerwaard, 2022).</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Van Eekeren, N., Deru, J., Philipsen, B. en Meerkerk, B.\n(2013).</strong> <em>Zoeken naar bodemstructuur en draagkracht onder\ngrasland.</em> V-focus, december 2013, pp. 32–33. Louis Bolk Instituut.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/2812.pdf</p><p><strong>Van Eekeren, N., Deru, J., Lenssinck, F. en Bloem, J.\n(2016).</strong> <em>Bodemkwaliteit op veengrond — effecten van drie\nmaatregelen op een rij (mestsoort, Ca/Mg-verhouding,\nonderwaterdrainage).</em> Louis Bolk Instituut, publicatienummer\n2016-013 LbD.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/3119.pdf</p><p><strong>Proeftuin Krimpenerwaard (2022).</strong> <em>Grip op\ndraagkracht — grasrassen, beweidingsmanagement en rijschade op\nveengrond.</em> Louis Bolk Instituut / PPP-Agro Advies / VIC.\nhttps://proeftuinkrimpenerwaard.nl/veranderende-draagkracht/</p>"},{"titel":"Bekalken","html":"<div class=\"ts\">WAT HET IS</div><p>Bekalken is het toedienen van kalk (CaCO₃, calciumoxide of\ncalciumhydroxide) om de pH van de bodem te verhogen. Op veengrond is de\npH van nature laag en neigt naar verzuring, zeker bij intensief gebruik,\nkunstmestgebruik en drijfmesttoediening. Naast pH-correctie gaat het bij\nbekalken ook om de verhouding tussen calcium (Ca) en magnesium (Mg) in\nde bodem — de Ca/Mg-verhouding is een indicator voor de bodemstructuur\nen het bodemleven.</p><div class=\"ts\">WAAROM VEEN BIJZONDER IS</div><p>Op minerale gronden heeft bekalken een relatief snel en voorspelbaar\neffect: een bekende hoeveelheid kalk verhoogt de pH met een bekende\nstap. Op veen is dat fundamenteel anders. Veen heeft een enorme\nbuffercapaciteit door het hoge organische stofgehalte: voor een\npH-stijging van 0,1 in de laag 0–10 cm is bij een organische stofgehalte\nvan 20% al 570 kg kalk per ha nodig. Bij hogere organische stofgehalten\n(30–50%, niet ongewoon in veenweide) zijn de benodigde hoeveelheden nog\ngroter. Dit maakt bekalking duurder en trager effectief dan op droge\ngrond (Hoekstra et al., 2024).</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>pH en bodemleven.</strong> Een pH onder 4,8 remt\nkiemkracht van kruiden en is de ondergrens voor productieve doorzaai.\nRegenwormen presteren beter bij hogere pH; de pH correleert positief met\nregenwormactiviteit en daarmee met NLV en voedselaanbod voor weidevogels\n(Van Eekeren et al., 2016).</p></li>\n<li><p><strong>Ca/Mg-verhouding.</strong> Een goede Ca/Mg-verhouding\nverbetert de bodemstructuur: voldoende calcium zorgt voor een stabiele\nkruimelstructuur; te veel magnesium ten opzichte van calcium leidt tot\neen smerende, structuurarme bodem. Op veen is de Ca/Mg-verhouding vaak\nongunstig door historisch hoge magnesiumgiften (Van Eekeren et al.,\n2016).</p></li>\n<li><p><strong>Ruige mest en dikke fractie verhogen pH.</strong>\nBekalking is niet de enige route naar een hogere pH: ruige mest en\nGFT-compost verhogen de pH significant meer dan drijfmest of kunstmest.\nHet toedienen van organische mestsoorten met hoge C/N-ratio heeft\ndaarmee een dubbel voordeel — bodemleven én pH (Deru &amp; Van Eekeren,\n2016).</p></li>\n<li><p><strong>Weidevogel- en botanisch beheer.</strong> In\nnatuurgraslanden ontbreekt periodieke bekalking vaak, wat leidt tot lage\npH's (soms onder 4,0) en dominantie van zuurtolerante soorten\n(pijpenstrootje, pitrus). Voor verzuurd grasland dat naar kruidenrijkdom\ngetransformeerd moet worden is bekalking een noodzakelijke eerste stap —\nook al is ze traag en kostbaar op veen (Factsheet kruidenrijk grasland\nFryslân, LBI).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Bekalken is aan de orde bij pH onder 5,0 op productiegrasland\n(streefwaarde: 5,0–5,5 voor veengrond) of bij pH onder 4,8 bij\nkruidenintroductie. Vanwege de hoge buffercapaciteit van veen werkt\nbekalken het best als gefractioneerde meerjarige behandeling — niet als\neenmalige grote gift. Op pachtpercelen of percelen met korte\ngebruikshorizon is de investering moeilijk terug te verdienen.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>REGELGEVING</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Bekalking valt niet onder de mestwetgeving en is daarmee vrij toe te\npassen. De gebruiksruimte voor kalk is niet genormeerd. Bekalking met\nagrarische hulpstoffen (kalkmeststoffen, dolokal) is wel opgenomen in\nhet bemestingsadvies voor grasland.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>LBI / Veenweide Fryslân (2024).</strong> <em>Factsheet\nkruidenrijk grasland in het veenweidegebied in Fryslân.</em> Louis Bolk\nInstituut, project Integrale Bodemverbetering Feangreiden.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/factsheet-kruidenrijk-grasland-het-veenweidegebied-fryslan.pdf</p><p><strong>Van Eekeren, N., Deru, J., Lenssinck, F. en Bloem, J.\n(2016).</strong> <em>Bodemkwaliteit op veengrond — effecten van drie\nmaatregelen op een rij.</em> Louis Bolk Instituut, publicatienummer\n2016-013 LbD.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/3119.pdf</p>"}]},{"id":"toolbox-04-grasland","naam":"Grasland","introHtml":"<p>Graslandbeheer op veen is een afzonderlijk vakgebied. Scheuren is\nverboden — niet als regel maar als beginsel, want scheuren op veen\nbetekent een enorme vrijkomst van CO₂ en stikstof. Alles wat op andere\ngrondsoorten via herinzaai wordt opgelost, moet op veen via doorzaai,\nmaaibeheer en gericht bodembeheer.</p><p>Gras is de basis van het veenweidebedrijf. Maar het gras op veen is\nanders: de bodem is nat en slap, de verkaveling is smal en lang, de\ndraagkracht is de dominante randvoorwaarde voor beweiding, en scheuren\nis geen optie. De keuzes in graslandbeheer, beweidingssysteem,\nvoederwinning en rantsoen zijn daardoor op veen structureel anders dan\nop droge grond — en ze bepalen samen in hoge mate de klimaatvoetafdruk,\nde biodiversiteit en het bedrijfsresultaat.</p>","maatregelen":[{"titel":"Beweidingssystemen","html":"<div class=\"ts\">WAT HET IS</div><p>Het beweidingssysteem bepaalt hoe, wanneer en hoe intensief koeien op\nde percelen grazen. In het veenweidegebied zijn de meest relevante\nsystemen: omweiden, stripgrazen, kurzrasen en roterend standweiden\n(RSW). Elk systeem heeft een eigen logica voor grashoogte,\nrotatiesnelheid, veebezetting en bijvoeding. Op veengrond bepalen drie\nbedrijfsgebonden randvoorwaarden — koppelomvang, aanwezigheid van een\nmelkrobot, en de bedrijfsintensiteit — mede welk systeem überhaupt\nuitvoerbaar is. Daarboven liggen veenspecifieke omstandigheden die voor\niedereen gelden.</p><div class=\"ts\">RANDVOORWAARDEN DIE DE SYSTEEMKEUZE BEPALEN</div><p><strong>Bedrijfsgebonden randvoorwaarden</strong></p><ul>\n<li><p><strong>Koppelomvang en veebezetting.</strong> Grote koppels op\nsmalle veenweidepercelen (15–45&nbsp;m breed, lang en serieel gepositioneerd)\nzijn logistiek lastig te managen. Elke extra koe per hectare vergroot de\nkans op vertrapping en verkort de beweidingsdagen per jaar. Intensieve\nbedrijven (7–8&nbsp;GVE/ha op de huiskavel) hebben minder systeemvrijheid dan\nextensieve bedrijven (3–5&nbsp;GVE/ha op de huiskavel).</p></li>\n<li><p><strong>Melkrobot of gangbaar melken.</strong> Bij automatisch\nmelken (AMS) moeten koeien zelf pendelen tussen wei en stal. Dit stelt\neisen aan loopafstand, perceelsindeling en koegedrag. Systemen waarbij\nkoeien dagelijks van perceel wisselen (stripgrazen, omweiden) zijn\nlastiger te combineren met een robot dan systemen waarbij koeien op één\nperceel blijven (kurzrasen). Bij grote koppels en lange loopafstanden is\nweidegang met AMS op veen uitdagend.</p></li>\n<li><p><strong>Bedrijfsintensiteit en doelstelling.</strong> Een\nintensief bedrijf stuurt op maximale melkproductie per hectare en kan\nhogere inputs inzetten. Een extensief bedrijf stuurt op biodiversiteit,\nlage externe inputs en ecosysteemdiensten. Wat wint op het ene doel,\nverliest op het andere — de systemen presteren in onderzoek significant\nanders bij hoge vs. lage veebezetting (Hoekstra et al., 2022).</p></li>\n</ul><p><strong>Veenspecifieke randvoorwaarden — gelden voor\niedereen</strong></p><ul>\n<li><p><strong>Klauwgezondheid.</strong> Op veenweidebedrijven is\nklauwgezondheid een structurele randvoorwaarde bij elk\nbeweidingssysteem. Natte percelen, looppaden over sloten, lange\nloopafstanden bij smalle en serieel gepositioneerde percelen en\nslootdoorgangen belasten klauwen extra. Bij kurzrasen lopen koeien\nrelatief veel om voldoende gras op te nemen; bij RSW en stripgrazen zijn\nde loopafstanden naar nieuwe perceelsdelen of de stal de belastende\nfactor. Een goede klauwconditie is daarmee geen aandachtspunt per\nsysteem maar een bedrijfsbrede randvoorwaarde die mede bepaalt hoe\nintensief en hoe lang beweid kan worden (Hoekstra et al.,\n2017).</p></li>\n</ul><p><strong>Veenspecifieke randvoorwaarden — gelden voor\niedereen</strong></p><ul>\n<li><p><strong>Draagkracht.</strong> De dominante randvoorwaarde op\nveen. Bij hoge grondwaterstanden en natte perioden is beweiding soms\nweken onmogelijk, ongeacht het systeem. Vertrapping beschadigt de zode,\nvergroot baggeraanwas en leidt tot landverlies.</p></li>\n<li><p><strong>Stikstofgehalte in gras.</strong> Veenweidegras heeft van\nnature een hoog eiwitgehalte (hoge OEB). Bij intensieve beweiding leidt\ndit tot ureumoverschot in de melk en hogere N-verliezen. Dit vraagt\nactieve sturing via bijvoeding — ongeacht het\nbeweidingssysteem.</p></li>\n<li><p><strong>Weidevogelcompatibiliteit.</strong> Beweiding en\nweidevogels zijn deels complementair (openheid, voedsel voor kuikens)\nmaar ook conflicterend. Te vroeg of te intensief beweiden vernietigt\nnesten. Het systeem en de veebezetting bepalen mede de\nhabitatgeschiktheid.</p></li>\n<li><p><strong>Perceelspaden en slootdoorgangen.</strong> Bij smalle,\nserieel gepositioneerde veenweidepercelen zijn looppaden langs en over\nsloten een infrastructureel knelpunt. Elke systeemkeuze die vraagt om\ndagelijkse koppelverplaatsing (stripgrazen, omweiden) vereist goede en\ndroge looproutes. Bij robotmelken moeten koeien zelfstandig kunnen\npendelen; lange of natte looppaden verlagen de motivatie om de wei in te\ngaan en verhogen het klauwrisico. Kurzrasen op de huiskavel vermijdt dit\nknelpunt grotendeels; systemen met meerdere percelen op afstand vereisen\neen bewuste investering in perceelsinfrastructuur.</p></li>\n</ul><div class=\"ts\">DE SYSTEMEN VERGELEKEN</div><p>Op basis van beweidingsproeven op veengrond (Hoekstra et al., 2017;\n2022):</p><p><strong>Kurzrasen</strong></p><p>Continu beweiden op 3–5&nbsp;cm grashoogte op een vast perceel. Na een\npaar seizoenen ontstaat een dichte, bladrijke grasmat met aantoonbaar\nhogere zodedichtheid en daarmee hogere draagkracht — het grootste\npraktische voordeel op veen. De causale keten is: kurzrasen → dichte\nzode → betere draagkracht → minder vertrappingsschade en minder\nversmering bij natte omstandigheden. In de proef uit 2016 moest de\nstripgraasgroep een week opstallen door gebrekkige draagkracht bij\nextreme regenval; de kurzrasengroep niet (Hoekstra et al., 2017).\nGrasproductie is 25% lager dan bij stripgrazen, maar wordt gecompenseerd\ndoor hogere grasbenutting — minder bosvorming, minder\nvertrappingsverlies — en hogere voederwaarde van het jonge\nbladmateriaal. Goed combineerbaar met robotmelken: koeien blijven op\nhetzelfde perceel, lopen actief en zijn makkelijk te motiveren voor\nstalgang. Aandachtspunten: hoge OEB in veenweidegras vereist correctie\nvia bijvoeding; op lange termijn risico op minder diepe beworteling en\nminder organische stofopbouw door lagere weideresten. Minder geschikt\nvoor weidevogelbeheer door te korte, dichte grasstructuur zonder dekking\n(Hoekstra et al., 2017; 2022).</p><p><strong>Roterend standweiden (RSW / Nieuw Nederlands\nWeiden)</strong></p><p>Koeien weiden een dag op een perceel, dan rotatie naar het volgende.\nGras groeit terug voor de volgende ronde. RSW combineert grashergroei\nper perceel met relatief lage arbeidsbelasting. De hogere grasstructuur\nbiedt meer dekking voor weidevogels en meer habitat voor insecten dan\nkurzrasen. Melkproductie uit weidegras vergelijkbaar met kurzrasen bij\ngelijke veebezetting. Bij lage veebezetting (extensief) is meer\ngrasoppervlak per koe beschikbaar, wat de weidedagen vergroot.\nCombinatie met robotmelken is mogelijk maar stelt hogere eisen aan\nperceelsindeling en loopafstand — beter geschikt voor gangbaar\nmelken.</p><p><strong>Stripgrazen</strong></p><p>Koeien krijgen dagelijks een verse strook. Hoge grasbenutting en hoge\nproductie per ha, maar hoge arbeidsinzet en intensieve\nschrikdraadinfrastructuur. Op smalle, langgerekte veenweidepercelen is\ndagelijks draad verzetten arbeidsintensief. Bij natte omstandigheden\nhoog vertrappingsrisico op elke nieuwe strook. Geschikt voor grotere\nkoppels op intensieve bedrijven met voldoende arbeid; moeilijk\ncombineerbaar met robotmelken.</p><p><strong>Omweiden (traditioneel)</strong></p><p>Koeien weiden meerdere dagen op een perceel voor de koppel wisselt.\nBekende methode met lage technische eisen. Minder efficiënt in\ngrasbenutting door bosvorming en variatie in grashoogte. Op veen nadelig\nbij grotere koppels: langere verblijftijd per perceel vergroot de\nvertrappingskans, zeker bij natte omstandigheden.</p><p><strong>Seizoensadaptief beweiden</strong></p><p>Op extensieve veenweidebedrijven werkt een seizoensaanpak: extensief\nRSW in het voorjaar voor een diverse grasstructuur (weidevogels,\ninsecten), intensiever beweiden vanaf juni voor zodedichtheid en\ndraagkrachtherstel richting het najaar. Dit vraagt een bewuste keuze in\nkoppelomvang en perceelindeling — niet elk bedrijf heeft de schaal of\ngrondpositie om dit te realiseren.</p><div class=\"ts\">WAT WE WETEN — KERNBEVINDINGEN</div><ul>\n<li><p><strong>Draagkracht en zodedichtheid.</strong> Kurzrasen geeft\nconsistent hogere zodedichtheid en daarmee hogere draagkracht dan RSW en\nstripgrazen (Hoekstra et al., 2017; 2022).</p></li>\n<li><p><strong>Melkproductie op systeemniveau.</strong> Vergelijkbaar\ntussen kurzrasen en RSW. De lagere grasproductie bij kurzrasen wordt\ngecompenseerd door hogere grasbenutting en betere voederwaarde (Hoekstra\net al., 2017; 2022).</p></li>\n<li><p><strong>Effect van intensiteit.</strong> Hogere veebezetting\ngeeft hogere productie per koe en per ha, maar lagere grasbenutting en\nhogere N-verliezen. Extensieve systemen presteren beter op grasbenutting\nen stikstofefficiëntie (Hoekstra et al., 2022).</p></li>\n<li><p><strong>OEB en eiwitmanagement.</strong> Lager OEB-niveau in\nkrachtvoer compenseert het hoge eiwitgehalte in veenweidegras zonder\nproductieverlies, vermindert eiwitimport en verhoogt N-benutting\n(Hoekstra et al., 2022).</p></li>\n<li><p><strong>Biodiversiteit.</strong> RSW met lage veebezetting geeft\nmeer insecten en meer weidevogelhabitat. De hogere grasstructuur en\nbossen in RSW bieden meer dekking en voedsel voor weidevogels (Hoekstra\net al., 2022).</p></li>\n<li><p><strong>Robotmelken.</strong> Kurzrasen is het best combineerbaar\nmet automatisch melken: vast perceel, actieve koeien, geen rijdraad,\nvoorspelbaar gedrag (Hoekstra et al., 2017).</p></li>\n</ul><div class=\"ts\">WANNEER WELK SYSTEEM</div><ul>\n<li><p><strong>Grote koppel, robotmelken, focus op draagkracht:</strong>\nkurzrasen op de huiskavel.</p></li>\n<li><p><strong>Grote koppel, gangbaar melken, intensief:</strong>\nstripgrazen of kurzrasen bij voldoende perceelsbreedte.</p></li>\n<li><p><strong>Kleine tot middelgrote koppel, biodiversiteit +\nweidevogels:</strong> extensief RSW met lage veebezetting en hogere\ngrashoogte.</p></li>\n<li><p><strong>Extensief, lage inputs, 100% eigen voer:</strong>\nseizoensadaptief RSW, passend ras bij natte omstandigheden.</p></li>\n<li><p><strong>Combinatie draagkracht en weidevogels:</strong> adaptief\n— extensief RSW in voor- en begin zomer, intensiever in zomer en\nnajaar.</p></li>\n</ul><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: WEIDEGANG ONDER DRUK</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>In het veenweidegebied weidt nog 90% van de koeien minimaal 120\ndagen per jaar. Maar bedrijfsuitbreiding, robotmelken en natte perioden\nzetten weidegang onder druk. Het verdwijnen van weidegang betekent meer\nstaluren, meer mestopslag, hogere ammoniakemissie en hoger\nenergieverbruik — en het verlies van de zichtbare verbinding tussen koe\nen landschap die het maatschappelijk draagvlak vergroot.</td>\n</tr>\n<tr class=\"even\">\n<td>Tegelijk: weidegang met te zware koppels op te natte percelen\nbeschadigt de bodem structureel. Weidegang is geen doel op zich maar\nvraagt het juiste systeem, de juiste koppelomvang en het juiste\nmoment.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Dynamisch draadloos weiden —</strong> GPS-gestuurd weiden\nbiedt perspectief om percelen te sturen zonder rijdraad en koeien van\noevers weg te houden. Sluit vooral goed aan bij stripgrazen: de\ndagelijkse strookindeling die normaal met rijdraad wordt bepaald, kan\nmet GPS-sturing worden vervangen, wat de arbeidsbelasting van\nstripgrazen sterk vermindert en het systeem praktischer maakt op smalle\nveenweidepercelen. Bij kurzrasen en RSW is de meerwaarde kleiner omdat\ndaar al minder of geen rijdraadinfrastructuur nodig is.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Oeverbeheer en veebescherming —</strong> Beweidingssysteem\nen koppelomvang bepalen samen de druk op oevers. Kurzrasen concentreert\nde loopdruk op een vast perceel; RSW spreidt die. Uitrasteren van oevers\nis bij elk systeem aan te bevelen.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Extensief veenweide-ras —</strong> Lichter en robuuster vee\npast beter bij extensief beweiden op natte veengrond en vermindert de\nbodemdruk bij elk beweidingssysteem.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Weidevogelbeheer —</strong> Beweidingssysteem en\nweidevogelbeheer zijn onlosmakelijk verbonden. Extensief RSW met\nuitgerasterde nestcirkels is de meest weidevogelvriendelijke\nbeweidingsvorm.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Hoekstra, N., Van Eekeren, N., Holshof, G., Rijneveld, H.,\nVan Houwelingen, K. en Lenssinck, F. (2017).</strong>\n<em>Systeeminnovatie Beweiden Veenweiden — eindrapportage\n2015–2016.</em> Louis Bolk Instituut, rapportnummer 2017-009 LbD.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/3234.pdf</p><p><strong>Hoekstra, N., Bruinenberg, M., Van Houwelingen, K. en\nHolshof, G. (2022).</strong> <em>Adaptief weiden in het veenweidegebied\n— kurzrasen en roterend standweiden. Systeemproef naar effect van\nbeweidingssysteem en intensiteit op gras- en melkproductie, draagkracht\nen biodiversiteit.</em> Louis Bolk Instituut, publicatienummer 2022-023\nLbD.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/adaptief-weiden-het-veenweidegebied-kurzrasen-en-roterend-standweiden.pdf</p>"},{"titel":"Grasrassen en doorzaaien","html":"<div class=\"ts\">WAT HET IS</div><p>De keuze van grasrassen en het beheer van de graszode bepalen samen\nde draagkracht, de grasproductie en de weerbaarheid van het perceel. Op\nveen geldt als basisregel: scheuren en herinzaaien is geen optie. Alle\nrassenlijstkeuzes en zodeverbeteringen moeten via doorzaai en beheer\nworden gerealiseerd.</p><p><strong>RASSENLIJST — DIPLOÏD VS. TETRAPLOÏD</strong></p><p>Engels raaigras is de dominante grassoort op Nederlandse\nmelkveebedrijven en staat in twee typen op de rassenlijst: diploïde en\ntetraploïde rassen. Voor veengrond is het onderscheid relevant:</p><ul>\n<li><p><strong>Diploïde rassen</strong> vormen meer spruiten per m² en\nbouwen daardoor een dichtere zode op. Een dichtere zode geeft hogere\ndraagkracht. Onderzoek in de Proeftuin Krimpenerwaard toont dit\naantoonbaar aan (Proeftuin Krimpenerwaard, 2022).</p></li>\n<li><p><strong>Tetraploïde rassen</strong> vormen grotere bladeren met\nhogere voederwaarde maar minder spruiten per m². Dit geeft een opener\nzode met lagere draagkracht — ongunstig op veen.</p></li>\n<li><p><strong>Persistentie</strong> is op veen minstens zo belangrijk\nals opbrengstpotentieel. Een ras dat lang in de zode blijft, vermindert\nde noodzaak van doorzaai en behoudt de zodedichtheid.</p></li>\n</ul><div class=\"ts\">ZODEBEHEER — DOORZAAIEN ALS ENIGE OPTIE</div><p>Wanneer de zode open plekken vertoont door vertrapping, muizenschade,\ndroogte of sleetse rassen, is doorzaaien de enige verantwoorde\nherstelmethode op veen. De hoofdregels:</p><ul>\n<li><p><strong>Niet scheuren.</strong> Scheuren op veen stoot veel CO₂\nuit in het jaar van scheuren door versnelde veenoxidatie en\nstikstofmineralisatie. Bovendien gaat de opgebouwde zodedichtheid en\nbodemstructuur volledig verloren.</p></li>\n<li><p><strong>Doorzaaimethode.</strong> De strokenfrees geeft de beste\nresultaten bij doorzaai (van kruiden) op veen: de machine freest een\nstrook van 7 cm breed in de bestaande zode en zaait daarin. Beter\nkiembed, minder concurrentie van bestaand gras, dan een wiedeg\n(Proeftuin Krimpenerwaard, 2022; LBI Fryslân, 2024).</p></li>\n<li><p><strong>Timing.</strong> Beste periode voor doorzaai: half\naugustus tot half september bij regen in de vooruitzichten. Zode eerst\nkort maaien (3 cm stoppel). Twee weken na doorzaai nogmaals maaien of\nbeweiden om grasconcurrentie te verminderen.</p></li>\n<li><p><strong>Niet te diep zaaien.</strong> Maximaal 1–2 cm zaaidepte.\nDroogte is funest voor kiemplantjes. Geduld is nodig: resultaat is soms\npas na een half jaar goed zichtbaar.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Rassenlijstkeuze geldt voor elk bedrijf dat zaad aanschaft of inhuurt\nvoor doorzaai. Kies bij twijfel voor diploïde persistente rassen.\nDoorzaai op plekken met meer dan 20% open zode of bij dominantie van\nongewenste soorten (kweek, straatgras, pitrus). Doorzaai vraagt\nvolhouden: een eenmalige actie is zelden voldoende.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: NIET SCHEUREN — OOK NIET BIJ\nTRANSITIE</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>De verleiding om te scheuren is het grootst bij transitie naar\nkruidenrijk grasland of bij ernstige zodeschade. Toch blijft scheuren op\nveen onacceptabel — ook als het praktisch de makkelijkste route lijkt.\nDoorzaai met de strokenfrees in combinatie met gericht maaibeheer geeft\nop veen vergelijkbare resultaten als herinzaai, zonder de CO₂-piek en\nhet verlies van de veenbodemstructuur (Hoekstra et al., 2024).</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Proeftuin Krimpenerwaard (2022).</strong> <em>Grip op\ndraagkracht — effect van grasrassen op zodedichtheid en draagkracht op\nveengrond.</em> Louis Bolk Instituut / PPP-Agro Advies / VIC.\nhttps://proeftuinkrimpenerwaard.nl/veranderende-draagkracht/</p><p><strong>Proeftuin Krimpenerwaard / LBI (2021).</strong>\n<em>Verrassende opbrengst in doorzaaiproef productieve kruiden.</em>\nProeftuin Trots op de Krimpenerwaard.\nhttps://proeftuinkrimpenerwaard.nl/verrassende-opbrengst-in-doorzaaiproef-productieve-kruiden/</p>"},{"titel":"Kruidenrijk grasland","html":"<div class=\"ts\">WAT HET IS</div><p>Kruidenrijk productief grasland is een graslandtype waarbij naast\ngrassen ook productieve kruiden aanwezig zijn: witte klaver, rode\nklaver, smalle weegbree, cichorei, karwij, rolklaver en duizendblad. Dit\nis nadrukkelijk géén botanisch grasland — het doel is een combinatie van\nhoge voederwaarde, betere stikstofbenutting, grotere droogteresistentie\nen meer biodiversiteit. De meest kansrijke kruiden voor het\nveenweidegebied zijn smalle weegbree, witte klaver en cichorei (Hoekstra\net al., 2021; LBI Fryslân, 2024).</p><div class=\"ts\">WAT KRUIDEN TOEVOEGEN</div><ul>\n<li><p><strong>Smalle weegbree.</strong> Droogteresistenter dan gras\ndoor diepere beworteling. In het extreem droge jaar 2018 gaf smalle\nweegbree tot 3× meer drogestofopbrengst dan monocultuur gras. In normale\njaren zijn opbrengsten vergelijkbaar of hoger (Pijlman &amp; Van\nEekeren, 2020).</p></li>\n<li><p><strong>Witte klaver.</strong> Biologische stikstofbinding via\nwortelknolletjes. Vermindert de kunstmestbehoefte. Correleert ook\npositief met fosfor in het gras, waarschijnlijk via mycorrhiza. Vormt\nclusters en persisteert goed op veen in mengsels (LBI Fryslân,\n2024).</p></li>\n<li><p><strong>Cichorei.</strong> Penwortel die diepere bodemlagen\nontsluit en mineralen beschikbaar maakt die gras niet bereikt. Hoge\nopbrengstpotentie maar minder persistent dan smalle weegbree in de\nzode.</p></li>\n<li><p><strong>Functionele werking in de bodem.</strong> Kruiden remmen\nnitrificatie, wat stikstofuitspoeling beperkt. Diepere wortels\nverbeteren de bodemstructuur en droogtebestendigheid van het grasland\nals geheel.</p></li>\n<li><p><strong>Diergezondheid.</strong> Smalle weegbree heeft bewezen\npositieve effecten op de gezondheid van melkvee: lagere wormdruk, betere\nmineralenstatus. Dit is een specifieke meerwaarde voor het\nveenweidebedrijf waar kruidenrijk voer van eigen land kan bijdragen aan\nminder externe inputs voor diergezondheid.</p></li>\n</ul><div class=\"ts\">DOORZAAIEN OP VEEN — DE PRAKTIJK</div><p>Doorzaai van kruiden op veen is mogelijk maar vraagt de juiste\ntechniek en omstandigheden. De kernlessen uit de Proeftuin\nKrimpenerwaard en het Friese IBF-project (Hoekstra et al., 2021; LBI\nFryslân, 2024):</p><ul>\n<li><p><strong>Strokenfrees &gt; wiedeg.</strong> Met de strokenfrees is\nhet aandeel kruiden na doorzaai bijna even hoog als na herinzaai. Wiedeg\nin lang gras geeft het slechtste resultaat.</p></li>\n<li><p><strong>pH minimum 4,8.</strong> Onder pH 4,8 is kruidenvestiging\nvrijwel kansloos. Bekalken is bij lage pH een noodzakelijke eerste stap\n— ook al vraagt dat op veen grote hoeveelheden kalk.</p></li>\n<li><p><strong>Klei-op-veen heeft hogere slagingskans.</strong> Door de\nhogere pH en betere bodemstructuur van klei-op-veenpercelen is\nkruidenvestiging hier kansrijker dan op zuiver veen.</p></li>\n<li><p><strong>Stikstofnalevering is het grootste probleem.</strong> De\nhoge stikstofnalevering van veen geeft grassen een enorm\nconcurrentievoordeel over kruiden. Niet te veel bemesten na doorzaai is\nessentieel — anders leggen kruiden het loodje. Laat kruiden minstens\néénmaal per twee jaar tot bloei komen.</p></li>\n<li><p><strong>Beheer na doorzaai.</strong> Eerste snede na doorzaai\nniet te zwaar laten worden (max. 2,5–4 ton DS/ha). Twee weken na\ndoorzaai nogmaals maaien of beweiden. Begin op percelen met weinig\nonkruid.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Kruidenrijk grasland is het meest haalbaar op percelen met pH ≥ 4,8,\nlage onkruiddruk en beperkte bemestingsintensiteit. Productief\nkruidenrijk grasland past binnen de normale bedrijfsvoering; botanisch\nkruidenrijk grasland (minder soorten, lager bemest, ANLb) vraagt een\nandere bedrijfslogica en wordt hier niet besproken. Periodiek doorzaaien\n(elke 3–5 jaar) is nodig om soortenrijkdom op peil te houden — kruiden\npersisteren niet eeuwig in de zode.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Bekalken —</strong> Voorwaarde voor succesvolle\nkruidenvestiging op veen bij lage pH.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Maaibeheer —</strong> Timing van maaien is de primaire\nsturingsmaatregel voor kruidenrijkdom: te vroeg maaien voorkomt\nzaadzetting van kruiden; te laat maaien geeft gras het voordeel.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Weidevogelbeheer —</strong> Smalle weegbree trekt insecten\nvia bloeiwijze aan, die voedsel zijn voor weidevogelpullen. Kruidenrijk\ngrasland versterkt weidevogelbeheer zonder extra ingreep.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Rantsoen op maat —</strong> Kruiden verbeteren de\nvoederwaarde in brede zin: hogere gehalten vitaminen, mineralen en\nsecundaire metabolieten. Dit kan de externe inputs voor diergezondheid\nverminderen.</td>\n</tr>\n</tbody>\n</table>","lit":null},{"titel":"Maaibeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Maaibeheer omvat de keuzes over wanneer, hoe vaak, hoe hoog en met\nwelk doel gemaaid wordt. Op veenweidepercelen heeft maaibeheer een\ndubbelfunctie: voederwinning (kuil, hooi) én graslandbeheer (botanische\nsamenstelling, zodekwaliteit, weidevogelhabitat). Deze twee functies\nstaan soms op gespannen voet — vroeg en vaak maaien maximaliseert de\nkuilkwaliteit maar is slecht voor biodiversiteit en weidevogels.</p><div class=\"ts\">DE VEENSPECIFIEKE MAAIVARIABELEN</div><ul>\n<li><p><strong>Stikstofnalevering.</strong> Veen levert van nature veel\nstikstof, met name in het najaar. Dit leidt tot een hoog eiwitgehalte\n(hoge OEB) in gras van latere snede in het seizoen.</p></li>\n<li><p><strong>Rijschade.</strong> Op natte veenpercelen is\nvoederwinning met zwaar materieel een grote bron van bodemverdichting.\nSleepslangbemesting en lichte combinaties voor voederwinning verminderen\nrijschade. Timing naar drogere perioden is de primaire\nmaatregel.</p></li>\n<li><p><strong>Weidevogels.</strong> Maaidatum is de meest bepalende\nfactor voor het succes van weidevogels: voor 1 juni maaien vernietigt\nnesten en kuikens. Uitgesteld maaien (na 15 juni, of gefaseerd per\nperceel) geeft weidevogels de kans om jongen groot te brengen.</p></li>\n<li><p><strong>Maaifrequentie en kruidenrijkdom.</strong> Kruiden kunnen\nzaad zetten als minstens één keer per twee jaar een perceel later in het\nseizoen gemaaid wordt. Bij strak maaischema (4–5 sneden per jaar)\nverdwijnen kruiden geleidelijk uit de zode.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Maaitijdstip eerste snede.</strong> Een lichte eerste\nsnede (niet te snel groeiend gras) is gunstig voor weidevogels: lichtere\nzode betekent betere mobiliteit voor kuikens. Kunstmest of hoge N-giften\ngeven een zware eerste snede die kuikenhabitat verslechtert (Deru &amp;\nVan Eekeren, 2016).</p></li>\n<li><p><strong>Maaiselafvoer.</strong> Voor kruidenrijke percelen en\nbotanisch grasland is maaiselafvoer essentieel: het verwijdert\nnutriënten uit het systeem en voorkomt dat gras de kruiden verdringt\ndoor te hoge bodemvruchtbaarheid. Op productiegrasland wordt maaisel\ngebruikt als ruwvoer.</p></li>\n<li><p><strong>Rijpadensysteem.</strong> Vaste rijpaden bij maaien en\nslootonderhoud concentreren rijschade op een beperkt deel van het\nperceel. Buiten de rijpaden is de bodem onverstoord en de zode intact.\nDit systeem is in de Proeftuin Krimpenerwaard uitgetest als 'slimme\nrijtechniek' (Proeftuin Krimpenerwaard, 2022).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Maaibeheer is op elk bedrijf stuurbaar. De keuze hangt af van de\ndoelstelling per perceel: maximale ruwvoerproductie,\nANLb-weidevogelbeheer, kruidenrijkdom, of een combinatie. Niet elk\nperceel hoeft dezelfde aanpak te volgen — perceelsgerichte maaiplanning\n(mozaïekbeheer) biedt ruimte voor differentiatie.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Licht materieel en rijpadensysteem —</strong> Rijschade bij\nmaaien is op veen minimaal te houden via rijpadensystemen en lichte\nmachines. Maaibeheer en machinepark zijn onlosmakelijk verbonden.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Weidevogelbeheer —</strong> Maaitijdstip is de directe\nsturingsknop voor weivogelgeschiktheid. ANLb-pakketten stellen eisen aan\nmaaidatum; dit is de concrete vertaling van maaibeheer naar\nvergoeding.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Voederwinning en conservering —</strong> Maaibeheer bepaalt\nde kwaliteit van het ruwvoer: vroeg gemaaid gras geeft hogere VEM en\nlagere vezels; later gemaaid gras geeft meer structuur maar lagere\nVEM.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Deru, J. en Van Eekeren, N. (2016).</strong> <em>Dikke\nfractie gescheiden drijfmest is alternatief voor ruige mest — mest voor\nweidevogelgebieden in veenweiden.</em> V-focus, april 2016, pp. 28–29.\nLouis Bolk Instituut / VIC.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/3117.pdf</p>"},{"titel":"Rijpaden en licht materieel","html":"<div class=\"ts\">WAT HET IS</div><p>Het gebruik van licht materieel en vaste rijpaden is een strategie om\nbodemverdichting en rijschade op veenpercelen te minimaliseren. Het gaat\nniet om nieuwe machines aanschaffen maar om anders denken: welk\nmaterieel is écht nodig, wanneer is de bodem rijbaar, en hoe concentreer\nje schade op zo min mogelijk oppervlak? De Proeftuin Krimpenerwaard\nheeft dit in twee pilots onderzocht als spin-off van het project Grip op\ndraagkracht (Proeftuin Krimpenerwaard, 2022).</p><div class=\"ts\">WAT HET DOET</div><p>Elke keer dat een machine over een veenperceel rijdt, compacteert de\nbodem in het rijspoor. Dit verhoogt de indringingsweerstand, verlaagt de\ndoorlatendheid, verslechtert de beworteling en vermindert de\ngrasproductie in het spoor. Vaste rijpaden concentreren al die schade op\nmaximaal 15–20% van het perceeloppervlak, zodat 80–85% ongemoeid\nblijft.</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Sleepslang voor drijfmest.</strong> Het uitrijden van\ndrijfmest via een sleepslang (in plaats van een mesttank op het perceel)\nelimineert rijspoorschade bij bemesting volledig. Op veen is dit één van\nde meest effectieve maatregelen voor bodemstructuurbehoud, ook bij de\neerste en tweede snede (Van Eekeren et al., 2013).</p></li>\n<li><p><strong>Bandenspanning en wielgrootte.</strong> Lagere\nbandenspanning verdeelt het gewicht over een groter oppervlak en\nvermindert de contactdruk. Op veen is de contactdruk de bepalende factor\nvoor verdichting, niet het totaalgewicht. Een zware machine met lage\ndruk kan minder schade geven dan een lichte machine met hoge\ndruk.</p></li>\n<li><p><strong>Diploïde rassen en rijpaden.</strong> Diploïde\ngrassenrassen herstellen rijspoorschade beter dan tetraploïde rassen\ndoordat ze sneller nieuwe spruiten vormen. Combinatie van vaste rijpaden\nmet diploïde rassen geeft het beste resultaat voor zodeherstel.</p></li>\n<li><p><strong>Tijdstip is de primaire variabele.</strong> Niet de\nmachine maar het moment bepaalt de schade. Een natte bodem compacteert\nbij dezelfde druk veel meer dan een droge bodem.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Rijpadensystemen zijn toepasbaar op elk veenweidebedrijf dat maait of\nmest uitrijdt (met behulp van gps). De implementatie vraagt eenmalige\nplanning (vaststellen vaste rijroutes per perceel) en discipline in\nuitvoering. Sleepslangbemesting is direct toepasbaar op bedrijven die\ndrijfmest uitrijden. Bij loonwerk is afstemming met de loonwerker over\nrijgedrag en bandenkeuze een belangrijke maar onderschatte stap.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Draagkracht en bodemstructuur —</strong> Licht materieel en\nrijpadensystemen zijn de gedragsmatige kant van draagkrachtbeheer.\nBodembeheer en machinegedrag zijn twee kanten van dezelfde\nmedaille.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Maaibeheer —</strong> Rijpaden bij ruwvoederwinning zijn\nhetzelfde principe als bij bemesten: vaste routes, minimale verstoring\nvan de rest van het perceel.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Zodebeheer en grasrassen —</strong> Diploïde rassen\nherstellen rijspoorschade sneller. Rassenlijstkeuze en rijgedrag\nversterken elkaar.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>Van Eekeren, N., Deru, J., Philipsen, B. en Meerkerk, B.\n(2013).</strong> <em>Zoeken naar bodemstructuur en draagkracht onder\ngrasland.</em> V-focus, december 2013, pp. 32–33. Louis Bolk Instituut.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/2812.pdf</p><p><strong>Proeftuin Krimpenerwaard (2022).</strong> <em>Met minder druk\nmeer lucht aan de bodem — rijschadebeperking op veengrond.</em> Louis\nBolk Instituut / PPP-Agro Advies.\nhttps://proeftuinkrimpenerwaard.nl/meer-lucht-aan-de-bodem/</p>"}]},{"id":"toolbox-05-bemesting","naam":"Bemesting","introHtml":"<p>Bemesting op veengrond is fundamenteel anders dan op minerale\ngronden. Het veen levert zelf al stikstof via mineralisatie — het\nstikstofleverend vermogen (NLV) van veengrond ligt gemiddeld op 270 kg\nN/ha/jaar maar varieert enorm. Dit betekent dat de bodem al een groot\ndeel van de stikstofsopgave op zich neemt, en externe stikstof daardoor\nsnel overbodig of zelfs schadelijk wordt. Precisiebemesting op veen is\nniet alleen een kostenbesparing maar ook een\nwaterkwaliteitsmaatregel.</p>","maatregelen":[{"titel":"Stikstofbemesting","html":"<div class=\"ts\">WAT HET IS</div><p>Stikstofbemesting op veen vraagt een andere benadering dan op\nminerale gronden. Het stikstofleverend vermogen (NLV) van de veenbodem —\nde hoeveelheid stikstof die de bodem zelf levert via mineralisatie — is\nop veen gemiddeld hoog maar sterk variabel: 200–350 kg N/ha/jaar. Bij\nhogere grondwaterstanden daalt het NLV doordat veenoxidatie en\nmineralisatie vertragen — dit is juist het doel van vernatting maar\nheeft gevolgen voor de bemestingsbehoefte.</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>NLV daalt bij vernatting.</strong> Bij hoog water\n(grondwaterstand −20 cm) was het NLV gemiddeld 255 kg N/ha tegenover 270\nkg N/ha bij laag water — een daling van 6%. Dit verklaart de gemiddeld\n5% lagere grasopbrengst bij vernatting maar betekent ook dat de\nkunstmestbehoefte bij vernatting iets toeneemt (Hoekstra &amp; Pijlman,\n2025).</p></li>\n<li><p><strong>N-benutting uit kunstmest gelijk bij hoog en laag\nwater.</strong> Bij hoge grondwaterstand wordt kunstmeststikstof even\nefficiënt benut als bij lage grondwaterstand. Het lagere NLV is dus\ncompenseerbaar met gerichte kunstmestgift zonder efficiëntieverlies\n(Hoekstra &amp; Pijlman, 2025).</p></li>\n<li><p><strong>OEB-problematiek bij beweiding.</strong> Veenweidegras\nheeft van nature een hoge onbestendige eiwitbalans (OEB). Lager\nOEB-niveau in bijvoeding compenseert dit zonder productiever lies,\nvermindert eiwitimport en verhoogt N-benutting op bedrijfsniveau\n(Hoekstra et al., 2022).</p></li>\n<li><p><strong>Ammoniakemissie reductie.</strong> Een 25% reductie in\nammoniakemissie is haalbaar via de combinatie van: meer en langer\nbeweiden, rantsoenmaatregelen (lagere TAN-excretie), minder\nkunstmestgebruik en verdund aanwenden van mest. Van die maatregelen is\nde combinatie beweiden + rantsoen het meest effectief (Verloop et al.,\n2018).</p></li>\n<li><p><strong>Grote variatie tussen bedrijven.</strong> De gemiddelde\nveldemissie op veenweidebedrijven is 42,5 kg NH₃/ha, maar de spreiding\nis enorm. Voorloperbedrijven in de Proeftuin Veenweiden realiseerden tot\n25% reductie zonder productieverlies (Verloop et al., 2018).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Stikstofsturing begint bij de KringloopWijzer: bedrijfsbenutting en\nbodembenutting zijn de startcijfers. Gerichte verbetering via: (1)\nrantsoenopdracht verlagen (minder OEB via bijvoeding); (2) meer\nweidegang (minder staluren, minder ammoniakemissie); (3) NLV per perceel\nkennen en kunstmestgift per perceel afstemmen; (4) verdunde mest of\nsleepvoet/ketsplaat bij aanwending.</p>","lit":"<p><strong>Hoekstra, N. en Pijlman, J. (2025).</strong> <em>Effect\nvernatting op grasopbrengst veenweide.</em> V-focus, september 2025, pp.\n26–29. Louis Bolk Instituut / WUR.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/effect-vernatting-op-grasopbrengst-veenweide.pdf</p><p><strong>Verloop, K., Verhoeff, T., Oenema, J., Hoving, I., Meerkerk,\nB., Huijsmans, J., Migchels, G., De Haan, M. en Van Eekeren, N.\n(2018).</strong> <em>Minder ammoniakemissie uit de melkveehouderij in\nhet veenweidegebied — 25% reductie een haalbaar doel.</em> Wageningen\nLivestock Research, Rapport 1129. https://doi.org/10.18174/462888</p>"},{"titel":"(Andere) mestsoorten en organische stof","html":"<div class=\"ts\">WAT HET IS</div><p>De keuze van mestsoort bepaalt niet alleen de stikstof- en\nfosfaatlevering maar ook de aanvoer van organische stof (C) en de\neffecten op bodemleven, pH en weidevogelhabitat. Op veenweidebedrijven\nzijn de relevante mestsoorten: drijfmest, dikke fractie van gescheiden\ndrijfmest, ruige mest en GFT-compost. Ze verschillen sterk in C/N-ratio\nen in de effecten op de bodem.</p><div class=\"ts\">WAT WE WETEN</div><p>Uit driejarig onderzoek op veengrond met zeven mestbehandelingen\n(Deru &amp; Van Eekeren, 2016):</p><ul>\n<li><p><strong>Dikke fractie ≥ ruige mest voor bodemleven.</strong>\nStrooiselbewonende regenwormen (0–10 cm) waren significant talrijker in\nplots bemest met dikke fractie dan in plots met andere mestsoorten. Het\nwormenaantal correleerde positief met de C/N-ratio van de mest: hoe\nhoger de C/N-ratio, hoe meer wormen.</p></li>\n<li><p><strong>Ruige mest en GFT verhogen pH.</strong> pH was\nsignificant hoger bij ruige mest en GFT-compost, lager bij kunstmest en\nonbemeste controle. Een hogere pH bevordert bodemleven en botanische\ndiversiteit.</p></li>\n<li><p><strong>Insecten voor weidevogels.</strong> Grotere insecten\n(&gt;5 mm, de werkelijk nuttige voedselbron voor weidevogelpullen) waren\ntalrijker bij dikke fractie, ruige mest, kunstmest en zaagsel+kunstmest\n— en juist minder bij drijfmest en GFT. Afgeraden wordt onbemeste\ngraslanden en drijfmest voor weidevogelgebieden.</p></li>\n<li><p><strong>Beschikbaarheid ruige mest afgenomen.</strong> Door de\nintroductie van ligboxenstallen is ruige mest schaars geworden. Dikke\nfractie van gescheiden drijfmest is het beste beschikbare alternatief\nvoor weidevogelgebieden: qua regenwormen zelfs beter dan ruige mest\n(Deru &amp; Van Eekeren, 2016).</p></li>\n</ul><div class=\"ts\">MESTSCHEIDING ALS BOUWSTEEN</div><p>Mestscheiding (scheiden van drijfmest in dikke en dunne fractie)\ngeeft de boer de mogelijkheid om de dikke fractie gericht in te zetten\nop percelen waar organische stof en bodemleven het meest baat hebben, en\nde dunne fractie te gebruiken als snel werkende N-bron. Dit vraagt een\nmestscheider of samenwerking in een keten. Opgewaardeerde dikke\nmestfracties (zoals vergiste of gecomposteerde fracties) laten\nveelbelovende effecten zien op bodem, productiviteit en biodiversiteit\nvan veenweidegrasland (LBI, 2023).</p><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Op alle veenweidebedrijven die drijfmest uitrijden. Mest scheiden\nvraagt een investering maar geeft meer stuurmogelijkheden voor\nperceel-specifiek bodembeheer. Dikke fractie is bij uitstek geschikt\nvoor percelen met ANLb-weidevogelbeheer of kruidenrijke\ngraslandpakketten.</p>","lit":null},{"titel":"Fosfaatbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Fosfaat (P) is op veenweidebedrijven zowel een\nnutriëntenbeheervraagstuk als een waterkwaliteitsvraagstuk. De\nfosfaattoestand varieert sterk tussen percelen — ook binnen één bedrijf\n— als gevolg van historische bemestingsverschillen. Door percelen met\nhoge P-toestand minder te bemesten en percelen met lage P-toestand iets\nmeer, kan de totale fosfaatbelasting van het oppervlaktewater worden\nverlaagd zonder productieverlies.</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Grote variatie in P-toestand tussen percelen.</strong>\nUit metingen op negen veenweidepercelen in de Proefpolder\nKringlooplandbouw bleek dat gras gemiddeld voldoende fosfor bevatte,\nmaar met grote variatie in bodem-P-toestand. Die variatie is direct\nterug te zien in het gras-P-gehalte (Van Rotterdam &amp; Pijlman,\n2019).</p></li>\n<li><p><strong>Gerichte mesttoedeling vermindert P-belasting.</strong>\nEen praktisch advies: percelen met lage P-toestand in de eerste snede 5\nm³ en gedurende het jaar 10 m³ drijfmest extra geven; percelen met hoge\nP-toestand eenzelfde hoeveelheid minder. Dit vermindert oppervlakkige\nuitspoeling en afspoeling naar sloten.</p></li>\n<li><p><strong>Dalende trend in P-CaCl₂.</strong> Lagere\nfosfaatgebruiksnormen na 2005 leidden tot een dalende P-beschikbaarheid\nin het bodemvocht, wat positief doorwerkt op de waterkwaliteit. De\nP-gehalten in voorjaarskuilen dalen nog, maar liggen op veel bedrijven\nnog boven de streefwaarde (Van Rotterdam &amp; Pijlman, 2019).</p></li>\n<li><p><strong>Fosfaat en waterkwaliteit.</strong> De grootste\nP-verliezen uit mest naar het oppervlaktewater treden op via ondiepe\nuitspoeling en oppervlakkige afspoeling. Bufferstroken onderscheppen een\ndeel hiervan, maar precisiebemesting fosfaat is een meer directe\nmaatregel aan de bron.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Precisiebemesting fosfaat vraagt bodemanalyses per perceel en een\nbewuste verdeling van de mestgift. Dit is geen ingrijpende investering\nmaar wel een gedragsverandering: niet alle percelen gelijk behandelen\nmaar differentiëren op basis van de P-toestand. De KringloopWijzer biedt\nhiervoor aanknopingspunten als startpunt.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Onbemeste bufferstroken —</strong> Bufferstroken\nonderscheppen oppervlakkige afspoeling van fosfaat; precisiebemesting\nvermindert de belasting aan de bron. Beide maatregelen zijn\ncomplementair.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Bodemkwaliteit en -bewaking —</strong> Perceel-specifieke\nP-toestand komt naar voren via bodemanalyses. Bodembewaking is de basis\nvoor precisiebemesting fosfaat.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>Van Rotterdam, D. en Pijlman, J. (2019).</strong>\n<em>Verbeteren benutting fosfaat in veenweiden — resultaten uit de\nProefpolder Kringlooplandbouw.</em> V-focus, augustus 2019, pp. 16–19.\nNMI / Louis Bolk Instituut.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/verbeteren-benutting-fosfaat-veenweiden.pdf</p><p><strong>Velstra, J., Van der Gaast, J., Kruisdijk, E., Verbruggen,\nM., Hoving, I., Smolders, F. en Lucassen, E. (2016).</strong> <em>Sturen\nop Nutriënten — dynamiek van nutriëntenlevering bij peilbeheer in\nveenweiden.</em> Acacia Water / WUR / B-WARE / VIC, Eindrapportage,\nprojectnummer 568.\nhttps://www.veenweiden.nl/wp-content/uploads/2023/12/Eindrapportage-Sturen-op-nutrienten.pdf</p>"}]},{"id":"toolbox-06-voer","naam":"Gewas en voer","introHtml":"<p>Gras is de basis van het veenweidebedrijf. Voederwinning,\neiwitbenutting en rantsoenstrategie zijn direct verbonden aan de\nveenspecifieke omstandigheden: hoge OEB in weidegras, wisselende\nvoerkwaliteit bij extensivering en vernatting, en de kans om met goed\nmanagement de eiwitimport sterk te verlagen.</p>","maatregelen":[{"titel":"Voederwinning en conservering","html":"<div class=\"ts\">WAT HET IS</div><p>Voederwinning omvat alle keuzes rond het maaien, drogen, inkuilen of\nhooien van gras. Op veenweidepercelen met uitgestelde maaidatum voor\nweidevogels en op percelen met kruidenrijke mengsels zijn de keuzes in\nvoederwinning extra complex: de maaidatum bepaalt tegelijk de\nvoederwaarde, de weidevogelgeschiktheid en de zodegezondheid.</p><div class=\"ts\">MAAIDATUM EN VOEDERWAARDE — DE KERN</div><p>Hoe later gemaaid, hoe lager de voederwaarde maar hoe meer structuur.\nOp veengrond speelt de hoge stikstofnalevering een extra rol: vroeg\ngemaaid gras bevat meer ruw eiwit dan melkkoeien benutten — dat\nveroorzaakt een OEB-overschot in het rantsoen. Later maaien verlaagt het\neiwitgehalte en de OEB, maar verlaagt ook de VEM. Het optimale\nmaaimoment op veen is dus een afweging tussen voederwaarde, OEB-sturing\nen weidevogelbelangen (Pijlman &amp; De Wit, 2019):</p><ul>\n<li><p><strong>4 mei-gras:</strong> hoog ruw eiwit, hoge VEM, hoge OEB.\nMoeilijk te sturen in rantsoen op veen.</p></li>\n<li><p><strong>25 mei-gras:</strong> betere balans. Bij langere\nveldperiode daalt OEB doordat oplosbaar eiwit afneemt en DVE\nstijgt.</p></li>\n<li><p><strong>11 juni-gras (uitgestelde maaidatum):</strong> lage VEM,\nlage OEB, veel structuur. Als hooi verrassend goed opneembaar door\nkoeien. Essentieel voor weidevogelbeheer maar vraagt aanpassing in\nrantsoensamenstelling.</p></li>\n</ul><div class=\"ts\">KUIL OF HOOI — KEUZE OP VEEN</div><p>Op veen is inkuilen de standaard, maar hooi heeft specifieke\nvoordelen voor extensieve bedrijven en weidevogelgrasland. Hooi van\nuitgestelde maaidatum (11 juni) had in onderzoek een vrijwillige opname\nvergelijkbaar met drogere meikuilen — ondanks lagere VEM. Dit heeft te\nmaken met de hogere structuurwaarde en lagere OEB van hooi. Voor\nextensieve bedrijven die OEB willen verlagen en structuurrijke ruwvoer\nwillen voeren is hooi van uitgestelde maaidatum een ondergewaardeerde\noptie (Pijlman &amp; De Wit, 2019).</p><div class=\"ts\">SMALLE WEEGBREE IN HET WINTERRANTSOEN</div><p>Kuil van smalle weegbree is goed inpasbaar in het winterrantsoen. Tot\ncirca een kwart smalle weegbree in het rantsoen had geen effect op\nvoeropname of eiwitproductie. Bij hogere aandelen daalde de\nmeetmelkproductie licht. Weegbreekuilen hebben gemiddeld wat minder ruw\neiwit en suiker dan graskuilen maar hogere mineralengehalten. De\nmethaanemissie per kg meetmelk leek iets lager bij weegbree in het\nrantsoen, maar dit verschil was niet significant (Pijlman et al.,\n2021).</p><div class=\"ts\">VOORBEWEIDEN — EFFECT OP GRASGROEI</div><p>Vroeg voorbeweiden in het voorjaar verlaagt de opbrengst van de\neerste snede met 12–20%, maar verhoogt het ruw-eiwitgehalte door\nverjonging van het gras. Op veen met uitgesteld maaibeleid is dit\ngunstig: een lichtere eerste snede is beter voor kuikenmobiliteit.\nVoorbeweiden stimuleert ook de mineralisatie via wortelexudaten die het\nbodemleven activeren (Rietberg et al., 2014; Hoekstra et al., 2020).</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Maaibeheer —</strong> Maaidatum is de directe\nsturingsvariabele die voederwaarde, weidevogelgeschiktheid en\nOEB-sturing verbindt. Voederwinning en maaibeheer zijn twee kanten van\ndezelfde beslissing.</td>\n</tr>\n<tr class=\"even\">\n<td></td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Weidevogelbeheer —</strong> Uitgestelde maaidatum is de\nprimaire weidevogelmaatregel; hooi van uitgestelde maaidatum is de\neconomische vertaling ervan — verkoopbaar of bruikbaar als ruwvoer met\neen acceptabele voederwaarde.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Pijlman, J. en De Wit, J. (2019).</strong> <em>Invloed\nmaaidatum op voederwaarde en opname.</em> V-focus, april 2019, pp.\n36–37. Louis Bolk Instituut / KTC Zegveld.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/invloed-maaidatum-op-voederwaarde-en-opname.pdf</p><p><strong>Pijlman, J., Bruinenberg, M., Koning, L. en Šebek, L.\n(2021).</strong> <em>Kwart smalle weegbree in winterrantsoen\nmogelijk.</em> V-focus, september 2021, pp. 26–27. Louis Bolk Instituut\n/ Wageningen Livestock Research.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/kwart-smalle-weegbree-winterrantsoen-mogelijk.pdf</p><p><strong>Rietberg, P., De Wit, J., Van Eekeren, N. en Iepema, G.\n(2014).</strong> <em>Stimuleert voorbeweiden grasgroei in\nvoorjaar?.</em> V-focus, 2014. Louis Bolk Instituut / Hogeschool Van\nHall Larenstein.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/2837.pdf</p>"},{"titel":"Eiwit van eigen land","html":"<div class=\"ts\">WAT HET IS</div><p>Eiwit van eigen land (EEL) is het aandeel eiwit in het rantsoen dat\nafkomstig is van het eigen bedrijf — niet aangekocht als krachtvoer,\nsojaschroot of bijproducten. Het kengetal wordt berekend via de\nKringloopWijzer: eigen geteeld eiwit gedeeld door totaal gevoerd eiwit,\nuitgedrukt in procenten. Het is een maat voor grondgebondenheid én voor\neiwitefficiëntie: een hoog EEL betekent minder afhankelijkheid van\ngeïmporteerde eiwitbronnen (soja, palmpit), lagere voerkosten en een\nbeter sluitende kringloop (WUR / PPP-Agro, 2022).</p><div class=\"ts\">WAAROM VEEN EEN APARTE POSITIE INNEEMT</div><p>Veengrond scoort structureel hoger op EEL dan klei- en zandgrond. Dat\nkomt door twee factoren die op veen samenvallen: het hoge\nstikstofleverend vermogen van veen (hoog NLV → veel eiwit in het gras)\nen de doorgaans extensievere bedrijfsvoering met meer grasland per koe.\nAnalyse van ruim 1.000 KringloopWijzers toont dat extensieve\nveenbedrijven relatief het hoogste EEL halen van alle grondsoorten (WUR\n/ PPP-Agro, 2022). Tegelijk geldt: een hoog EEL op veen betekent nog\nniet dat de eiwitbenutting optimaal is. Veenweidegras heeft van nature\neen hoge OEB — het rantsoen bevat meer eiwit dan de koe kan benutten,\nwat leidt tot hogere ureum- en ammoniak-verliezen. Op veen is de\nuitdaging daarmee niet alleen EEL verhogen maar ook de eiwitbenutting\nvan eigen gras verbeteren.</p><div class=\"ts\">ZES STUURKNOPPEN VOOR EEL</div><p>Op basis van analyse van KringloopWijzer-datasets zijn zes\nmanagementfactoren bepalend voor het EEL (WUR / PPP-Agro, 2022):</p><ul>\n<li><p><strong>Aandeel grasland in het bouwplan.</strong> Meer grasland\n= meer eigen eiwit. Op veenweidebedrijven is dit doorgaans al hoog — dit\nknopje zit grotendeels vast.</p></li>\n<li><p><strong>Aandeel vers gras in het rantsoen.</strong> Meer\nweidegang = meer vers gras in het rantsoen = hoger EEL. Elke dag extra\nweidegang verhoogt het EEL zonder aankoop van voer. Dit is de meest\ndirecte stuurknop voor veenweidebedrijven.</p></li>\n<li><p><strong>RE/VEM-verhouding in het rantsoen.</strong> Op veen is\ndit een tweesnijdend zwaard: veenweidegras heeft hoge RE bij lage VEM.\nBijvoeding met een laag OEB-krachtvoer verlaagt de RE/VEM-verhouding én\nvermindert eiwitaanvoer van buiten. Twee doelen tegelijk.</p></li>\n<li><p><strong>Graslandopbrengst per hectare.</strong> Hogere\ngrasproductie = meer eigen eiwit in de teller. Op veen bij hoog water\ndaalt de grasproductie echter gemiddeld 5% (Hoekstra &amp; Pijlman,\n2025) — dit knopje werkt op veen soms tégen hogere EEL bij\nvernatting.</p></li>\n<li><p><strong>Jongveebezetting.</strong> Minder jongvee per 10\nmelkkoeien = minder eiwit nodig in de noemer. Op extensieve\nveenweidebedrijven is de jongveebezetting al lager dan\ngemiddeld.</p></li>\n<li><p><strong>Krachtvoer per 100 kg melk.</strong> Minder krachtvoer =\nminder aangekocht eiwit = hoger EEL. Dit is de directe sturingsvariabele\nvoor de korte termijn. Op het Extensief Veenweide Verdienbedrijf werd\ngewerkt zonder of met minimaal krachtvoer van buiten — EEL was daarmee\nstructureel hoog (Pijlman et al., 2025).</p></li>\n</ul><div class=\"ts\">EFFECT VAN GRONDWATERPEILVERHOGING OP EEL</div><p>Vernatting heeft directe gevolgen voor het eiwitaanbod van eigen\nland. Uit het Living Lab Boeren op Hoog Water (Pijlman et al., 2025) en\nde studie van Hoekstra &amp; Pijlman (2025) komen de volgende effecten\nop EEL:</p><ul>\n<li><p><strong>Grasproductie daalt gemiddeld 5% bij GWS −20 cm.</strong>\nMinder grasopbrengst betekent minder eigen eiwit in de teller van de\nEEL-berekening. Bij gelijkblijvende eiwitbehoefte van de veestapel daalt\ndaarmee het EEL.</p></li>\n<li><p><strong>NLV daalt circa 6% bij hoog water.</strong> Het\nstikstofleverend vermogen van de veenbodem daalt doordat veenoxidatie en\nmineralisatie vertragen bij hogere grondwaterstand. Dit verlaagt het\neiwitgehalte in het gras, wat het EEL verder kan drukken.</p></li>\n<li><p><strong>Eiwitgehalte voorjaarsgras daalt bij minder\nbemesting.</strong> Op het extensieve bedrijf met lager bemestingsniveau\nwas een duidelijk negatief effect op het eiwitgehalte van het\nvoorjaarsgras zichtbaar — met name in het tweede jaar. Dit effect neemt\ntoe naarmate de bodemvruchtbaarheid daalt door de lagere\naanvoer.</p></li>\n<li><p><strong>Compensatie via rantsoensamenstelling.</strong> Een lager\neiwitgehalte in het eigen gras vermindert het OEB-overschot in het\nrantsoen — wat vanuit oogpunt van stikstofefficiëntie juist gunstig is.\nDe voederwaardedaling vraagt wel compensatie in de\nrantsoensamenstelling, passend bij het productiepotentieel van het\ngekozen ras.</p></li>\n</ul><p>De conclusie voor EEL bij vernatting is tweeledig: enerzijds daalt\nhet EEL door lagere grasopbrengst en lager eiwitgehalte; anderzijds\ndaalt ook de OEB-problematiek, waardoor de eiwitbenutting van eigen gras\nverbetert. Het absolute EEL-percentage en de stikstofefficiëntie kunnen\ndaarmee gelijktijdig in tegengestelde richting bewegen (Pijlman et al.,\n2025; Hoekstra &amp; Pijlman, 2025).</p><div class=\"ts\">VEEN EN HET EXTENSIEF VEENWEIDE VERDIENBEDRIJF</div><p>Op het Extensief Veenweide Verdienbedrijf (Pijlman et al., 2025) was\nde combinatie van lager bemestingsniveau, 100% eigen ruwvoer en minimale\nkrachtvoer-aanvulling het vertrekpunt. De lagere bemesting had een\nduidelijk negatief effect op de ruwvoerproductie — met name op het\neiwitgehalte in het voorjaarsgras. Tegelijk was de EEL per definitie\nhoog doordat nauwelijks eiwit van buiten werd aangekocht. De les: op\nveen is een hoog EEL relatief gemakkelijk te realiseren via\nextensivering, maar de voederwaardedaling van het eigen gras vraagt\ncompensatie in rantsoensamenstelling en rassenlijstkeuze.</p><div class=\"ts\">WANNEER TOEPASBAAR</div><p>EEL is via de KringloopWijzer voor elk bedrijf inzichtelijk te maken.\nDe stuurknoppen weidegang en krachtvoerreductie zijn direct toepasbaar\nop elk veenweidebedrijf. Graslandopbrengst verhogen als strategie werkt\nop veen beperkt bij hogere grondwaterstanden. Het meerjarig gemiddelde\n(drie jaar) geeft een betrouwbaarder beeld dan één jaarcijfer vanwege\nweerseffecten op gewasopbrengst — zeker op veen, waar droge jaren sterke\ninvloed hebben.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: HOOG EEL ≠ GOEDE EIWITBENUTTING OP\nVEEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Veenweidegras heeft een hoge OEB: meer eiwit dan de koe kan\nbenutten. Een hoog EEL op veen kan gepaard gaan met hoge\nammoniakverliezen via urine als het rantsoen niet actief wordt\nbijgestuurd. De doelstelling is dus niet alleen EEL maximaliseren maar\nook de OEB in het rantsoen verlagen — via bijvoeding met een laag\nOEB-krachtvoer of via uitgesteld maaien (latere snede heeft lagere OEB).\nEiwitefficiëntie en EEL samen zijn de juiste maatstaf voor\nveenweidebedrijven.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Beweidingssystemen —</strong> Meer weidegang is de meest\ndirecte stuurknop voor EEL.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Voederwinning en conservering —</strong> Uitgesteld maaien\n(lager eiwitgehalte) verlaagt de OEB in het rantsoen en verbetert\ndaarmee de eiwitbenutting van eigen gras.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Kruidenrijk productief grasland —</strong> Kruiden als\nsmalle weegbree en witte klaver verhogen de voederwaardediversiteit en\nmineralengehalte van het eigen ruwvoer zonder de eiwitproductie te\nverlagen.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Stikstofbemesting —</strong> Minder stikstof aanvoeren\nverlaagt het eiwitgehalte in het gras en de OEB — direct gunstig voor\neiwitbenutting, maar vraagt compensatie in de\nvoederwaarde-planning.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Extensief veenweide-ras —</strong> Een robuust dubbeldoelras\ndat goed functioneert bij wisselende voerkwaliteit en lage\nkrachtvoergift is de vee-component van de EEL-strategie.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>WUR / PPP-Agro Advies / BEL Leerdammer (2022).</strong>\n<em>Kennisdocument project 'Eiwit van Eigen Land' — update 2022.</em>\nWageningen University &amp; Research / PPP-Agro Advies, Zegveld, juli\n2022. https://edepot.wur.nl/579883</p><p><strong>WUR / PPP-Agro Advies / BEL Leerdammer (2021).</strong>\n<em>Eiwit van Eigen Land — brochure concrete maatregelen voor meer eiwit\nvan eigen land.</em> Wageningen University &amp; Research / PPP-Agro\nAdvies / ZuivelNL. https://edepot.wur.nl/530990</p><p><strong>Honkoop, W. (2021).</strong> <em>Resultaten KringloopWijzers\nProefpolder Kringlooplandbouw.</em> PPP-Agro Advies, deelrapportage\nProefpolder Kringlooplandbouw.\nhttps://www.veenweiden.nl/wp-content/uploads/2021/03/Deelrapportage-Proefpolder-Kringlooplandbouw-PPP-Agro-Advies.pdf</p>"},{"titel":"Rantsoen op maat","html":"<div class=\"ts\">WAT HET IS</div><p>Het rantsoen op een veenweidebedrijf is de som van weidegras,\ngraskuil, eventueel hooi en krachtvoer of bijproducten. Op veen heeft\nhet rantsoen structureel andere kenmerken dan op droge grond: het\nweidegras heeft een hoog eiwitgehalte (hoge OEB), de ruwvoerkwaliteit\nvarieert meer met het seizoen en de maaidatum, en bij extensivering of\nvernatting daalt de voederwaarde van het eigen gras. Rantsoen op maat is\nhet afstemmen van bijvoeding op die veenspecifieke rantsoenkenmerken —\nniet het volgen van een generiek voerschema.</p><p><strong>DE KERN: OEB-STURING OP VEEN</strong></p><p>Het meest onderscheidende rantsoenprobleem op veen is de hoge\nonbestendige eiwitbalans (OEB) van veenweidegras. Gras dat vroeg in het\nseizoen wordt geweid of gemaaid heeft een RE/VEM-verhouding die\nstructureel boven de behoefte van de koe uitkomt. Dit leidt tot:</p><ul>\n<li><p>Hoog ureumgehalte in de melk (indicator van\neiwitoverschot).</p></li>\n<li><p>Hogere N-verliezen via urine en daarmee hogere\nammoniakemissie.</p></li>\n<li><p>Eiwitimport die vermijdbaar is als de bijvoeding correct is\nafgestemd.</p></li>\n</ul><p>De oplossing is niet minder weidegras maar slimmere bijvoeding:\nkrachtvoer of ruwvoeraanvulling met een lage OEB compenseert het\nOEB-overschot in het weidegras zonder productieverlie. Onderzoek toont\naan dat een lager OEB-niveau in het krachtvoer de meetmelkproductie niet\nverlaagt bij kurzrasen of stripgrazen op veen — maar de N-benutting\nstijgt en de ammoniakemissie daalt (Hoekstra et al., 2017; 2022).</p><div class=\"ts\">NATUURGRAS EN EXTENSIEF GRASLAND IN HET RANTSOEN</div><p>Op extensieve veenweidebedrijven en bedrijven met ANLb-grasland\ngroeit het aandeel vezelrijk, eiwitarm gras in het ruwvoerpakket. Het\ngangbare voermodel beoordeelt dit gras als suboptimaal. Dat is\nonterecht: de koe is een herkauwer die uit vezelrijke voeders méér\nenergie kan halen dan het voederwaardemodel berekent. Praktijkonderzoek\ntoont dat koeien goed melk geven op een rantsoen met tot 17%\nbotanisch/natuurgras zonder meetbare productiedaling. Bij 33–50% daalt\nde melkgift beperkt (2–3 kg/koe/dag). Het voermodel is aan herziening\ntoe voor vezelrijke graslanden (Migchels &amp; Van Duinkerken,\n2008).</p><div class=\"ts\">RANTSOEN BIJ HOOG WATER EN EXTENSIVERING</div><p>Bij vernatting (GWS −20 cm) daalt de grasproductie gemiddeld 5% en\nhet eiwitgehalte van het voorjaarsgras daalt bij lager bemestingsniveau.\nDit heeft directe gevolgen voor het rantsoen:</p><ul>\n<li><p>Minder eigen ruwvoer beschikbaar of lagere voederwaarde.</p></li>\n<li><p>Het OEB-overschot in het weidegras neemt af — wat de\neiwitbenutting verbetert.</p></li>\n<li><p>Compensatie via gerichte kunstmestgift is mogelijk zonder\nefficiëntieverlies; N-benutting uit kunstmest is gelijk bij hoog en laag\nwater (Hoekstra &amp; Pijlman, 2025).</p></li>\n</ul><p>Het rantsoen bij hoog water vraagt dus een aanpassing in de\nbijvoedingsstrategie: minder eiwit corrigeren, meer energie aanvullen\nals de grasopbrengst tegenvalt. Een robuust ras dat functioneert bij\nwisselende voerkwaliteit vermindert de rantsoengevoeligheid.</p><div class=\"ts\">ZES KNOPPEN VOOR RANTSOENOPTIMALISATIE OP VEEN</div><ul>\n<li><p><strong>OEB bijvoeding verlagen.</strong> Kies krachtvoer met\nlaag OEB-niveau als het weidegras een hoge OEB heeft. Geen\nproductieverlie, wel lagere N-verliezen (Hoekstra et al., 2017;\n2022).</p></li>\n<li><p><strong>Maaidatum als OEB-sturingsinstrument.</strong> Later\nmaaien geeft lager eiwitgehalte en lagere OEB in het ruwvoer. Hooi van\nuitgestelde maaidatum is laag in OEB en hoog in structuur (Pijlman &amp;\nDe Wit, 2019).</p></li>\n<li><p><strong>Weegbree in het rantsoen.</strong> Tot een kwart smalle\nweegbree in het winterrantsoen heeft geen effect op voeropname of\neiwitproductie. Weegbree heeft hogere mineralengehalten dan gras en een\niets lagere OEB (Pijlman et al., 2021).</p></li>\n<li><p><strong>Natururgras en botanisch grasland inpassen.</strong>\nVezelrijk grasland uit ANLb- of beheerspercelen is bruikbaar tot 17% van\nhet rantsoen zonder productieproblemen. Herkauwen haalt meer energie uit\ndit gras dan het voermodel berekent (Migchels &amp; Van Duinkerken,\n2008).</p></li>\n<li><p><strong>Jongveebezetting verlagen.</strong> Minder jongvee per 10\nmelkkoeien verlaagt de eiwitbehoefte van de veestapel en verhoogt het\neiwit van eigen land.</p></li>\n<li><p><strong>Krachtvoerkeuze sturen op herkomst.</strong> Krachtvoer\nuit gangbare akkerbouw bevat structureel pesticidresiduen die via de\nmest de mestfauna schaden. Biologisch krachtvoer of bijproducten met\nlage residubelasting is een insectenbeheer- én rantsoenkeuze tegelijk\n(Bruinenberg &amp; Van Eekeren, 2023).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Rantsoenoptimalisatie begint bij de KringloopWijzer: ureumgehalte in\nde melk, RE/VEM-verhouding in het rantsoen en kg krachtvoer per 100 kg\nmelk zijn de drie directe indicatoren. Een hoog ureum (&gt;25) op veen\nwijst altijd op een OEB-overschot dat corrigeerbaar is via bijvoeding of\nmaaidatum. Er is geen standaard veenweidenrantsoen — de juiste aanpak\nhangt af van de graslandkwaliteit, het beweidingssysteem en de\nbedrijfsintensiteit.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Beweidingssystemen —</strong> Het beweidingssysteem bepaalt\nde OEB van het weidegras in het rantsoen. Kurzrasen geeft constant jong,\nbladrijk gras met hoge OEB; uitgesteld maaien en hooi verlagen de\nOEB.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Eiwit van eigen land —</strong> Rantsoenoptimalisatie via\nminder krachtvoer verhoogt het EEL. OEB-sturing en EEL zijn twee kanten\nvan dezelfde medaille.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Ammoniakemissie beperken —</strong> Lagere TAN-excretie via\nOEB-sturing is de meest directe rantsoenknop voor\nammoniakemissiereductie.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Insectenbeheer —</strong> Krachtvoerkeuze op herkomst en\nresidubelasting is een rantsoenbeslissing met directe effecten op\nmestfauna.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Extensief veenweide-ras —</strong> Een robuust dubbeldoelras\nfunctioneert beter bij wisselende ruwvoerkwaliteit en verlaagde\nkrachtvoergift.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>Hoekstra, N., Van Eekeren, N., Holshof, G., Rijneveld, H.,\nVan Houwelingen, K. en Lenssinck, F. (2017).</strong>\n<em>Systeeminnovatie Beweiden Veenweiden — eindrapportage\n2015–2016.</em> Louis Bolk Instituut, rapportnummer 2017-009 LbD.\nhttps://www.veenweiden.nl/wp-content/uploads/2017/10/Systeeminnovatie-Beweiden-Veenweiden1.pdf</p><p><strong>Migchels, G. en Van Duinkerken, G. (2008).</strong>\n<em>Koeien geven goed melk op rantsoen met natuurgras.</em> Syscope,\nWageningen University &amp; Research. https://edepot.wur.nl/28128</p>"}]},{"id":"toolbox-07-vee","naam":"Vee en dierenwelzijn","introHtml":"<p>Het vee is het meest zichtbare onderdeel van het veenweidebedrijf —\nmaar in de verduurzamingsdiscussie ook het minst besproken. Rassenkeuze,\nopfok, koe-kalf-systemen en dierenwelzijn zijn minstens even bepalend\nvoor de bedrijfsidentiteit en de maatschappelijke acceptatie van de\nsector.</p>","maatregelen":[{"titel":"Koe-kalf-kudde","html":"<div class=\"ts\">WAT HET IS</div><p>In het gangbare melkveebedrijf wordt het kalf binnen 24 uur na\ngeboorte van de moeder gescheiden. Koe-kalf-systemen laten koe en kalf\nlanger bij elkaar — variërend van partieel contact (naast elkaar, geen\nzuigen) tot volledig contact met onbeperkt zuigen. De term\n'koe-kalf-kudde' verwijst naar systemen waarbij het kalf voor een\nperiode van meerdere weken bij de koe blijft en deel uitmaakt van de\nkoppel. Dit is een van de meest maatschappelijk gevoelige thema's in de\nmelkveehouderij.</p><div class=\"ts\">DRIE SYSTEMEN</div><ul>\n<li><p><strong>Geen contact (NC).</strong> Standaard in Nederland: kalf\nwordt direct na geboorte verwijderd, individueel opgefokt op\nemmermachine of kunstspeen.</p></li>\n<li><p><strong>Partieel contact (PC).</strong> Kalf naast de koe,\nnaast-naast-contact mogelijk (zien, ruiken, likkken) maar geen zuigen.\nIntermediaire optie die dierenwelzijn verbetert zonder melkopbrengst te\nverliezen.</p></li>\n<li><p><strong>Volledig contact (FC).</strong> Kalf bij de koe in de\nkoppel, onbeperkt zuigen. Meer groei, andere microbioomopbouw, maar meer\ngezondheidsproblemen door huisvestingscondities en hogere infectiedruk\nin een koppel gericht op volwassen koeien.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN</div><p>Uit een gecontroleerde proef met 48 Holstein Friesian koeien\ngedurende de eerste 7 weken post partum (Wenker et al., 2022):</p><ul>\n<li><p><strong>Groei.</strong> FC-kalveren groeiden significant sneller\n(1,03 kg/dag) dan NC- en PC-kalveren (0,72 en 0,75 kg/dag). Op 6 maanden\nleeftijd was er geen verschil meer — het groeiverschil egaliseert na\nspenen.</p></li>\n<li><p><strong>Gezondheid kalveren.</strong> FC-kalveren hadden\nsignificant meer gezondheidsproblemen (hogere totale gezondheidsscore,\nP=0,02) en een trend naar meer antibioticagebruik dan NC-kalveren. Dit\nwerd deels verklaard door suboptimale huisvesting: bestaande\nkoeienstallen zijn niet ontworpen voor jonge kalveren.</p></li>\n<li><p><strong>Microbioom.</strong> FC-kalveren hadden een andere fecale\nmicrobioomsamenstelling met hogere abundantie van Lactobacillus, wat\nprobiotiefuncties biedt. Of dit op langere termijn gunstig is, is nog\nonbekend.</p></li>\n<li><p><strong>Melkproductie koeien.</strong> FC-koeien hadden\nsignificant minder machine-gemolken melk (17 kg/dag vs. 29 kg/dag bij\nNC/PC) en lager vetgehalte. Koeien die zogen geven een groot deel van\nhun melk rechtstreeks aan het kalf.</p></li>\n<li><p><strong>Koegezondheid.</strong> Niet beïnvloed door het type\nsysteem. Uiergezondheid bleef goed bij alle systemen.</p></li>\n<li><p><strong>Partieel contact als compromis.</strong> PC scoort op\nvrijwel alle parameters tussenin — het is een haalbare tussenstap die\ndierenwelzijn verbetert (sociale interactie, gedragsmogelijkheden)\nzonder significante gezondheidsrisico's voor het kalf of melkverlies\nvoor de boer.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Koe-kalf-systemen zijn technisch haalbaar op elk bedrijf maar vragen\naanpassing van huisvesting, management en mentale omslag. Volledig\ncontact vraagt specifieke infrastructuur voor kalveren in de koeiengroep\n(creep area, aparte ligplaatsen). Partieel contact is relatief eenvoudig\nte implementeren. Op extensieve veenweidebedrijven met een biologisch of\nmaatschappijgeoriënteerd businessmodel past koe-kalf-contact goed bij de\nbedrijfsidentiteit.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: SPENEN IS EEN KRITIEK MOMENT</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Het spenen en scheiden van koe en kalf na een periode van volledig\ncontact is een stressvol moment voor beide dieren. Graduele spening\n(geleidelijk minder contact) vermindert de stress significant. Abrupt\nscheiden na langdurig contact geeft de sterkste stressrespons — dit is\nhet voornaamste managementknelpunt bij FC-systemen en vraagt een\ndoordachte aanpak (Wenker et al., 2022).</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Extensief veenweide-ras —</strong> Bij extensieve bedrijven\ndie inzetten op koe-kalf-contact past een ras dat minder gericht is op\nmaximale melkproductie en meer op dubbeldoel (melk + vlees). Dit\nverlaagt het economische verlies van de kalf-gerelateerde\nmelkreductie.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Wenker, M.L., Verwer, C.M., Bokkers, E.A.M., te Beest, D.E.,\nGort, G., de Oliveira, D., Koets, A., Bruckmaier, R.M., Gross, J.J. en\nVan Reenen, C.G. (2022).</strong> <em>Effect of Type of Cow-Calf Contact\non Health, Blood Parameters, and Performance of Dairy Cows and\nCalves.</em> Frontiers in Veterinary Science, Volume 9, artikel 855086.\ndoi:10.3389/fvets.2022.855086</p>"},{"titel":"Dynamisch draadloos weiden","html":"<div class=\"ts\">WAT HET IS</div><p>Dynamisch draadloos weiden (virtual fencing) is een systeem waarbij\nkoeien via een halsband worden gestuurd door akoestische signalen en,\nindien nodig, een licht elektrisch impulssignaal. Er is geen fysieke\nafrastering meer nodig. De grenzen worden ingetekend in software en\nkunnen dagelijks of meerdere keren per dag worden aangepast. In het\nveenweidegebied is de technologie onderzocht voor twee\nhoofdtoepassingen: bescherming van slootkanten en greppels, en flexibele\nbeweidingssturing (Janssen et al., 2026).</p><div class=\"ts\">WAT HET DOET</div><p>Het systeem maakt het mogelijk om percelen gedeeltelijk te beweiden,\nkoeien van kwetsbare zones weg te houden en beweidingsgrenzen aan te\npassen aan draagkracht, weidevogelnesten of greppelligging — zonder\nrijdraad te plaatsen of te verplaatsen. Dit is het kernvoordeel ten\nopzichte van stripgrazen: de voordelen van dagelijkse beweidingssturing\nzijn bereikbaar zonder de arbeidsintensieve rijdraadinfrastructuur.</p><div class=\"ts\">WAT WE WETEN — PRAKTIJKPROEVEN 2025</div><p>Twee praktijkproeven in 2025 (biologisch bedrijf Reeuwijk en KTC\nZegveld) geven het meest actuele beeld (Janssen et al., 2026):</p><ul>\n<li><p><strong>Slootkantbescherming werkt.</strong> Bij uitrastering op\n2 meter van de waterlijn was al een duidelijke afname in\nslootkantgebruik zichtbaar. Bij 3–4 meter was de bescherming robuuster.\nVolledige uitsluiting werd niet bereikt — incidenteel gebruik bleef\nvoorkomen.</p></li>\n<li><p><strong>Drinkplaats is het knelpunt.</strong> Een drinkplaats van\n12 meter breed werd het meest gebruikt, maar ging gepaard met\nvertrapping van de slootkant. Smallere drinkplaatsen werden minder\nbenut. Conclusie: bij slootkantbescherming als primair doel is het\nlogischer drinkwater via een drinkbak te organiseren.</p></li>\n<li><p><strong>Greppelbescherming is minder robuust.</strong> Bij het\nuitrasteren van greppels (3 meter aan weerszijden) was koeverkeer in de\nuitgerasterde zone 93% lager — maar volledige uitsluiting werd niet\nbereikt. Koeien staken over op de kopakker. Effectiviteit is sterker\nafhankelijk van perceelindeling en individueel diergedrag dan bij\nslootkanten.</p></li>\n<li><p><strong>Geen nadelige effecten op dierenwelzijn\naangetoond.</strong> Melkcortisol was hoger één week na training en bij\nafsluiting van de slootkant, maar was niet gerelateerd aan het aantal\nontvangen schokken. Op de eerste twee trainingsdagen waren de meeste\nschokken, maar cortisol was gelijk aan de periode vóór training. Dit\npast in het bredere beeld uit eerder onderzoek.</p></li>\n<li><p><strong>Werkbaarheid in beweidingssystemen.</strong> Koeien leren\nomgaan met draadloze afrastering ongeacht het beweidingssysteem — zowel\nbij dagelijks als wekelijks omweiden. Geen effect op voeropname,\nmelkproductie of cortisolwaarden vergeleken met fysieke afrastering.\nDagelijks omweiden geeft een hogere vertrouwensratio: koeien zoeken\nvrijwilliger de grens op. Weidegang zelf verlaagde het stressniveau\nongeacht het afrasteringssysteem (Burgers et al., 2025).</p></li>\n<li><p><strong>Minimale uitsluitingsgrootte voor\nbiodiversiteit.</strong> Voor bescherming van weidevogelnesten is een\nminimale uitsluitingsdiameter van 15 meter nodig. Een uitsluiting van\n9×9 meter was onvoldoende — koeien betraden het nest nog. Tussen twee\nafzonderlijke draadloze afrasteringen moet minimaal 15 meter afstand\nzijn om verwarring bij koeien te voorkomen (Janssen et al.,\n2025).</p></li>\n<li><p><strong>Greppeluitrastering vraagt minimaal 8 meter aan\nweerszijden.</strong> Bij 4 meter was al een duidelijke vermindering van\nbegrazing; bij 8 meter was de bescherming robuust. Smallere\nuitsluitingen gaven te veel overschrijdingen door GPS-onnauwkeurigheid\n(Janssen et al., 2025).</p></li>\n<li><p><strong>Relatie met stripgrazen.</strong> Virtual fencing past\nhet best bij dagelijks omweiden (stripgrazen): de dagelijkse\ngrensverplaatsing die normaal met rijdraad plaatsvindt wordt vervangen\ndoor een app-aanpassing. Dagelijks omweiden met virtual fencing geeft de\nhoogste vertrouwensratio — koeien leren het systeem sneller door de\nfrequente confrontatie met de grens (Burgers et al., 2025).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Virtual fencing is beschikbaar als commercieel product (Nofence,\nGallagher eShepherd). De technologie werkt betrouwbaar als\nbeweidingssysteem zowel bij dagelijks als wekelijks omweiden. Voor\nbiodiversiteitsdoelen (nestbescherming, greppeluitrastering) werkt het\nmits aan de minimale afmetingen wordt voldaan. Op smalle\nveenweidepercelen met meerdere parallelle greppels op korte onderlinge\nafstand is het systeem momenteel niet bruikbaar — de\n15-meter-minimumafstand tussen uitsluitingen laat op een 20-meter-breed\nperceel te weinig beweidingsruimte over.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: GPS-NAUWKEURIGHEID BEPAALT DE MINIMALE\nSCHAAL</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>De GPS-nauwkeurigheid van Nofence-halsbanden is 3 meter. Dit bepaalt\nde minimale uitsluitingsgrootte: 15 meter diameter voor nestbescherming,\n8 meter aan weerszijden voor greppels. Smalle veenweidepercelen van\n10–30 meter met greppels op 6–10 meter afstand laten bij meerdere\nparallelle uitsluitingen nauwelijks beweidingsruimte over. Bovendien\nmoet tussen twee draadloze afrasteringen minimaal 15 meter zitten om\nverwarring bij koeien te voorkomen. Op percelen met meerdere greppels\ndicht bij elkaar is het systeem momenteel niet bruikbaar (Janssen et\nal., 2025).</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Beweidingssystemen —</strong> Sluit het best aan bij\ndagelijks omweiden (stripgrazen): de dagelijkse grensverplaatsing\nvervangt het rijdraad verzetten. Dagelijks omweiden geeft de sterkste\nleercurve voor koeien met virtual fencing.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Oeverbeheer —</strong> Slootkantbescherming via virtual\nfencing op 3–4 meter van de waterlijn werkt goed als alternatief voor\nfysiek uitrasteren, maar volledige uitsluiting is niet\ngegarandeerd.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Weidevogelbeheer —</strong> Nestbescherming via virtual\nfencing is bewezen haalbaar bij uitsluitingen van minimaal 15 meter\ndiameter. Dit biedt ook een bijkomend voordeel: de nestlocatie blijft\nbeter verborgen voor predatoren dan bij een gemarkeerd\nnestcirkeltje.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Greppelinfiltratie —</strong> Greppeluitrastering vraagt\nminimaal 8 meter aan weerszijden. Op veenweidepercelen met smalle\ngreppelafstanden bij greppelinfiltratie (6–10 m) laat dit nauwelijks\nruimte over. Open technisch vraagstuk.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Janssen, P., Bonekamp, G. en Bestman, M. (2026).</strong>\n<em>Toepassing van draadloze afrastering (virtual fencing) op\npraktijkbedrijven: bescherming van slootkanten, beperking van\nvertrapping en effecten op dierenwelzijn.</em> Louis Bolk Instituut /\nWageningen Livestock Research, publicatienummer 2026-7386-LbD. In\nopdracht van VIC/VIPNL.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/toepassing-van-draadloze-afrastering-virtual-fencing-op-praktijkbedrijven-bescherming-van.pdf</p>"},{"titel":"Passende koe","html":"<div class=\"ts\">WAT HET IS</div><p>De keuze van het melkveeras is op het veenweidebedrijf geen neutrale\nbeslissing. De dominante Holstein Friesian (HF) is gefokt voor maximale\nmelkproductie op een rantsoen met veel krachtvoer en een droge,\ndraagkrachtige bodem. Op natte veengrond met een extensief beheer, lager\nbemestingsniveau en voer van eigen land stelt de omgeving andere eisen\naan de koe. De zoektocht naar een 'passende veenweidekoe' combineert\ntwee vragen: welke rasgerelateerde kenmerken zijn essentieel voor\nbeweiding op veen, en biedt een dubbeldoelras (melk én vlees) een beter\nverdienmodel bij extensieve bedrijfsvoering?</p><div class=\"ts\">WAT DE VEENWEIDEKOE MOET KUNNEN</div><p>Op basis van de Discussiemiddag Veenweidekoe (Schoon et al., 2022) en\nde ervaringen met het Extensief Veenweide Verdienbedrijf (Pijlman et\nal., 2025) zijn vier dierkenmerken bepalend voor geschiktheid op\nveen:</p><ul>\n<li><p><strong>Lichte voetafdruk en goede draagkracht.</strong> Hoe\nzwaarder de koe, hoe groter de bodemdruk per stap. Op slappe veenbodem\nleidt een zware koe tot meer vertrapping, zodeschade en baggeraanwas.\nEen lichter ras vermindert de bodemdruk bij elk beweidingssysteem —\nzonder aanpassingen in het systeem zelf (Schoon et al., 2022).</p></li>\n<li><p><strong>Goed beenwerk en klauwgezondheid.</strong> Koeien op veen\nlopen meer dan op droge grond: natte percelen, looppaden langs sloten en\nslootdoorgangen zijn structureel belastend voor klauwen. Een ras met\nsterke benen en robuuste klauwen heeft minder klauwaandoeningen en een\nlangere productieve levensduur (Schoon et al., 2022).</p></li>\n<li><p><strong>Graas- en vreetgedrag.</strong> Koeien op extensief\nveenweidebedrijf lopen meer om voldoende gras op te nemen op korte,\nnatte vegetatie. Ze mogen niet kieskeurig zijn bij wisselende\ngraslandkwaliteit — een eigenschap die de HF bij extensieve\nomstandigheden minder heeft dan dubbeldoelrassen (Schoon et al.,\n2022).</p></li>\n<li><p><strong>Robuustheid bij wisselend voeraanbod.</strong> Bij hoog\nwater en minder bemesting varieert de ruwvoerkwaliteit meer dan op een\nintensief bedrijf. Een robuust ras houdt conditie en productie op peil\nbij een periode van mindere voerkwaliteit — zonder in te leveren op\ndiergezondheid (Schoon et al., 2022; Pijlman et al., 2025).</p></li>\n</ul><div class=\"ts\">DE GRONINGER BLAARKOP ALS PRAKTIJKVOORBEELD</div><p>Het Extensief Veenweide Verdienbedrijf werkte met Groninger\nBlaarkopkoeien — een traditioneel Nederlands dubbeldoelras. De\nervaringen (Pijlman et al., 2025):</p><ul>\n<li><p><strong>Gezondheid.</strong> Over het algemeen weinig\ngezondheidsproblemen. Koeien bleven goed in conditie, ook na besmetting\nmet Blauwtong. Dit past bij de bekende robuustheid van het ras.</p></li>\n<li><p><strong>Melkproductie.</strong> Lager dan op een intensief\nHF-bedrijf, maar hoger dan op een volledig grasgevoerd Blaarkopbedrijf.\nDe combinatie van een matig bemestingsniveau met beperkte\nkrachtvoer-aanvulling gaf een aanvaardbare productie.</p></li>\n<li><p><strong>Vleescomponent als extra inkomensstroom.</strong> De\nBlaarkop levert naast melk ook vlees van betere kwaliteit dan de HF.\nStieren en overtollige vaarzen zijn verkoopbaar als dubbeldoelkalf of\nals vleesvee. Dit is de kern van het extensieve verdienmodel: minder\nmelk per koe compenseren met hogere opbrengst per dier.</p></li>\n<li><p><strong>Draagkracht.</strong> Beweidingspercelen hadden een\nhogere draagkracht dan maaipercelen doordat de graszode onder beweiding\ndichter bleef — een effect dat onafhankelijk is van het ras maar\nversterkt wordt door de lichtere voetafdruk van de Blaarkop ten opzichte\nvan een zware HF.</p></li>\n</ul><p><strong>HOLSTEIN FRIESIAN — IS INKRUISEN EEN\nALTERNATIEF?</strong></p><p>De discussie over de veenweidekoe richt zich niet alleen op\nrasvervanging maar ook op inkruisen. De HF biedt grote genetische\nvariatie en er zijn stierlijnen die scoren op beenwerk, klauwgezondheid\nen efficiëntie. Het Friese Veenweideprogramma en WLR concluderen dat er\ngeen standaard fokdoel voor alle veenweidebedrijven geldt: de keuze\nhangt af van de specifieke bedrijfsvisie, het beweidingssysteem en de\nmate van extensivering. Wel is de richting duidelijk: weg van het pure\nmaximale melkproductie-fokdoel, richting meer aandacht voor functionele\nkenmerken (Schoon et al., 2022).</p><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Een rassenkeuze is een langetermijnbeslissing die niet van de ene op\nde andere dag te maken is. Relevante momenten: bij bedrijfsuitbreiding,\nbij een transitie naar een extensiever beweidingssysteem, bij\nstructurele klauwaandoeningen in de koppel, of bij de overweging om een\nverdienmodel op te bouwen rond dubbeldoelmelk of vlees. Inkruisen met\neen lichtere of robuustere stierlijn kan stapsgewijs worden doorgevoerd\nzonder het hele bedrijfssysteem te veranderen.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: GEEN EENDUIDIG FOKDOEL VOOR\nIEDEREEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>De 'passende veenweidekoe' bestaat niet als universeel type.\nBedrijven die inzetten op maximale melkproductie per ha hebben andere\neisen dan bedrijven die kiezen voor extensivering en biodiversiteit. De\ndiscussie over het fokdoel is pas relevant als eerst de\nbedrijfsdoelstelling helder is. Rasvervanging zonder aanpassing van het\nbedrijfssysteem geeft weinig meerwaarde (Schoon et al., 2022).</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Beweidingssystemen —</strong> Een lichter ras vermindert de\nbodemdruk bij elk beweidingssysteem. De combinatie van een lichte koe\nmet kurzrasen of extensief RSW is het meest gunstig voor draagkracht en\nzodeherstel.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Draagkrachtbeheer —</strong> Rasgewicht is een van de\nweinige factoren in het draagkrachtvraagstuk die de boer volledig zelf\nbepaalt. Een lichtere koe geeft meer beweidingsdagen per jaar op natte\nveengrond.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Koe-kalf-kudde —</strong> Bij een dubbeldoelras als de\nBlaarkop is koe-kalf-contact economisch logischer: het kalf heeft een\nhogere vlees- en opfokwaarde, wat het inkomensverlies bij volledig\ncontact deels compenseert.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Rantsoen en eiwit van eigen land —</strong> Een\ndubbeldoelkoe op extensief bedrijf met 100% eigen voer vraagt een\nrobuust ras dat ook bij lagere VEM en wisselende OEB goed blijft\nfunctioneren. Dit is precies wat de Blaarkop in de praktijk liet\nzien.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>Schoon, M.A., Bonekamp, G. en Hiemstra, S.J. (2022).</strong>\n<em>Discussiemiddag Veenweidekoe — wat zijn de gevolgen van hoogwater\nvoor het boerenbedrijf en wat wordt er van de koeien verwacht?.</em>\nWageningen Livestock Research, mei 2022.\nhttps://edepot.wur.nl/588220</p><p><strong>Pijlman, J., Hoekstra, N., Bestman, M., Honkoop, W., Beek,\nJ., Van Houwelingen, K. en Van der Weijde, H. (2025).</strong>\n<em>Extensief Veenweide Verdienbedrijf — eindrapportage: testen van een\nintegrale maatregelenset bij hoog grondwaterpeil en minder\nbemesting.</em> Louis Bolk Instituut / PPP-Agro Advies / KTC Zegveld,\napril 2025.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/extensief-veenweide-verdienbedrijf.pdf</p><p><strong>Lenssinck, F. (red.) (2022).</strong> <em>De trots van de\nKrimpenerwaard — resultaten Proeftuin Trots op de Krimpenerwaard.</em>\nLouis Bolk Instituut / Proeftuin Krimpenerwaard, mei 2022.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/de-trots-van-de-krimpenerwaard.pdf</p>"}]},{"id":"toolbox-08-stal","naam":"Stal en emissies","introHtml":"<p>Ammoniakemissie uit de melkveehouderij draagt bij aan eutrofiëring\nvan natuurgebieden en verzuring van de bodem. Veenweidebedrijven hebben\neen hogere gemiddelde emissie dan bedrijven op klei en zand. Tegelijk is\ner grote spreiding: voorloperbedrijven in de Proeftuin Veenweiden\nrealiseerden 25% reductie zonder productieverlies. De opgave is reëel en\nhaalbaar — maar vraagt een samenhangende aanpak van stal, weide en\nmesttoediening.</p>","maatregelen":[{"titel":"Ammoniakemissie","html":"<div class=\"ts\">WAT HET IS</div><p>Ammoniakemissie (NH₃) ontstaat op elk punt waar stikstof de keten\nverlaat: in de stal (urine en mest), bij mestopslag, bij mesttoediening\nop het land (veldemissie) en bij beweiding. Op veenweidebedrijven is de\ngemiddelde veldemissie 42,5 kg NH₃/ha en de stalemissie 1,81 kg NH₃ per\nton melk. Rond deze gemiddelden is grote spreiding: 12% van de\nveenweidebedrijven scoort al structureel onder het gemiddelde (Verloop\net al., 2018).</p><p><strong>DE STRATEGIE: LEKKEN DICHT</strong></p><p>De kern van de ammoniakstrategie op veen is niet één maatregel maar\neen systeemaanpak in twee stappen (Verloop et al., 2018):</p><ul>\n<li><p><strong>Stap 1 — Stikstofkraan bijstellen.</strong> De\nstikstofstroom door het bedrijf niet hoger maken dan nodig: minder\nkunstmest, lager eiwitgehalte in het rantsoen (lagere TAN-excretie),\nminder jongvee. Zonder deze stap compenseert het bedrijf elke dichte lek\nvia andere lekken.</p></li>\n<li><p><strong>Stap 2 — Lekken dichten.</strong> Als de stikstofstroom\nis beperkt, worden specifieke emissiepunten aangepakt: mesttoediening,\nstal, opslag, beweidingsbeheer.</p></li>\n</ul><div class=\"ts\">MAATREGELEN PER EMISSIEPUNT</div><p><strong>Veldemissie — laag hangend fruit</strong></p><ul>\n<li><p><strong>Meer en langer beweiden.</strong> Weidegang verlaagt de\nstalemissie (minder mest in de stal) én de veldemissie (directe\ndepositie van kleine porties urine op het land verdampt minder dan\nuitgereden mest). Dit is de meest effectieve maatregel op\nveenweidebedrijven (Verloop et al., 2018).</p></li>\n<li><p><strong>Verdund mest aanwenden.</strong> Verdunnen van drijfmest\nmet water verlaagt de NH₃-emissie bij toediening doordat de concentratie\nammonium in de mest daalt en de mest dieper in de zode dringt. Effect:\n20–40% reductie van de veldemissie bij aanwending.</p></li>\n<li><p><strong>Sleepvoet of zodenbemester.</strong> Emissiearme\naanwendingstechnieken brengen de mest dichter bij de wortelzone en\nverminderen het contactoppervlak met de lucht. Op veengrond vermindert\nde sleepslang ook rijspoorschade — een dubbel voordeel.</p></li>\n<li><p><strong>Minder kunstmestgebruik.</strong> Kunstmeststikstof\n(ureum, kalkammonsalpeter) levert bij toediening directe\nammoniakemissie. Verlagen van de kunstmestgift — mogelijk doordat NLV\nvan veen al hoog is — verlaagt de veldemissie structureel.</p></li>\n</ul><p><strong>Stalemissie</strong></p><ul>\n<li><p><strong>Rantsoenmaatregelen.</strong> Verlaging van het\nruw-eiwitgehalte (RE) in het rantsoen verlaagt de ureum-excretie via\nurine — de primaire bron van stallucht-ammoniak. Op veen scoort\nweidegras al hoog in RE (hoge OEB); bijvoeding met laag OEB-krachtvoer\ncompenseert dit en verlaagt de TAN-excretie zonder productieverlie\n(Verloop et al., 2018).</p></li>\n<li><p><strong>Meer weidegang.</strong> Elke uur extra weidegang is een\nuur minder mest in de stal. Dit verlaagt de stalemissie direct en\nproportioneel.</p></li>\n<li><p><strong>Stalvloer en -systeem.</strong> Emissiearme vloeren\n(hellende vloer met giergoot, sleufvloer) verminderen het\ncontactoppervlak tussen urine en mest. Op bestaande bedrijven is dit\ndoorgaans alleen haalbaar bij nieuwbouw of renovatie.</p></li>\n<li><p><strong>Mest frequent afvoeren uit de stal.</strong> Hoe korter\nmest in de stal blijft, hoe minder ammoniak vervluchtigt. Bij bestaande\nstallen is dit te realiseren via frequentere mestschuif of vaker\nmixen.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN — RESULTATEN PROEFTUIN VEENWEIDEN</div><ul>\n<li><p><strong>25% reductie is haalbaar.</strong> Op basis van analyse\nvan de brede praktijk en de resultaten van tien voorloperbedrijven\nconcluderen Verloop et al. (2018) dat 25% reductie haalbaar is bij een\nstabiel melkproductieniveau.</p></li>\n<li><p><strong>Voorloperbedrijven: 13% stalemissie en 18% veldemissie\nreductie.</strong> De voorloperbedrijven in de Proeftuin realiseerden in\ndrie jaar tijd deze reducties. De totale bedrijfsemissie daalde 7% —\nminder dan per ha en per ton melk, doordat productie en areaal ook\ngroeiden.</p></li>\n<li><p><strong>Combinatie beweiden + rantsoen is het meest\neffectief.</strong> Van alle maatregelen geeft de combinatie van meer\nweidegang en rantsoenmaatregelen het grootste effect. Dit zijn ook de\nmaatregelen die boeren het meest direct zelf sturen.</p></li>\n<li><p><strong>Grote spreiding tussen bedrijven.</strong> Lage emissie\nis niet voorbehouden aan extensieve of beweide bedrijven: ook intensieve\nbedrijven en opstallers scoren soms laag. Er is geen one-size-fits-all;\nmaatwerk per bedrijf is de kern van de aanpak.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Ammoniakreductie is op elk veenweidebedrijf toepasbaar, maar de meest\neffectieve combinatie verschilt per bedrijfstype. Startpunt is de\nKringloopWijzer: die geeft de huidige stalemissie (kg/ton melk) en\nveldemissie (kg/ha) en toont waar de lekken het grootst zijn.\nVervolgens: rantsoen optimaliseren (laag OEB), weidegang maximaliseren,\nmesttoediening emissiearm maken. Stalmaatregelen zijn alleen relevant\nbij (ver)nieuwbouw.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: STIKSTOFKRAAN EERST</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Een veelgemaakte fout is het nemen van emissiemaatregelen zonder\ntegelijk de stikstofaanvoer te beperken. Als de stikstofkraan\nopenblijft, compenseert het bedrijf de gedichte lekken via andere\nemissieroutes. De effectiviteit van emissiemaatregelen hangt direct af\nvan het gelijktijdig verlagen van de totale stikstofstroom door het\nbedrijf (Verloop et al., 2018).</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Beweidingssystemen —</strong> Meer en langer beweiden is de\neffectiefste maatregel voor zowel stal- als veldemissie. Het\nbeweidingssysteem bepaalt hoeveel uren per dag de koe buiten is.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Stikstofbemesting —</strong> Minder kunstmest verlaagt de\nveldemissie direct. Op veen is het hoge NLV de reden waarom minder\nkunstmest mogelijk is zonder opbrengstverlies.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Eiwit van eigen land —</strong> Verlaging van het\nRE/VEM-gehalte in het rantsoen verlaagt TAN-excretie en daarmee\nstalemissie. EEL en ammoniakemissie zijn via het rantsoen direct aan\nelkaar gekoppeld.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Rijpadensysteem en licht materieel —</strong>\nSleepslangbemesting is tegelijk een emissie-arme aanwendingstechniek en\neen maatregel voor bodemstructuurbehoud — twee doelen met één\nmachine.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>Verloop, K., Verhoeff, T., Oenema, J., Hoving, I., Meerkerk,\nB., Huijsmans, J., Migchels, G., De Haan, M. en Van Eekeren, N.\n(2018).</strong> <em>Minder ammoniakemissie uit de melkveehouderij in\nhet veenweidegebied — 25% reductie een haalbaar doel.</em> Wageningen\nLivestock Research, Rapport 1129. https://doi.org/10.18174/462888</p>"}]},{"id":"toolbox-09-biodiversiteit","naam":"Biodiversiteit en landschap","introHtml":"<p>Biodiversiteit in het veenweidegebied staat niet los van de\nbedrijfsvoering — het is er een directe uitkomst van. Beweidingssysteem,\nmaaidatum, grondwaterstand, mestsoort en slootbeheer bepalen samen\nhoeveel insecten, weidevogels en planten er op het bedrijf voorkomen. De\nkomende bouwstenen werken dit per thema uit.</p><p>Biodiversiteit in het veenweidegebied staat niet los van de\nbedrijfsvoering — het is er een directe uitkomst van.</p>","maatregelen":[{"titel":"Weidevogelbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Weidevogelbeheer is het geheel van maatregelen dat gericht is op het\nbeschermen en bevorderen van broedende weidevogels — grutto, kievit,\ntureluur, scholekster, veldleeuwerik — en hun kuikens. In het\nveenweidegebied is dit een van de meest urgente biodiversiteitsopgaves:\ngruttopopulaties zijn in 40 jaar met meer dan 70% gedaald.\nWeidevogelbeheer is geen vrijblijvende maatregel maar een combinatie van\nverplichte en vrijwillige maatregelen die via ANLb worden\ngefinancierd.</p><div class=\"ts\">DE DRIE PIJLERS VAN WEIDEVOGELBEHEER</div><ul>\n<li><p><strong>Uitgestelde maaidatum.</strong> Het meest directe\nbeheerinstrument. Niet maaien voor 1, 8 of 15 juni geeft kuikens de kans\nvliegvlug te worden. Maar: onderzoek toont dat najaarsbeheer (maaien in\noktober om voorjaarsgroei te remmen) nauwelijks effect heeft op\nkuikengeschiktheid in het voorjaar. Op veengrond met intensief\nbemestingsverleden is het gras in mei ongeacht najaarsbeheer te zwaar\nvoor kuikens (Hoekstra et al., 2020).</p></li>\n<li><p><strong>Voorweiden.</strong> Vroeg in het voorjaar het perceel\nbegrazen tot een lagere grashoogte, zodat het gewas in de kuikenperiode\n(half mei–juni) opener en doordringbaarder is. Dit werkt beter dan\nnajaarsbeheer om kuikenland te creëren. Voorbeweiden verlaagt de\nopbrengst van de eerste snede met 12–20% maar verbetert de grasstructuur\nvoor weidevogels aanzienlijk (Rietberg et al., 2014; Hoekstra et al.,\n2020).</p></li>\n<li><p><strong>Nestbescherming en plas-dras.</strong> Individuele\nnestbescherming (nestcirkels), uitrasteren van slootkanten en aanleg van\nplas-dras zijn aanvullende maatregelen. Plas-dras (een watervoerende\ngreppel of vernatte plek) trekt grutto's en andere wadvogels aan als\ndrinkplek en foerageerlocatie voor kuikens. Dit is de directe link naar\ngreppelinfiltratie als weidevogelmaatregel.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Najaarsbeheer heeft nauwelijks effect.</strong> Op\nveengrond met een intensief bemestingsverleden is het gras op 13 mei al\nmeer dan 35 cm hoog en meer dan 90% dicht tot 20 cm — ongeacht het\ntoegepaste najaarsbeheer. Alleen voorweiden gaf een meetbaar lagere\ngrashoogte (29 cm) en een opener gewas (Hoekstra et al., 2020).</p></li>\n<li><p><strong>Wormen en insecten zijn niet de bottleneck.</strong> Op\nveengrond zijn regenwormen in ruime mate aanwezig (meer dan 600 per m²\nop 0–20 cm diepte in april). De beperking zit niet in het voedselaanbod\nmaar in de bereikbaarheid: een te dicht en te hoog gewas maakt het voor\nkuikens onmogelijk om effectief te foerageren (Hoekstra et al.,\n2020).</p></li>\n<li><p><strong>Slootkantbeheer is bepalend voor vlinders.</strong>\nPercelen die alleen gemaaid worden (geen beweiding) scoren beter voor\nnachtvlinders doordat slootkantvegetatie gespaard blijft. De zeldzame\nargusvlinder profiteert sterk van slootkantbeheer en de aanwezigheid van\nnectarplanten (Van Grunsven &amp; Van der Laan, 2024).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Weidevogelbeheer is via ANLb vergoedbaar op percelen die voldoen aan\nde gestelde eisen voor mozaïek-, plas-dras- en weidevogelpakketten. De\nmeest effectieve combinatie op veen: vroeg voorweiden + uitgestelde\nmaaidatum + nestcirkels + plas-dras op strategische locaties. Sommige\npercelen zijn structureel ongeschikt vanwege te hoge veebezetting of te\nintensief bemestingsverleden — op die percelen heeft weidevogelbeheer\nweinig effect.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Greppelinfiltratie —</strong> Een extreem vernatte greppel\nis plas-dras. De directe koppeling tussen water- en weidevogelbeheer\nmaakt greppelinfiltratie tot een weidevogelmaatregel zonder extra\ningreep.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Beweidingssystemen —</strong> Extensief roterend standweiden\nmet lage veebezetting geeft hogere grasstructuur dan kurzrasen en is de\nmeest weidevogelvriendelijke beweidingsvorm.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Maaibeheer —</strong> Maaidatum is de primaire sturingsknop.\nNajaarsbeheer werkt nauwelijks; voorweiden is effectiever.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Mestsoort en bodemorganische stof —</strong> Dikke fractie\nen ruige mest stimuleren bodemleven en strooiselbewonende regenwormen —\ndirect voedsel voor weidevogelpullen.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Hoekstra, N., De Wit, J. en Van Eekeren, N. (2020).</strong>\n<em>Najaarsbeheer: weinig effect voor weidevogel.</em> V-focus, november\n2020, pp. 32–35. Louis Bolk Instituut.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/najaarsbeheer-weinig-effect-voor-weidevogel.pdf</p><p><strong>Van Grunsven, R.H.A. en Van der Laan, A. (2024).</strong>\n<em>Veenweidevernatting en insecten.</em> De Vlinderstichting, rapport\nVS2024.013, Wageningen, maart 2024.\nhttps://assets.vlinderstichting.nl/docs/d7a59b0f-4fba-495c-9b87-674a8ccc82e8.pdf</p>"},{"titel":"Insectenbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Insectenbeheer omvat maatregelen die gericht zijn op het beschermen\nen bevorderen van insecten op het melkveebedrijf. Insecten zijn\nessentieel als voedsel voor weidevogelpullen (grote insecten &gt;5 mm),\nals bestuivers van kruiden en bloeiende planten, en als onderdeel van de\nvoedselketen. Op melkveebedrijven vormen mestfauna (kevers, vliegen,\nwormen in mestflatten) en bloembezoekende insecten de twee meest directe\ngroepen.</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Vernatting bevordert libellen maar niet terrestrische\ninsecten.</strong> Op vernatte percelen (GWS −20 cm) zijn 2,4× zoveel\nlibellen aangetroffen als op niet-vernatte percelen. Voor vlinders en\nnachtvlinders was er geen effect van vernatting — dat effect wordt meer\nbepaald door beheer (maaien vs. beweiden) dan door waterpeil (Van\nGrunsven &amp; Van der Laan, 2024).</p></li>\n<li><p><strong>Slootkantbeheer is bepalend voor vlinders.</strong>\nPercelen die alleen gemaaid worden scoren beter voor nachtvlinders\ndoordat slootkantvegetatie gespaard blijft. De argusvlinder profiteert\nvan nectarplanten langs slootkanten en bosjes op het bedrijf (Van\nGrunsven &amp; Van der Laan, 2024).</p></li>\n<li><p><strong>Pesticiden in voer en mest zijn een serieuze bedreiging\nvoor mestfauna.</strong> Op acht melkveebedrijven in het\nHollands-Utrechtse veenweidegebied werden in alle voedermiddelen\nresiduen van gewasbeschermingsmiddelen aangetroffen (8–50 verschillende\nresiduen per bedrijf). Deze komen via de mest terecht in de\nweidemestflatten en hebben een negatief effect op mestkevers en vliegen.\nMet name deltamethrin en cypermethrin zijn toxisch voor mestfauna.\nBiologisch krachtvoer bevatte minder residuen maar was niet vrij van\ngewasbeschermingsmiddelen (Bruinenberg &amp; Van Eekeren,\n2023).</p></li>\n<li><p><strong>Krachtvoer en bijproducten zijn de grootste\npesticidendragers.</strong> In ruwvoer (gras, graskuil) zaten beduidend\nminder residuen dan in krachtvoer en bijproducten zoals bierbostel en\ngerst. Dit is een directe aanleiding om te sturen op herkomst en\nsamenstelling van krachtvoer bij insectenbeheer als doelstelling\n(Bruinenberg &amp; Van Eekeren, 2023).</p></li>\n<li><p><strong>Onbemest grasland is ongunstig voor insecten.</strong>\nWeidevogelgrasland dat volledig onbemest is gelaten heeft minder grote\ninsecten (&gt;5 mm) dan bemest grasland. Dikke fractie, ruige mest en\ndrijfmest geven meer grote insecten dan kunstmest en onbemeste controle\n— met dikke fractie als beste (Deru &amp; Van Eekeren, 2016).</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Insectenbeheer is op elk bedrijf te verbeteren door: (1) keuze van\nmestsoort (dikke fractie i.p.v. drijfmest op weidevogelgrasland); (2)\nvermindering van pesticiden in het rantsoen via keuze krachtvoer en\nbijproducten; (3) behoud van slootkantvegetatie en nectarplanten via\nterughoudend oeverbeheer; (4) combinatie van maaien en beweiden per\nperceel differentiëren i.p.v. overal hetzelfde schema.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: PESTICIDEN VIA RANTSOEN ZIJN EEN BLINDE\nVLEK</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>De meeste melkveehouders weten niet hoeveel pesticiden hun koeien\nvia het rantsoen binnenkrijgen. Krachtvoer uit gangbare akkerbouw bevat\nstructureel residuen van fungiciden, insecticiden en herbiciden die via\nde mest in de weidemestflatten terechtkomen. Dit is geen bewuste keuze\nmaar een systeemeffect. De enige directe sturingsvariabele voor de boer\nis de keuze van krachtvoer en bijproducten — biologisch krachtvoer bevat\nminder residuen maar is duurder en ook niet vrij van residuen\n(Bruinenberg &amp; Van Eekeren, 2023).</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Weidevogelbeheer —</strong> Grote insecten zijn het primaire\nvoedsel voor weidevogelpullen. Insectenbeheer en weidevogelbeheer zijn\nonlosmakelijk verbonden.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Mestsoort en bodemorganische stof —</strong> Dikke fractie\ngeeft meer mestfauna dan drijfmest. De mestsoort is een directe\nsturingsvariabele voor insecten.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Slootmaaibeheer en oeverbeheer —</strong> Slootkantvegetatie\nmet bloeiende kruiden is een habitat voor nectarzoekende insecten.\nTerughoudend beheer van slootkanten is de simpelste\ninsectenmaatregel.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Rantsoen en eiwit van eigen land —</strong> Minder aankoop\nvan krachtvoer van buitenaf betekent minder pesticideninput via het\nrantsoen — een indirect maar reëel effect.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Bruinenberg, M. en Van Eekeren, N. (2023).</strong>\n<em>Residuen van gewasbeschermingsmiddelen in het rantsoen van\nmelkkoeien: effect op mestfauna.</em> V-focus, maart 2023, pp. 24–27.\nLouis Bolk Instituut.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/residuen-van-gewasbeschermingsmiddelen-het-rantsoen-van-melkkoeien-effect-op-mestfauna.pdf</p><p><strong>Van Grunsven, R.H.A. en Van der Laan, A. (2024).</strong>\n<em>Veenweidevernatting en insecten.</em> De Vlinderstichting, rapport\nVS2024.013, Wageningen, maart 2024.\nhttps://assets.vlinderstichting.nl/docs/d7a59b0f-4fba-495c-9b87-674a8ccc82e8.pdf</p>"},{"titel":"Mozaïekbeheer","html":"<div class=\"ts\">WAT HET IS</div><p>Mozaïekbeheer is het afstemmen van beheersmaatregelen — maaidatum,\nbeweidingsintensiteit, plas-dras, kruidenrijkdom — op perceelsniveau\nzodat in een gebied een gevarieerd landschapspatroon ontstaat met open\nen dicht grasland, natte en droge plekken, en kort en lang gras naast\nelkaar. Het principe is dat weidevogels voor verschillende levensfasen\n(broeden, foerageren, kuikens opvoeden) verschillende omstandigheden\nnodig hebben die niet op één perceel tegelijk aanwezig kunnen zijn.\nMozaïekbeheer organiseert die variatie ruimtelijk over meerdere percelen\nen bij voorkeur over meerdere bedrijven in een gebied (Oosterveld et\nal., 2008; Van Eekeren et al., 2022).</p><div class=\"ts\">WAT HET DOET</div><p>Een goed mozaïek biedt grutto, kievit en tureluur een volledig\nleefgebied binnen bereikbare afstand:</p><ul>\n<li><p><strong>Nestpercelen:</strong> lang gras of kruidenrijke percelen\nmet dekking voor de broedende vogel, uitgestelde maaidatum.</p></li>\n<li><p><strong>Kuikenland:</strong> korte, open grasvegetatie met\nzichtbaarheid en bereikbare bodemfauna. Dit is de kritieke schakel:\nonvoldoende kuikenland is de meest genoemde reden voor gruttoverlies\n(Oosterveld et al., 2008).</p></li>\n<li><p><strong>Foerageergebied:</strong> plas-dras, natte greppelranden\nen slootkanten met modderige randen voor volwassen vogels en\nkuikens.</p></li>\n<li><p><strong>Rust- en vluchtzones:</strong> percelen zonder verstoring\ndoor vee of machines in de broedperiode.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Kuikenland is de bottleneck.</strong> Analyse van\nmeerdere mozaïekbeheerprojecten toont dat in 17 van 20 gebieden de\nbenodigde oppervlakte kuikenland wél werd gerealiseerd, maar\nreproductiesucces uitbleef. Externe factoren — predatie en\nongestoordheid — bleken zelfstandig bepalend naast het beheer\n(Oosterveld et al., 2008).</p></li>\n<li><p><strong>Meer kuikenland dan de norm is nodig.</strong> Het\nproject Nederland-Gruttoland wees uit dat voor toereikende reproductie\nméér kuikenland gerealiseerd moet worden dan de indertijd gebruikte norm\nvan 0,7 ha per broedpaar. De huidige richtlijn ligt op 1,4 ha kuikenland\nper gruttobroedpaar (Schotman et al., 2008).</p></li>\n<li><p><strong>Jaareffect 2006: open structuur in mei is de\nsleutel.</strong> Een groot deel van het reproductiesucces in de\nonderzochte gebieden bleek gerealiseerd in 2006, toen laat maaien en\ntrage grasgroei samen een open graslandstructuur gaven in de tweede\nhelft van mei. Dit bevestigt dat de combinatie van uitgesteld maaien én\nlage bemesting op kuikenlandpercelen het meest effectief is (Oosterveld\net al., 2008).</p></li>\n<li><p><strong>Situering van het beheer doet ertoe.</strong> Het\ngrutto-mozaïekmodel (Schotman et al., 2008) toont dat ruimtelijke\nsamenhang — percelen dicht bij nesten van gruttobroedparen — een derde\nvan de variatie in reproductie verklaart. Een goed mozaïek op de\nverkeerde locatie helpt nauwelijks.</p></li>\n<li><p><strong>Voorbeweiden als kuikenlandmaatregel.</strong>\nVoorbeweiden in het vroege voorjaar is effectiever dan najaarsbeheer om\nopen kuikenland te creëren in mei. Dit is op veen extra relevant omdat\ngras hier van nature snel en dicht groeit (Van Eekeren et al., 2022;\nHoekstra et al., 2020).</p></li>\n<li><p><strong>Collectieve aanpak is voorwaarde.</strong> Eén boer die\nmozaïekbeheer toepast heeft beperkt effect als de buren intensief\nmaaien. Mozaïekbeheer werkt alleen als meerdere bedrijven in een gebied\nsamenwerken via een agrarisch collectief (Van Eekeren et al.,\n2022).</p></li>\n</ul><div class=\"ts\">BEDRIJFSMATIGE INPASBAARHEID</div><p>Mozaïekbeheer levert in de praktijk drie knelpunten op die\ninpasbaarheid beperken: (1) de gewenste oppervlakte plas-dras is\nmoeilijk inpasbaar op één bedrijf — samenwerking met een aanpalend\nnatuurgebied of boeren is dan de route; (2) meer dan 20% van de\nbedrijfsoppervlakte laat maaien botst met voederwinningsdoelen; (3)\nmaaitrappen realiseren in de eerste snede vraagt een weerrisico dat\npsychologisch gevoelig ligt bij boeren (Oosterveld et al., 2008).\nANLb-vergoedingen zijn bedoeld om dit weerrisico en het inkomensverlies\nte compenseren.</p><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Mozaïekbeheer is toepasbaar op bedrijven die deelnemen aan een\nagrarisch collectief met ANLb-weidevogelpakketten. Het vereist een\ngebiedsgerichte aanpak waarbij de situering van het beheer wordt\nafgestemd op de werkelijke nestlocaties van grutto en kievit. Het\ngrutto-mozaïekmodel (bereikbaar via internet) biedt een praktisch\nhulpmiddel voor planning en evaluatie van het beheer per week (Schotman\net al., 2008).</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Weidevogelbeheer —</strong> Mozaïekbeheer is de\ngebiedsschaal waarop weidevogelbeheer werkt. Individuele maatregelen\n(uitgestelde maaidatum, nestcirkels, plas-dras) zijn bouwstenen van het\nmozaïek.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Beweidingssystemen —</strong> Voorbeweiden als\nkuikenlandmaatregel is direct inpasbaar in RSW en kurzrasen. Extensief\nRSW met lage veebezetting geeft de meest weidevogelvriendelijke\ngrasstructuur.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Greppelinfiltratie —</strong> Watervoerende greppels en\nplas-dras zijn de natte component van het mozaïek. Greppelinfiltratie\nmaakt plas-dras-achtige omstandigheden structureel beschikbaar.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Maaibeheer —</strong> De maaidatum is de primaire\nsturingsknop voor het mozaïek. Niet elk perceel hoeft dezelfde datum te\nhebben — perceelsgerichte maaiplanning IS mozaïekbeheer.</td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Oosterveld, E.B., Terwan, P. en Guldemond, J.A.\n(2008).</strong> <em>Mozaïekbeheer voor weidevogels: evaluatie en\nmogelijkheden voor optimalisering.</em> Altenburg &amp; Wymenga / CLM,\nin opdracht van Kenniskring Weidevogellandschap.\nhttps://www.boerenlandvogelsnederland.nl/Uploaded_files/Naslagwerk/aenw-clm-bt-rapport-evaluatie-en-optimalisering-mozaiekbeheer.b38a97.pdf</p><p><strong>Schotman, A.G.M., Melman, Th.C.P., Hensen, S.R., Kiers, M.A.,\nMeeuwsen, H.A.M., Roosenschoon, O.R. en Vanmeulebrouk, B.\n(2008).</strong> <em>Het Grutto-mozaïekmodel als kwaliteittoets\nweidevogelbeheer — ontwikkeling en toepassingen 2004–2008.</em>\nAlterra-rapport 1408, Wageningen University &amp; Research.\nhttps://edepot.wur.nl/3870</p><p><strong>Van Eekeren, N., De Wit, J., Versteeg, C., Hoekstra, N.,\nPijlman, J. e.a. (2022).</strong> <em>Winst &amp; Weidevogels —\nweidemaatregelen voor (functionele agro-)biodiversiteit.</em> Louis Bolk\nInstituut, publicatienummer 2022-015LbD.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/winst-weidevogels.pdf</p>"},{"titel":"Landschapselementen onderhouden","html":"<div class=\"ts\">WAT HET IS</div><p>Landschapselementen zijn de houtige en natte kleinschalige elementen\ndie het veenweidelandschap karakter geven en tegelijk essentiële\necologische functies vervullen: geriefhoutbosjes, knotbomen en\nknotbomenrijen, singels, elzensingels, grienden, poelen en kleine\nrietpercelen. Ze zijn van oudsher aanwezig in het veenweidegebied maar\nsterk afgenomen door ruilverkaveling, schaalvergroting en gebrek aan\nonderhoud. Behoud en herstel van deze elementen is een Niveau\n1-maatregel: het vraagt geen nieuw verdienmodel maar wel actief\nonderhoud en kennis van de beheerseisen.</p><div class=\"ts\">DE VEENWEIDESPECIFIEKE ELEMENTEN</div><ul>\n<li><p><strong>Geriefhoutbosjes.</strong> Kleine aangeplante bosjes\n(doorgaans &lt;150 m²) te midden van weilanden, karakteristiek voor\nUtrecht-West en de Krimpenerwaard. Van oudsher geplant op natte,\nonproductieve plekken — juist op veen dus ideale locaties. Beheer:\nhakhout afzetten eens per 10–15 jaar, gefaseerd. Het afzetten geeft\nvariatie in leeftijd en structuur, wat de waarde voor vogels en insecten\nverhoogt (Landschap Erfgoed Utrecht, 2022).</p></li>\n<li><p><strong>Knotbomen en knotbomenrijen.</strong> Langs slootkanten\nen perceel- en wegkanten. Knotbomen worden periodiek geknot (eens per\n3–6 jaar), waardoor een karakteristieke vorm en structuurrijkdom\nontstaat. Ze bieden nestgelegenheid voor zangvogels, steenuilen en\nvleermuizen. Beheer via ANLb-pakket 'Solitaire (knot)bomen' of 'Beheer\nvan bomenrijen'.</p></li>\n<li><p><strong>Elzensingels en grienden.</strong> Veenspecifieke houtige\nelementen op natte grond, bestaande uit zwarte els of wilg. Grienden\nworden cyclisch geoogst als hakhout. Elzensingels langs sloten zijn\nkarakteristiek voor het Hollandse veenweidelandschap en bieden\nhabitatdiversiteit voor broedvogels.</p></li>\n<li><p><strong>Poelen.</strong> Kleine ondiepe waterpartijen die\namfibieën, libellen en watervogels aantrekken. In het veenweidegebied\nzijn ze zeldzaam geworden. Aanleg en beheer via ANLb-pakket 'Poel en\nklein historisch water'. Combinatie met plas-dras is mogelijk.</p></li>\n<li><p><strong>Rietkragen en kleine rietpercelen.</strong> Langs\nslootkanten en op natte hoeken. Riet biedt dekking voor broedvogels\n(rietzanger, rietgors), filtert nutriënten uit het slootwater en\nversterkt de oeverstabiliteit. Beheer via ANLb-pakket 'Rietzoom en klein\nrietperceel'.</p></li>\n</ul><div class=\"ts\">FUNCTIE IN HET LANDSCHAP</div><p>Landschapselementen vervullen meerdere functies tegelijk:</p><ul>\n<li><p><strong>Biodiversiteit:</strong> schuilplaats, nestgelegenheid,\nvoedsel en overwinteringshabitat voor zangvogels, uilen, vleermuizen,\namfibieën en insecten.</p></li>\n<li><p><strong>Landschapskarakter:</strong> de openheid van het\nveenweidelandschap wordt bepaald door de juiste maat van houtige\nelementen — niet te veel, niet te weinig. Geriefhoutbosjes en\nknotbomenrijen zijn visuele ankers in het open polderlandschap.</p></li>\n<li><p><strong>Predatiedruk weidevogels.</strong> Opgaand hout trekt\nroofvogels en kraaiachtigen aan en kan daarmee de predatiedruk op\nweidevogelnesten verhogen. De locatie van landschapselementen ten\nopzichte van weidevogelkerngebieden is daarmee een expliciete\nafweging.</p></li>\n<li><p><strong>Klimaatadaptatie en CO₂-opslag:</strong> houtige\nelementen leggen koolstof vast en bieden schaduw en luwte bij extremere\nweersomstandigheden.</p></li>\n</ul><div class=\"ts\">ANLb EN VERGOEDINGEN</div><p>Landschapselementen worden beheerd via het ANLb-spoor 'Dooradering'\n(ook wel: groenblauwe dooradering). De dooraderingspakketten zijn\nregionaal georganiseerd via agrarische collectieven. In het\nveenweidegebied zijn relevante collectieven onder meer: Rijn, Vecht en\nVenen, Lopikerwaard, Alblasserwaard/Vijfheerenlanden en de Utrechtse\ncollectieven. Relevante pakketten (Boerennatuur 2025; Rijn, Vecht en\nVenen, 2026):</p><ul>\n<li><p>Pakket 20 — Hakhoutbeheer; Pakket 27 — Hakhoutbosje en\ngriendje</p></li>\n<li><p>Pakket 21 — Beheer van bomenrijen; Pakket 25 — Solitaire\n(knot)bomen</p></li>\n<li><p>Pakket 9 — Poel en klein historisch water; Pakket 11 — Rietzoom\nen klein rietperceel</p></li>\n<li><p>Pakket 28 — Griendje; Pakket 29 — Bosje</p></li>\n</ul><p>Naast ANLb zijn er provinciale regelingen voor aanleg en herstel van\nkleine landschapselementen via het Platform Groenblauwe Dooradering.\nAanleg kan worden gesubsidieerd; beheer daarna via ANLb.</p><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Op elk veenweidebedrijf waar al landschapselementen aanwezig zijn:\ninstandhouding begint met periodiek beheer (knotbomen: knotten, hakhout:\nafzetten, poelen: uitbaggeren). Nieuw aanleggen is mogelijk op natte,\nweinig productieve hoeken van percelen — klassiek de locatie van het\ngeriefhoutbosje. Afstemming met het agrarisch collectief is de eerste\nstap: zij begeleiden de ANLb-aanvraag en weten welke locaties kansrijk\nzijn in de gebiedskaart.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>AANDACHTSPUNT: LOCATIE TEN OPZICHTE VAN\nWEIDEVOGELKERNGEBIEDEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td>Opgaand hout verhoogt de predatiedruk op weidevogelnesten in de\ndirecte omgeving. In weidevogelkerngebieden is de locatie van\ngeriefhoutbosjes en bomenrijen daarmee een expliciete afweging:\nbiodiversiteitswinst voor de ene soortgroep kan ten koste gaan van de\nandere. Overleg met het agrarisch collectief en de weidevogelcoördinator\nis essentieel bij nieuwe aanplant.</td>\n</tr>\n</tbody>\n</table><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Weidevogelbeheer —</strong> Locatie van landschapselementen\nten opzichte van nestelende grutto's en kieviten is een bewuste keuze.\nRietkragen langs slootkanten verhogen de dekking; bosjes verhogen de\npredatiedruk.</td>\n</tr>\n<tr class=\"even\">\n<td><strong>Insectenbeheer —</strong> Bloeiende houtige elementen\n(meidoorn, vlier, wilg) zijn nectarbronnen voor bestuivers. Knotbomen en\nhakhout creëren dood hout als habitat voor houtbewonende insecten.</td>\n</tr>\n<tr class=\"odd\">\n<td><strong>Mozaïekbeheer —</strong> Landschapselementen zijn\nstructurele onderdelen van het ruimtelijke mozaïek. De combinatie van\nopen kuikenland, natte greppels en kleine bosjes geeft het maximale\neffect voor biodiversiteit.</td>\n</tr>\n</tbody>\n</table><blockquote>\n\n</blockquote>","lit":"<p><strong>Landschap Erfgoed Utrecht (2022).</strong> <em>Factsheet\ngeriefhoutbosje — Plan Boom uitdeelactie.</em> Landschap Erfgoed Utrecht\n/ Natuur en Milieufederaties.\nhttps://www.landschaperfgoedutrecht.nl/media/8981/factsheet-geriefhoutbosje.pdf</p><p><strong>Boerennatuur Rijn, Vecht en Venen (2026).</strong>\n<em>Beheerpakketten Agrarisch Natuur- en Landschapsbeheer — beheerjaar\n2023–2028.</em> Collectief Rijn, Vecht en Venen.\nhttps://www.rijnvechtenvenen.nl/assets/uploads/files/ANLb2023/Pakkettenboek%20RVV%202026.pdf</p><p><strong>Boerennatuur Nederland (2025).</strong> <em>Overzicht\nBeheerpakketten Agrarisch Natuur &amp; Landschapsbeheer, versie\n2025.</em> BoerenNatuur.\nhttps://boerennatuur.nl/wp-content/uploads/2025/01/Beheerpakketten2025-website.pdf</p>"}]},{"id":"toolbox-10-energie","naam":"Mechanisatie en energie","introHtml":"<p>Energie is op het melkveebedrijf zowel een kostenpost als een\nduurzaamheidsopgave. Op veenweidebedrijven is het energieverbruik\nstructureel verdeeld over stroom (melken, koelen, verlichting) en diesel\n(maaien, bemesten, transport). Verduurzaming van energie vraagt twee\nparallelle stappen: eerst efficiëntie verhogen en verbruik verschuiven\nvan fossiel naar elektrisch, dan eigen hernieuwbare energie opwekken om\nhet verschoven verbruik te dekken.</p>","maatregelen":[{"titel":"Elektrificatie","html":"<div class=\"ts\">WAT HET IS</div><p>Elektrificatie is het vervangen van processen die nu draaien op\ndiesel of aardgas door elektrisch aangedreven equivalenten. Op een\nmelkveebedrijf is 35% van het totale energieverbruik stroom en 65%\ndiesel. Die verhouding biedt kansen: de stalprocessen en\nerfwerkzaamheden zijn goed te elektrificeren; het zware veldwerk\n(maaien, bemesten) is lastiger (Dekking &amp; Van der Voort, 2025).</p><p><strong>KANSRIJKE ELEKTRIFICATIEROUTES OP HET\nMELKVEEBEDRIJF</strong></p><ul>\n<li><p><strong>Elektrische boilers voor waterverwarming.</strong>\nWaterverwarming voor melkreiniging verbruikt een aanzienlijk deel van\nhet gasgebruik. Een elektrische boiler gekoppeld aan eigen zonnestroom\nverhoogt het zelfverbruik van opgewekte energie sterk — zeker als de\nboiler 's middags warm water aanmaakt op het moment van piekvoltage van\nde zonnepanelen (Ruitenberg et al., 2020).</p></li>\n<li><p><strong>Elektrische voersystemen.</strong> Elektrische\nvoermengwagens en voerschuiven zijn beschikbaar en geschikt voor\nkoppeling aan eigen stroomproductie. Het grote voordeel: voeren kan op\nvariabele tijdstippen worden gepland, wat inpassing van zonne-energie in\nhet dagprofiel vergemakkelijkt (Ruitenberg et al., 2020).</p></li>\n<li><p><strong>Elektrische shovel of compact loader.</strong> Voor\nmestschuiven en lichte erfwerkzaamheden zijn elektrische shovels\nbeschikbaar. Ze lenen zich goed voor eigen stroomgebruik doordat het\noplaadmoment flexibel is. Zware shovels voor mestopslag en\nbulkwerkzaamheden zijn minder eenvoudig te elektrificeren.</p></li>\n<li><p><strong>IJswaterkoeling voor melkkoeling.</strong>\nIJswaterkoeling koelt de melk snel en verbruikt elektriciteit op\nflexibele momenten — 's nachts of overdag bij piekproductie van\nzonnestroom. Dit kan het eigen stroomverbruik sterk verhogen (Ruitenberg\net al., 2020).</p></li>\n<li><p><strong>Lichte veldwerktuigen.</strong> Elektrische kleine\ntractoren voor perceelsinspectie, graslandbeheer op kleine schaal en\nslootonderhoud zijn beschikbaar. Zware trekkers voor maaien, schudden en\ninkuilen zijn technisch nog niet rendabel te elektrificeren op grotere\nschaal.</p></li>\n</ul><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Erfsprocessen zijn het meest kansrijk.</strong> Op een\nmelkveebedrijf vindt een relatief groot deel van het energieverbruik op\nhet erf plaats. De mogelijkheden van elektrificatie zijn daardoor groter\ndan op een akkerbouwbedrijf (Dekking &amp; Van der Voort,\n2025).</p></li>\n<li><p><strong>Eigen stroomproductie en elektrificatie versterken\nelkaar.</strong> Als het elektriciteitsnet overbelast is of saldering\nafgebouwd wordt, verhoogt elektrificatie het directe zelfverbruik van\nopgewekte stroom. Dit verbetert de terugverdientijd van zonnepanelen en\nmaakt het bedrijf minder afhankelijk van het net (Ruitenberg et al.,\n2020).</p></li>\n<li><p><strong>CO₂-besparing afhankelijk van stroommix.</strong>\nElektrificatie verlaagt de CO₂-uitstoot alleen als de opgewekte of\ngebruikte stroom hernieuwbaar is. Bij grijze stroom is de CO₂-balans\nminder gunstig dan bij diesel. Koppeling aan eigen zonne- of windenergie\nis daarmee de voorwaarde voor echte verduurzaming.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Elektrificatie loont het meest bij vervanging van bestaande\napparatuur (einde levensduur) of bij nieuwbouw. Waterverwarming en\nmelkkoeling zijn direct aanpasbaar; elektrische shovels en voersystemen\nvragen een gerichte investering. Begin met de processen met het hoogste\nfossiele verbruik en de beste aansluiting op eigen stroomproductie.</p>","lit":"<p><strong>Dekking, A. en Van der Voort, M. (2025).</strong>\n<em>Energiegebruik in de melkveehouderij — factsheet KOM Landbouw nr.\n8.</em> Wageningen Research, juni 2025. https://edepot.wur.nl/706159</p><p><strong>Ruitenberg, G., Van Well, E. en Veefkind, W. (2020).</strong>\n<em>Rapportage 'Elektrificatie op het boerenerf' (AGRO18013).</em>\nRuitenberg Advies / CLM / LTO Noord, juni 2020.\nhttps://cdn.nieuweoogst.nu/public/file/177327.pdf</p>"},{"titel":"Eigen energieopwekking","html":"<div class=\"ts\">WAT HET IS</div><p>Eigen energieopwekking is het produceren van hernieuwbare energie op\nhet eigen bedrijf — primair via zonnepanelen op stal- en erfdaken, en\neventueel aangevuld met een kleine windturbine. Zelfvoorzienend worden\nqua energie is voor veel melkveehouders een ideaalbeeld. Hoe realistisch\ndat is hangt af van de verhouding tussen productie en verbruik op\njaarbasis, en van de seizoensonbalans die dat veroorzaakt (Dekking &amp;\nVan der Voort, 2025).</p><div class=\"ts\">WAT WE WETEN</div><ul>\n<li><p><strong>Zon en wind vullen elkaar goed aan.</strong> Zonnepanelen\nproduceren het meest in de zomer; een kleine windturbine produceert het\nmeest in de winter. Op jaarbasis is de combinatie goed dekkend — maar er\nblijft onbalans per week en seizoen (Dekking &amp; Van der Voort,\n2025).</p></li>\n<li><p><strong>250 zonnepanelen + kleine windmolen = energieneutraal op\npapier.</strong> Voor een modelbedrijf van 55 ha, 100 melkkoeien is de\ncombinatie van 250 zonnepanelen (350 Wp) en een kleine windmolen (50 kW)\nvoldoende om het totale energieverbruik (492.000 MJ/jaar) op jaarbasis\nte dekken. Maar dit is een jaarsaldo — in de praktijk is er perioden van\noverschot en perioden van tekort (Dekking &amp; Van der Voort,\n2025).</p></li>\n<li><p><strong>65% van het energieverbruik is diesel.</strong>\nZonnepanelen en windmolens wekken elektriciteit op, niet diesel. Zolang\nhet veldwerk op diesel draait, kan elektriciteitsopwekking alleen het\nstroomverbruik (35%) verduurzamen, niet de totale energiebehoefte.\nElektrificatie van erfprocessen is de sleutel om meer van de eigen\nstroom te benutten.</p></li>\n<li><p><strong>Opslag of flexibel verbruik is noodzakelijk.</strong>\nVoor echt off-grid gebruik is energieopslag (batterij) of\nwaterstofproductie nodig. Batterijopslag is beschikbaar maar duur;\nwaterstof op bedrijfsniveau is nog in ontwikkeling. Slim plannen van\nflexibele processen (boiler, voersysteem, koeling) is de goedkopere\nroute (Ruitenberg et al., 2020).</p></li>\n<li><p><strong>Netcongestie en afbouw saldering.</strong> Het\nelektriciteitsnet is op veel plekken overbelast. Dit beperkt\nteruglevering en vermindert de waarde van niet-zelfverbruikte stroom.\nAfbouw van de salderingsregeling versterkt dit effect. Eigen verbruik\nverhogen via elektrificatie is daarmee ook financieel aantrekkelijker\ngeworden.</p></li>\n</ul><div class=\"ts\">WANNEER TOEPASBAAR</div><p>Zonnepanelen op staldaken zijn op vrijwel elk bedrijf toepasbaar en\nhebben een bewezen terugverdientijd. Een kleine windturbine vraagt een\nvergunning en is niet overal inpasbaar in het landschap — in het open\nveenweidelandschap stuit dit soms op ruimtelijke bezwaren. Begin met het\nin kaart brengen van het eigen energieprofiel (verbruik per uur, per\ndag, per seizoen) voordat gekozen wordt voor een productiesysteem en\nopslagoplossing.</p><table>\n<colgroup>\n<col style=\"width: 100%\">\n</colgroup>\n<thead>\n<tr class=\"header\">\n<th><strong>RELATIE MET ANDERE BOUWSTENEN</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td><strong>Elektrificatie werktuigen —</strong> Eigen energieopwekking\nen elektrificatie zijn communicerende vaten: meer eigen stroom maakt\nelektrificatie aantrekkelijker; meer elektrificatie verhoogt het\nzelfverbruik van opgewekte stroom.</td>\n</tr>\n<tr class=\"even\">\n<td></td>\n</tr>\n</tbody>\n</table>","lit":"<p><strong>Dekking, A. en Van der Voort, M. (2025).</strong>\n<em>Energiegebruik in de melkveehouderij — factsheet KOM Landbouw nr.\n8.</em> Wageningen Research, juni 2025. https://edepot.wur.nl/706159</p><p><strong>Ruitenberg, G., Van Well, E. en Veefkind, W. (2020).</strong>\n<em>Rapportage 'Elektrificatie op het boerenerf' (AGRO18013).</em>\nRuitenberg Advies / CLM / LTO Noord, juni 2020.\nhttps://cdn.nieuweoogst.nu/public/file/177327.pdf</p>"}]}],"overigeLiteratuur":[{"titel":"Bufferstroken","html":"<p><strong>RVO (2023).</strong> <em>Bufferstroken 2023 — verplichte\nbufferstroken langs waterlopen.</em> Rijksdienst voor Ondernemend\nNederland. https://www.rvo.nl/onderwerpen/bufferstroken-2023</p><p><strong>WUR / Koeien &amp; Kansen (2024).</strong> <em>Bufferstroken\nbeperken afspoeling naar oppervlaktewater.</em> Wageningen Livestock\nResearch.\nhttps://www.wur.nl/nl/onderzoek-resultaten/onderzoeksinstituten/livestock-research/show-wlr/bufferstroken-beperken-afspoeling-naar-oppervlaktewater.htm</p><p><strong>STOWA (2022).</strong> <em>Deltafact — effectiviteit\nnutriëntenmaatregelen om uit- en afspoeling vanuit landbouwgronden te\nverminderen.</em> Stichting Toegepast Onderzoek Waterbeheer.\nhttps://www.stowa.nl/deltafacts/waterkwaliteit/kennisimpuls-waterkwaliteit/effectiviteit-nutrientenmaatregelen-om-uit-en</p><p><strong>DAW (2026).</strong> <em>Aanleg en beheer van droge en natte\nbufferstroken.</em> Deltaplan Agrarisch Waterbeheer.\nhttps://agrarischwaterbeheer.nl/maatregel/aanleg-en-beheer-van-droge-en-natte-bufferstroken/</p>"},{"titel":"Kruidenrijk productief\ngrasland","html":"<p><strong>Pijlman, J. en Van Eekeren, N. (2020).</strong> <em>Ervaring\nmet smalle weegbree in veenweiden.</em> V-focus, november 2020, pp.\n28–31. Louis Bolk Instituut / KTC Zegveld.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/ervaring-met-smalle-weegbree-veenweiden.pdf</p><p><strong>LBI / Veenweide Fryslân (2024).</strong> <em>Factsheet\nkruidenrijk grasland in het veenweidegebied in Fryslân.</em> Louis Bolk\nInstituut, project Integrale Bodemverbetering Feangreiden.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/factsheet-kruidenrijk-grasland-het-veenweidegebied-fryslan.pdf</p><p><strong>Proeftuin Krimpenerwaard / LBI (2021).</strong>\n<em>Weidebuffet met kruiden — doorzaaiproef en screenen van\ngraskruidenmengsels voor veenweiden.</em> Proeftuin Trots op de\nKrimpenerwaard.\nhttps://proeftuinkrimpenerwaard.nl/weidebuffet-met-kruiden/</p><p><strong>Pijlman, J., Roelen, S. en Van Eekeren, N. (2020).</strong>\n<em>Klimaatmaatregelen in het veenweidegebied in relatie tot\nbiodiversiteit, bodem- en waterkwaliteit — een inventarisatie van\neffecten.</em> Louis Bolk Instituut, publicatienummer 2020-036 LbD. In\nopdracht van ministerie LNV en STOWA.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/klimaatmaatregelen-het-veenweidegebied-relatie-tot-biodiversiteit-bodem-en-waterkwaliteit_0.pdf</p>"},{"titel":"Mestsoort en organische stof","html":"<p><strong>Deru, J. en Van Eekeren, N. (2016).</strong> <em>Dikke\nfractie gescheiden drijfmest is alternatief voor ruige mest — mest voor\nweidevogelgebieden in veenweiden.</em> V-focus, april 2016, pp. 28–29.\nLouis Bolk Instituut / VIC.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/3117.pdf</p><p><strong>Van Eekeren, N., Deru, J., Lenssinck, F. en Bloem, J.\n(2016).</strong> <em>Bodemkwaliteit op veengrond — effecten van drie\nmaatregelen op een rij.</em> Louis Bolk Instituut, publicatienummer\n2016-013 LbD.\nhttps://www.louisbolk.nl/sites/default/files/publication/pdf/3119.pdf</p>"},{"titel":"Overkoepelend — Boeren op\nHoog Water","html":"<p><strong>Pijlman, J., Bestman, M., Blokland, P.W., Hoekstra, N.,\nHonkoop, W., Hoving, I., Thijssen, M. en Van Eekeren, N. (red.)\n(2025).</strong> <em>Living Lab Boeren op Hoog Water 2020–2024 —\neindrapportage.</em> VIC / Louis Bolk Instituut / WUR / PPP-Agro Advies\n/ KTC Zegveld, oktober 2025.\nhttps://vip-nl.nl/wp-content/uploads/Eindrapportage-Living-Lab-BoHW-2020-2024.pdf</p>"}]};